/* ── easing / интерполяция ── */
const lerp=(a,b,t)=>a+(b-a)*t;
const easeOut=t=>1-Math.pow(1-Math.min(1,Math.max(0,t)),3);
const easeIn=t=>{t=Math.min(1,Math.max(0,t));return t*t*t;};
const easeInOut=t=>{t=Math.min(1,Math.max(0,t));return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;};

export const G={scene:sceneGarage,grp:null,fx:null,ramp:null,rampG:null,rampMask:null,
  ringA:null,ringB:null,tank:null,px:0,py:0,dust:[],departFx:[],bigText:null,
  rotT:0,tRot:0,tCur:0,grpScale:1,localBottom:0,localL:200,
  departing:false,depart:null,arriving:false,arrive:null};

/* alias: resize-обработчик в screens.js зовёт старое имя layoutGarage */
export function layoutGarage(){ garageLayout(); }
export function garageLayout(){
  const W=innerWidth,H=innerHeight;
  const compact=('ontouchstart' in window)||Math.min(W,H)<700;
  const landscape=W>H;
  let L;
  if(!compact) L={colX:W-410,colY:66,colW:396,colH:H-66-92,prevX:Math.max(300,(W-430)/2),prevY:H*.54,grpScale:1,showBriefing:true};
  else if(landscape){const colW=Math.min(380,Math.round(W*.44));
    L={colX:W-colW-12,colY:60,colW,colH:H-60-70,prevX:(W-colW-12)/2,prevY:(H+52)/2,grpScale:.6,showBriefing:false};}
  else{const prevH=Math.min(300,Math.round(H*.36));
    L={colX:12,colY:52+prevH+8,colW:W-24,colH:H-(52+prevH+8)-64,prevX:W/2,prevY:52+prevH/2,grpScale:.52,showBriefing:false};}
  G.px=L.prevX;G.py=L.prevY;G.grpScale=L.grpScale;
  if(G.grp){G.grp.position.set(G.px,G.py);G.grp.scale.set(G.grpScale);}
  if(G.bigText)G.bigText.position.set(G.px,G.py);
  /* геометрия трапа в локальных координатах превью (центр 0,0; платформа R=190) */
  G.localBottom=(H+80-G.py)/Math.max(.01,G.grpScale);   // локальный Y, при котором центр танка за нижним краем
  G.localL=Math.max(60,G.localBottom-180);              // длина трапа от кромки платформы вниз
  buildRampG();
  if(!G.departing&&!G.arriving) setRampRevealed(0);
  return L;
}

/* трап рисуется один раз (в локальных координатах G.ramp, 0 = верх трапа) */
function buildRampG(){
  const g=G.rampG;if(!g)return;const L=G.localL;
  g.clear();
  g.beginFill(0x14181b);g.drawRect(-35,0,70,L);g.endFill();                 // полотно
  g.beginFill(0xffb020,.5);g.drawRect(-35,0,3,L);g.drawRect(32,0,3,L);g.endFill(); // янтарные кромки
  g.beginFill(0xffb020,.22);for(let y=8;y<L;y+=26)g.drawRect(-1.5,y,3,13);g.endFill(); // осевой пунктир
  g.lineStyle(2,0xffb020,.16);                                              // шевроны направления
  for(let y=18;y<L;y+=44){g.moveTo(-22,y);g.lineTo(0,y+12);g.lineTo(22,y);}
  g.lineStyle(0);
  g.beginFill(0x262d31);g.drawRect(-38,-6,76,8);g.endFill();                 // стык с платформой
}
/* маска трапа: открывает полотно сверху вниз на rev пикселей (локальных) */
function setRampRevealed(rev){
  const m=G.rampMask;if(!m)return;m.clear();
  if(rev>0){m.beginFill(0xffffff);m.drawRect(-40,-8,80,Math.min(rev,G.localL)+8);m.endFill();}
}

function mkRing(r,color,segs){
  const g=new PIXI.Graphics();g.lineStyle(2,color,.8);
  const step=Math.PI*2/segs;
  for(let k=0;k<segs;k++)g.arc(0,0,r,k*step,k*step+step*.55);
  return g;
}
export function rebuildPreview(){
  if(!G.grp)return;
  if(G.tank&&G.tank.container.parent) G.tank.container.parent.removeChild(G.tank.container);
  G.tank=tankVisual(store.S.loadout,1.7);
  G.grp.addChild(G.tank.container);   // танк последним → поверх трапа и платформы
  G.grp.scale.set(G.grpScale||1);
}
export function buildGarageScene(){
  sceneGarage.removeChildren().forEach(c=>c.destroy({children:true}));
  G.dust=[];G.departFx=[];G.grp=null;G.tank=null;G.fx=null;G.ramp=null;G.rampG=null;G.rampMask=null;
  G.bigText=new PIXI.Text('РУБЕЖ',{fontFamily:'Russo One',fontSize:230,fill:0xffffff,alpha:.04,letterSpacing:20});
  G.bigText.anchor.set(.5);sceneGarage.addChild(G.bigText);

  G.grp=new PIXI.Container();sceneGarage.addChild(G.grp);
  const glow=new PIXI.Graphics();
  glow.beginFill(0x79c7d4,.03);glow.drawCircle(0,0,340);glow.endFill();
  glow.beginFill(0xffb020,.045);glow.drawCircle(0,0,215);glow.endFill();
  G.grp.addChild(glow);
  G.ringA=mkRing(252,0x39424a,8);G.ringB=mkRing(300,0x2a3338,5);G.grp.addChild(G.ringA,G.ringB);
  const plat=new PIXI.Graphics();
  plat.beginFill(0x1d2326);plat.drawCircle(0,0,190);plat.endFill();
  plat.lineStyle(3,0x39424a);plat.drawCircle(0,0,190);
  plat.lineStyle(2,0x2a3338);plat.drawCircle(0,0,150);
  plat.lineStyle(0);plat.beginFill(0xffb020,.7);
  for(let k=0;k<24;k++){const a=k*Math.PI/12;
    plat.drawPolygon([Math.cos(a)*178,Math.sin(a)*178,Math.cos(a+.13)*178,Math.sin(a+.13)*178,Math.cos(a+.065)*188,Math.sin(a+.065)*188])}
  plat.beginFill(0x242c30);
  for(let k=0;k<8;k++){const a=k*Math.PI/4+.3;plat.drawCircle(Math.cos(a)*120,Math.sin(a)*120,5)}
  G.grp.addChild(plat);
  const tag=new PIXI.Text('ОБРАЗЕЦ · СТАПЕЛЬ 07',{fontFamily:'Russo One',fontSize:11,fill:0xffb020,alpha:.55,letterSpacing:3});
  tag.anchor.set(.5);tag.position.set(0,232);G.grp.addChild(tag);
  const tag2=new PIXI.Text('каждый модуль меняет облик машины',{fontFamily:'JetBrains Mono',fontSize:8.5,fill:0x8b968f,letterSpacing:1});
  tag2.anchor.set(.5);tag2.position.set(0,252);G.grp.addChild(tag2);

  /* трап живёт ВНУТРИ группы (локальные координаты превью) → масштабируется пропорционально платформе */
  G.ramp=new PIXI.Container();G.ramp.position.set(0,180);
  G.rampG=new PIXI.Graphics();G.rampMask=new PIXI.Graphics();
  G.ramp.addChild(G.rampG,G.rampMask);G.ramp.mask=G.rampMask;
  G.grp.addChild(G.ramp);

  /* слой пыли выезда/заезда — в мировых координатах сцены, поверх всего */
  G.fx=new PIXI.Container();sceneGarage.addChild(G.fx);

  for(let i=0;i<42;i++){
    const d=new PIXI.Graphics();d.beginFill(0xcfd8d2,rnd(.05,.16));d.drawCircle(0,0,rnd(.8,2.2));d.endFill();
    const o={el:d,x:rnd(0,innerWidth),y:rnd(0,innerHeight),vx:rnd(-9,-3),vy:rnd(-14,-5)};
    d.position.set(o.x,o.y);sceneGarage.addChild(d);G.dust.push(o);}

  garageLayout();   // ставит позиции + считает геометрию трапа + рисует его
  rebuildPreview();
}

/* пыль с кормы танка в транзите (dirSign=-1 → вверх при съезде, +1 → вниз при заезде) */
function spawnTransitDust(localY,dirSign){
  if(!G.tank)return;
  const s=G.grpScale||1;
  for(let side=-1;side<=1;side+=2){
    const lx=side*16, ly=localY+dirSign*20;          // корма в локальных координатах превью
    const wx=G.px+lx*s, wy=G.py+ly*s;               // → в мировые координаты сцены
    const el=new PIXI.Graphics();
    const col=[0x6a6258,0x7d7468,0x574f46][(Math.random()*3)|0];
    el.beginFill(col);el.drawCircle(0,0,rnd(3,6));el.endFill();
    G.fx.addChild(el);
    G.departFx.push({el,x:wx,y:wy,
      vx:side*rnd(20,50)+(Math.random()*2-1)*20,
      vy:dirSign*rnd(30,80),
      life:rnd(.4,.7),max:0});
    G.departFx[G.departFx.length-1].max=G.departFx[G.departFx.length-1].life;
  }
}
function updDepartFx(dt){
  for(let i=G.departFx.length-1;i>=0;i--){
    const p=G.departFx[i];p.life-=dt;
    if(p.life<=0){if(p.el.parent)p.el.parent.removeChild(p.el);p.el.destroy();G.departFx.splice(i,1);continue;}
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=0.92;p.vy*=0.92;
    p.el.position.set(p.x,p.y);
    p.el.alpha=(p.life/p.max)*0.8;
    p.el.scale.set(1+(1-p.life/p.max)*1.4);
  }
}
function updDustBg(ds){
  for(const dd of G.dust){dd.x+=dd.vx*ds;dd.y+=dd.vy*ds;
    if(dd.x<-5)dd.x=innerWidth+5;if(dd.y<-5)dd.y=innerHeight+5;dd.el.position.set(dd.x,dd.y);}
}

export function updGarage(ds,t){
  if(!G.grp||!G.ringA)return;
  G.ringA.rotation+=ds*.2;G.ringB.rotation-=ds*.12;
  updDepartFx(ds);

  /* ── СЪЕЗД НА АРЕНУ: платформа стоит, выезжает трап, танк катит по нему ── */
  if(G.depart){
    const d=G.depart, tk=G.tank?G.tank.container:null;
    if(d.phase==='turn'){
      if(!tk){d.fired=true;if(d.onDone)d.onDone();updDustBg(ds);return;}
      if(d.startRot===undefined){let r=tk.rotation%(Math.PI*2);if(r<0)r+=Math.PI*2;d.startRot=r;}
      d.t+=ds;const k=easeOut(d.t/0.4);
      tk.rotation=lerp(d.startRot,Math.PI,k);          // разворот носом к трапу (вниз)
      if(d.t>=0.4){d.phase='ramp';d.t=0;}
    // }else if(d.phase==='ramp'){
    }else if(d.phase==='ramp'){
      if(!d.rampSnd){d.rampSnd=true;AudioFX.rampExtend();EngineSound.setEnabled(true);EngineSound.setDrive(true,2.4,store.S.loadout.gear,store.S.loadout.engine);}
      d.t+=ds;const k=easeOut(d.t/0.35);
      setRampRevealed(k*G.localL);

      // d.t+=ds;const k=easeOut(d.t/0.35);
      // setRampRevealed(k*G.localL);                      // трап выезжает из-под платформы
      if(tk) tankFx(G.tank,ds,t,0);
      if(d.t>=0.35){d.phase='roll';d.t=0;}
    }else if(d.phase==='roll'){
      if(!d.rollSnd){d.rollSnd=true;AudioFX.deployRumble();}
      d.t+=ds;const k=easeIn(d.t/0.7);
      const ly=lerp(0,G.localBottom,k);
      if(tk){tk.position.set(0,ly);tk.rotation=Math.PI;tankFx(G.tank,ds,t,220*ds);}
      d._dustT=(d._dustT||0)-ds;
      if(d._dustT<=0&&k<0.95){d._dustT=0.04;spawnTransitDust(ly,-1);}
      if(k>0.55&&!d.lateFired){d.lateFired=true;if(d.onRollLate)d.onRollLate();}
      if(d.t>=0.7&&!d.fired){d.fired=true;if(d.onDone)d.onDone();}
    }
    updDustBg(ds);return;
  }

  /* ── ВОЗВРАТ В АНГАР: трап выезжает, танк вкатывает снизу, трап убирается ── */
  if(G.arrive){
    const a=G.arrive, tk=G.tank?G.tank.container:null;
    if(!a.inited){a.inited=true;if(tk){tk.position.set(0,G.localBottom);tk.rotation=0;}} // за экраном, носом вверх
    if(a.phase==='ramp_in'){
      a.t+=ds;const k=easeOut(a.t/0.3);setRampRevealed(k*G.localL);
      if(tk) tankFx(G.tank,ds,t,0);
      if(a.t>=0.3){a.phase='roll_in';a.t=0;}
    }else if(a.phase==='roll_in'){
      a.t+=ds;const k=easeOut(a.t/0.6);
      const ly=lerp(G.localBottom,0,k);
      if(tk){tk.position.set(0,ly);tk.rotation=0;tankFx(G.tank,ds,t,220*ds);}
      a._dustT=(a._dustT||0)-ds;
      if(a._dustT<=0&&k<0.95){a._dustT=0.04;spawnTransitDust(ly,+1);}
      if(a.t>=0.6){a.phase='ramp_out';a.t=0;}
    }else if(a.phase==='ramp_out'){
      a.t+=ds;const k=easeIn(a.t/0.3);setRampRevealed((1-k)*G.localL);
      if(tk) tankFx(G.tank,ds,t,0);
      if(a.t>=0.3){if(tk)tk.position.set(0,0);G.arrive=null;G.arriving=false;setRampRevealed(0);}
    }
    updDustBg(ds);return;
  }

  /* ── штатный режим: плавное вращение на круге ── */
  G.tCur+=ds*0.45;
  if(G.tank){const tk=G.tank.container;tk.rotation=G.tCur;tk.position.set(0,Math.sin(t*.8)*3);tankFx(G.tank,ds,t,0);}
  updDustBg(ds);
}

/* ── действия гаража (заблокированы во время транзитных анимаций) ── */
function busy(){return G.departing||G.arriving;}
export function equip(id){
  if(busy())return;
  const m=MODULES[id];if(!m)return;
  let slot=m.cat;
  if(m.cat==='aux'){ if(!store.S.loadout.aux1)slot='aux1'; else if(!store.S.loadout.aux2)slot='aux2';
    else{toast('ОБА ВСПОМОГАТЕЛЬНЫХ СЛОТА ЗАНЯТЫ');AudioFX.err();return;} }
  const old=store.S.loadout[slot];
  store.S.loadout[slot]=id;store.S.inv[id]--;if(store.S.inv[id]<=0)delete store.S.inv[id];
  if(old)store.S.inv[old]=(store.S.inv[old]||0)+1;
  // save();emit('ui:rebuild');rebuildPreview();AudioFX.place();
  save();emit('ui:rebuild');rebuildPreview();AudioFX.place();AudioFX.servo();
}
export function unequip(k){
  if(busy())return;
  const id=store.S.loadout[k];if(!id)return;
  store.S.loadout[k]=null;store.S.inv[id]=(store.S.inv[id]||0)+1;
  // save();emit('ui:rebuild');rebuildPreview();
  save();emit('ui:rebuild');rebuildPreview();AudioFX.servo();
}
function rollCraft(){
  const total=CRAFT_POOL.reduce((s,e)=>s+e[1],0);let r=Math.random()*total;
  for(const[id,w]of CRAFT_POOL){r-=w;if(r<=0)return id;}
  return CRAFT_POOL[0][0];
}
export function openCraft(){
  if(busy())return;
  if(store.S.boxes<1){toast('НЕТ КОНТЕЙНЕРОВ');AudioFX.err();return;}
  store.S.boxes--;const id=rollCraft();store.S.inv[id]=(store.S.inv[id]||0)+1;
  save();emit('ui:rebuild');rebuildPreview();AudioFX.pickup();
  store.uiState.modal={type:'reveal',id,batch:null,t:0};emit('ui:rebuild');
}
export function openOneMore(){
  if(busy())return;
  if(store.S.boxes<1){toast('НЕТ КОНТЕЙНЕРОВ');AudioFX.err();return;}
  store.S.boxes--;const id=rollCraft();store.S.inv[id]=(store.S.inv[id]||0)+1;
  save();store.uiState.modal={type:'reveal',id,batch:null,t:0};emit('ui:rebuild');AudioFX.pickup();
}
export function openBatch(n){
  if(busy())return;
  const take=Math.min(n,store.S.boxes);
  if(take<1){toast('НЕТ КОНТЕЙНЕРОВ');AudioFX.err();return;}
  if(take<n)toast('В НАЛИЧИИ ТОЛЬКО '+take);
  store.S.boxes-=take;const counts={};let last=null;
  for(let i=0;i<take;i++){const id=rollCraft();counts[id]=(counts[id]||0)+1;store.S.inv[id]=(store.S.inv[id]||0)+1;last=id;}
  save();const summary=Object.entries(counts).map(([id,count])=>({id,count}));
  store.uiState.modal={type:'reveal',id:last,batch:summary,batchN:take,t:0};emit('ui:rebuild');AudioFX.pickup();
}
export function buyBox(){
  if(busy())return;
  if(store.S.bolts<150){toast('НЕ ХВАТАЕТ БОЛТОВ');AudioFX.err();return;}
  store.S.bolts-=150;store.S.boxes++;save();emit('ui:rebuild');rebuildPreview();AudioFX.pickup();toast('+1 КРАФТ-БОКС');
}
export function toggleSound(){
  store.S.sound=!store.S.sound;AudioFX.on=store.S.sound;save();AudioFX.ensure();AudioFX.pickup();emit('ui:rebuild');
}
export function toggleMusic(){
  store.S.music=!store.S.music;save();
  import('../core/music.js').then(M=>M.setEnabled(store.S.sound&&store.S.music));
  AudioFX.pickup();emit('ui:rebuild');
}
export function doReset(){
  resetProgress();store.uiState.modal=null;emit('ui:rebuild');rebuildPreview();toast('ПРОГРЕСС СБРОШЕН');
}