import { store,save } from '../core/store.js';
import { CELL,BORDER,GRID_W,GRID_H,baseRing,TL } from '../config/world.js';
import { fxLayer } from '../core/engine.js';
import { floatText } from '../fx/particles.js';
import { AudioFX } from '../core/audio.js';
import { placeValid } from './collision.js';
import { tiles,placeTile,removeTile } from '../world/map.js';
import { randi } from '../utils/helpers.js';
import { log,syncRes } from '../ui/hud.js';
import { mkIcon } from '../ui/icons.js';

export function spawnPickup(type){
  let gx=-1,gy=-1;
  for(let tries=0;tries<60;tries++){
    const cx=randi(0,GRID_W-1),cy=randi(1,GRID_H-1);
    if(placeValid(cx,cy)){gx=cx;gy=cy;break}}
  if(gx<0)return;
  const c=new PIXI.Container();
  const bg=new PIXI.Graphics();
  bg.beginFill(0x161c1f);bg.drawPolygon([6,0,36,0,36,30,30,36,0,36,0,6]);bg.endFill();
  bg.lineStyle(1.5,0xffb020,1);bg.drawPolygon([6,0,36,0,36,30,30,36,0,36,0,6]);bg.lineStyle(0);
  c.addChild(bg);
  const ic=mkIcon(type,18);ic.position.set(9,9);c.addChild(ic);   // без .anchor — у Graphics его нет
  c.position.set(BORDER+gx*CELL+6,BORDER+gy*CELL+6);
  fxLayer.addChild(c);
  store.B.pickups.push({gx,gy,type,el:c,life:25});
}
export function activateShovel(){
  const B=store.B;B.shovelT=12;
  baseRing.forEach(([gx,gy])=>{
    const k=gx+','+gy,tl=tiles.get(k);
    if(tl&&tl.t===TL.BRICK)removeTile(tl);
    if(!tiles.get(k))placeTile(gx,gy,TL.STEEL_TEMP)});
  log('ШТАБ ОБНЁСЁН СТАЛЬЮ · 12 СЕКУНД','warn');
}
export function applyPickup(p){
  const B=store.B,x=BORDER+p.gx*CELL+CELL/2,y=BORDER+p.gy*CELL+CELL/2;
  AudioFX.pickup();
  if(p.type==='bolts'){store.S.bolts+=15;B.boltsRun+=15;floatText(x,y,'+15',0xffd27a,14,'bolts')}
  else if(p.type==='gears'){store.S.gears++;B.gearsRun++;floatText(x,y,'+1',0x79c7d4,14,'gears')}
  else if(p.type==='repair'){B.player.hp=Math.min(B.player.maxHp,B.player.hp+2);floatText(x,y,'+2 HP',0xa5c46b,14,'repair')}
  else if(p.type==='shield'){B.player.invuln=Math.max(B.player.invuln,6);floatText(x,y,'6С',0x9fd8e2,14,'shield')}
  else if(p.type==='shovel'){activateShovel();floatText(x,y,'ЛОПАТА',0x9fb0ba,14,'shovel')}
  else if(p.type==='box'){store.S.boxes++;B.boxesRun++;floatText(x,y,'+1',0xffd27a,14,'box');log('КОНТЕЙНЕР ЗАГРУЖЕН В ТЯГАЧ','good')}
  save();syncRes();
}
export function updPickups(dt){
  const B=store.B;
  for(let i=B.pickups.length-1;i>=0;i--){
    const p=B.pickups[i];p.life-=dt;
    p.el.alpha=p.life<4?(Math.sin(B.time*10)>0?1:.3):(.85+.15*Math.sin(B.time*5));
    const px=p.gx*CELL+CELL/2,py=p.gy*CELL+CELL/2;
    if(!B.over&&Math.abs(B.player.x-px)<28&&Math.abs(B.player.y-py)<28){
      applyPickup(p);B.pickups.splice(i,1);p.el.destroy();continue}
    if(p.life<=0){B.pickups.splice(i,1);p.el.destroy()}
  }
}