import * as loader from '../ui/loader.js';
import { startBattle, toGarage } from './battle.js';
import { G } from '../garage/garage.js';

/* Оркестратор переходов. Гараж про лоадер/бой не знает ничего —
   общаемся через G.depart / G.arrive, которые крутит updGarage. */

export function goToBattle(){
  if(G.departing) return;
  G.departing=true;
  G.depart={ phase:'turn', t:0, startRot:undefined, lateFired:false, fired:false,
    onRollLate:()=>loader.show('РАЗВЁРТЫВАНИЕ ПИТА 07'),
    onDone:()=>loader.runProgress(()=>{
      startBattle();
      loader.fadeOut(()=>{ G.departing=false; G.depart=null; });
    }),
  };
}

export function goToGarage(){
  loader.show('ВОЗВРАТ В АНГАР');
  loader.runProgress(()=>{
    toGarage();
    G.arriving=true;
    G.arrive={ phase:'ramp_in', t:0, inited:false };
    loader.fadeOut(()=>{ /* arrive доиграет в updGarage и сам сбросит флаг */ });
  });
}