export function modStat(m){
  if(!m)return'';
  if(m.cat==='hull')return m.hp+' HP · '+m.w+' Т';
  if(m.cat==='gun')return m.dmg+'У · ОБ'+m.clip+' · '+m.rate+'/С · '+m.range+'КЛ';
  if(m.cat==='engine')return m.spd+' КЛ/С · ПЗ×'+m.rlm+(m.dash?' · РЫВОК':'');
  if(m.cat==='gear')return '+'+m.add+' КЛ/С · '+m.w+' Т';
  if(m.cat==='optics')return '+'+m.rng+' КЛ ДАЛЬН';
  if(m.cat==='power')return m.cap+' ЭН · '+m.reg+'/С';
  return m.tag||'';
}

