import { clamp } from '../utils/helpers.js';
import { MODULES } from '../config/modules.js';

export function tankVisual(lo,scale){
  const c=new PIXI.Container();
  const g=new PIXI.Graphics();
  c.addChild(g);
  const hullId=lo.hull||'hull_medium';
  let hw=20,hl=20,body=0xc8a83c,bodyL=0xe0c860,bodyD=0x8a7428;
  if(hullId==='hull_light'){hw=16;hl=18;body=0x8a9a55;bodyL=0xa8b870;bodyD=0x5c6a38}
  if(hullId==='hull_heavy'){hw=22;hl=22;body=0x9a8a4c;bodyL=0xb8a866;bodyD=0x6a5e30}
  if(hullId==='hull_assault'){hw=19;hl=21;body=0xb08a3c;bodyL=0xd0a855;bodyD=0x7a5e26}
  const gearId=lo.gear||'gear_tracks';
  const gw=gearId==='gear_wide'?10:8;
  const wheels=[];
  if(gearId==='gear_wheels'||gearId==='gear_rollers'){
    const n=gearId==='gear_wheels'?3:4,r=gearId==='gear_wheels'?6:4;
    for(let s=-1;s<=1;s+=2)for(let i=0;i<n;i++){
      const y=-hl+6+((hl*2-12)/(n-1))*i;
      const w=new PIXI.Graphics();
      w.beginFill(0x2a2e28);w.drawCircle(0,0,r);w.endFill();
      w.beginFill(0x555b50);w.drawCircle(0,0,r-2.5);w.endFill();
      w.lineStyle(1.5,0x2a2e28);w.moveTo(-r+2,0);w.lineTo(r-2,0);w.moveTo(0,-r+2);w.lineTo(0,r-2);w.lineStyle(0);
      w.beginFill(0x191d18);w.drawCircle(0,0,1.8);w.endFill();
      w.position.set(s*(hw+r-1),y);
      c.addChild(w);wheels.push(w)}
    g.beginFill(0x4a4f42);
    g.drawRect(-hw-gw+2,-hl-2,gw-2,4);g.drawRect(hw,-hl-2,gw-2,4);
    g.drawRect(-hw-gw+2,hl-2,gw-2,4);g.drawRect(hw,hl-2,gw-2,4);g.endFill();
  }else{
    g.beginFill(gearId==='gear_wide'?0x2e3428:0x3a3a30);
    g.drawRect(-hw-gw,-hl,gw,hl*2);g.drawRect(hw,-hl,gw,hl*2);g.endFill();
  }
  g.beginFill(body);g.drawRoundedRect(-hw,-hl,hw*2,hl*2,5);g.endFill();
  g.beginFill(bodyL);
  if(hullId==='hull_assault')g.drawPolygon([-hw+4,-hl,hw-4,-hl,hw-8,-hl+7,-hw+8,-hl+7]);
  else g.drawRect(-hw+3,-hl+2,hw*2-6,5);
  g.endFill();
  g.beginFill(bodyD);g.drawRect(-hw+3,hl-6,hw*2-6,4);g.endFill();
  g.beginFill(bodyD);g.drawCircle(0,2,6);g.endFill();
  g.beginFill(bodyL);g.drawCircle(0,2,3.5);g.endFill();
  if(hullId==='hull_heavy'){
    g.beginFill(0x6e6440);
    [[-hw+4,-hl+8],[hw-4,-hl+8],[-hw+4,hl-8],[hw-4,hl-8]].forEach(p=>g.drawCircle(p[0],p[1],2));
    g.endFill();
    g.beginFill(0x7c7048);g.drawRect(-hw-2,-hl+6,3,hl*2-12);g.drawRect(hw-1,-hl+6,3,hl*2-12);g.endFill()}
  if(hullId==='hull_assault'){
    g.beginFill(0xd4574a);g.drawPolygon([-4,-hl+9,4,-hl+9,0,-hl+14]);g.endFill()}
  const engId=lo.engine||'eng_base';
  const pipes=engId==='eng_turbo'?3:engId==='eng_forced'?2:1;
  g.beginFill(0x26291f);
  for(let i=0;i<pipes;i++)g.drawCircle(-6+i*6,hl-2,2.6);
  g.endFill();
  const gunId=lo.gun;
  if(gunId){
    g.beginFill(0x3c4038);
    if(gunId==='gun_short')g.drawRect(-2,-hl-10,4,12);
    else if(gunId==='gun_long'){g.drawRect(-2,-hl-28,4,30);g.endFill();
      g.beginFill(0x26291f);g.drawRect(-3.5,-hl-28,7,5)}
    else if(gunId==='gun_twin'){g.drawRect(-7,-hl-18,4,20);g.drawRect(3,-hl-18,4,20)}
    else if(gunId==='gun_howitzer'){g.drawRect(-4,-hl-14,8,16);g.endFill();
      g.beginFill(0x26291f);g.drawCircle(0,-hl-14,5);
      g.beginFill(0x3c4038);g.drawCircle(0,-hl-14,2.5)}
    else g.drawRect(-2,-hl-18,4,20);
    g.endFill();
    g.beginFill(0x4a4f42);g.drawCircle(0,-hl+4,6);g.endFill();
  }
  const auxIds=[lo.aux1,lo.aux2].filter(Boolean);
  const drones=[];
  auxIds.forEach((id,ai)=>{
    if(id==='aux_mortar'){
      const mx=ai?hw-7:-hw+7;
      g.beginFill(0x2f352c);g.drawCircle(mx,hl-9,5.5);g.endFill();
      g.beginFill(0x11150f);g.drawCircle(mx,hl-9,2.6);g.endFill();
    }else if(id==='aux_eng'){
      g.beginFill(0xd99414);g.drawRect(-7,hl-5,14,5);g.endFill();
      g.beginFill(0x8a6205);g.drawRect(-9,hl-2,4,3);g.drawRect(5,hl-2,4,3);g.endFill();
    }else if(id==='aux_turret'){
      const tx=ai?-hw+7:hw-7;
      g.lineStyle(2,0x555b50);g.drawCircle(tx,hl-9,4.5);g.lineStyle(0);
      g.beginFill(0x555b50);g.drawCircle(tx,hl-9,1.8);g.endFill();
    }else if(id==='aux_dh'||id==='aux_da'){
      const heal=id==='aux_dh';
      const m = MODULES[id];
      const n = (m && m.drones) || 2;     // сколько дронов рисовать
      for(let k=0;k<n;k++){
        const d=new PIXI.Graphics();
        d.beginFill(heal?0x6fc37a:0xd4763c);d.drawCircle(0,0,3.4);d.endFill();
        d.beginFill(heal?0xbfeec6:0xf0b490);d.drawCircle(0,0,1.5);d.endFill();
        if(!heal){d.beginFill(0x26291f);d.drawRect(-1,-6,2,4);d.endFill()}
        c.addChild(d);
        drones.push({el:d,r:hl+14+ai*7,spd:(heal?2.2:2.9)*(k?-1:1),off:k*Math.PI+ai*1.3,heal})}
    }
  });
  const optId=lo.optics;let blink=null;
  if(optId==='opt_prism'){g.beginFill(0x79c7d4);g.drawRect(hw-7,-hl+5,5,3);g.endFill()}
  if(optId==='opt_radar'){
    g.lineStyle(1.5,0x555b50);g.moveTo(-hw+5,-hl+6);g.lineTo(-hw+5,-hl-8);g.lineStyle(0);
    blink=new PIXI.Graphics();blink.beginFill(0xe0503c);blink.drawCircle(0,0,2);blink.endFill();
    blink.position.set(-hw+5,-hl-8);c.addChild(blink)}
  const powId=lo.power;const glows=[];
  if(powId){
    const n=powId==='pow_reactor'?2:1;
    for(let i=0;i<n;i++){
      const gl=new PIXI.Graphics();
      gl.beginFill(0x6fd3e0,.9);gl.drawRect(0,0,4,7);gl.endFill();
      gl.position.set(hw-6,(-n*9)/2+i*9+1);
      c.addChild(gl);glows.push(gl)}}
  let notch=null;
  if(gearId!=='gear_wheels'&&gearId!=='gear_rollers'){
    notch=new PIXI.Graphics();notch.beginFill(0x1f231c);
    for(let y=-hl+2;y<hl-2;y+=7){notch.drawRect(-hw-gw+1,y,gw-2,3);notch.drawRect(hw+1,y,gw-2,3)}
    notch.endFill();c.addChild(notch)}
  c.scale.set(scale||1);
  return{container:c,body:g,notch,wheels,drones,blink,glows,acc:0,frame:0,hl};
}

export function tankFx(v,dt,time,dist){
  if(v.notch){v.acc+=dist;
    if(v.acc>7){v.acc-=7;v.frame^=1;v.notch.y=v.frame?3.5:0}}
  v.wheels.forEach(w=>w.rotation+=dist*.12);
  v.drones.forEach(d=>{const a=time*d.spd+d.off;d.el.position.set(Math.cos(a)*d.r,Math.sin(a)*d.r)});
  if(v.blink)v.blink.alpha=.3+.7*Math.abs(Math.sin(time*4));
  v.glows.forEach((gl,i)=>gl.alpha=.5+.5*Math.abs(Math.sin(time*3+i)));
}

export function tankSprite(cols,barrelCols,px){
  px=px||4;
  const g=new PIXI.Graphics();
  const rows=['...........','...........','...........','TT.BBBBB.TT','TT.BbbbB.TT',
    'TTT.BCB.TTT','TT.BbbbB.TT','TT.BBBBB.TT','TT..BBB..TT','TT...B...TT','TT.......TT'];
  const grid=rows.map(r=>r.split(''));
  barrelCols.forEach(cc=>{grid[0][cc]='G';grid[1][cc]='G';grid[2][cc]='G'});
  const cmap={T:cols.tread,B:cols.body,b:cols.light,C:cols.hatch,G:cols.gun};
  grid.forEach((row,r)=>row.forEach((ch,cc)=>{
    if(ch==='.')return;
    g.beginFill(cmap[ch]);g.drawRect((cc-5.5)*px,(r-5.5)*px,px,px);g.endFill()}));
  return g;
}
export function treadGfx(cols){
  const g=new PIXI.Graphics();
  g.beginFill(cols.notch);
  for(let y=-10;y<=14;y+=8){g.drawRect(-22,y,8,3);g.drawRect(14,y,8,3)}
  g.endFill();return g;
}
export function buildEnemySprite(type){
  const c=new PIXI.Container();
  const bcols=type==='boss'?[3,5,7]:[5];
  const body=tankSprite(ECOLS[type],bcols,4);
  const treads=treadGfx(ECOLS[type]);
  c.addChild(body,treads);
  if(type==='boss')c.scale.set(1.18);
  return{container:c,body,treads};
}
import { ECOLS } from '../config/world.js';