export function startBattle(){
  const st=calcStats();
  if(!st.gun){toast('УСТАНОВИТЕ ОРУДИЕ');AudioFX.err();return}
  store.mode='battle';
  sceneGarage.visible=false;sceneBattle.visible=true;
  tankLayer.removeChildren();bulletLayer.removeChildren();fxLayer.removeChildren();
  tileLayer.removeChildren();treeLayer.removeChildren();groundLayer.removeChildren();
  // resetParticles();resetMap();
  resetParticles();clearTracks();resetMap();
  store.uiState.log=[];store.uiState.modal=null;store.uiState.ann=null;
  const B={active:true,paused:false,over:false,resultsShown:false,time:0,timeScale:1,tsTarget:1,
    wave:0,state:'inter',interT:5,lastSec:99,spawnQ:[],spawnT:0,gateIdx:0,
    score:0,kills:0,boltsRun:0,boxesRun:0,gearsRun:0,
    player:{x:14*CELL+CELL/2,y:25*CELL+CELL/2,dir:0,hp:st.hp,maxHp:st.hp,speed:st.speed,
      invuln:2,unstuckCd:0,dashCd:0,trance:false,tranceE:st.tranceMax,hullFlash:0},
    stats:st,
    enemies:[],bullets:[],spawnFX:[],pickups:[],
    base:{alive:true},shovelT:0,waterT:0,waterFrame:0,
    healT:2,atkT:1,mortT:2,smokeT:0,
    cam:{x:BORDER+14*CELL+CELL/2,y:BORDER+25*CELL+CELL/2},shake:0,sel:0};
  store.B=B;
  buildGround();genMap();
  const gd=Object.assign({},st.gun,{rld:st.gun.rld*st.relMult,range:st.range});
  B.vis=tankVisual(store.S.loadout,1);
  B.tank={vis:B.vis,turrets:[{def:gd,clip:gd.clip,rel:0,cd:0}]};
  B.vis.container.position.set(BORDER+B.player.x,BORDER+B.player.y);
  tankLayer.addChild(B.vis.container);
  makeGhost();
  world.filters=[CMF];CMF.enabled=false;
  emit('ui:rebuild');
  log('ВЫЛАЗКА НАЧАЛАСЬ · ПИТ 07','warn');
  log('ПРИКРЫВАЙТЕ ШТАБ — ОДНО ПОПАДАНИЕ ФАТАЛЬНО','bad');
  announce('ВЫЛАЗКА','',2,'ПИТ 07 · ЗАЩИТА ШТАБА');
  AudioFX.horn();syncRes();
}

function updCamera(ds){
  const vw=app.screen.width,vh=app.screen.height;
  const fw=FIELD_W+BORDER*2,fh=FIELD_H+BORDER*2;
  const B=store.B;
  const px=BORDER+B.player.x,py=BORDER+B.player.y;
  const compact=vw<700||vh<700||('ontouchstart' in window);
  const landscape=vw>vh;

  /* высоты HUD по центру экрана (там, где обычно танк) — по режиму */
  let hudTop,hudBot;
  if(!compact){ hudTop=172; hudBot=150; }        /* десктоп: левая верхняя панель + нижний блок */
  else if(landscape){ hudTop=58; hudBot=0; }     /* мобильный ландшафт: одна строка сверху */
  else { hudTop=96; hudBot=0; }                  /* мобильный портрет: двухстрочная шапка */

  /* желаемые экранные пределы танка: 3 клетки под HUD сверху, 2.5 клетки над низом */
  const wantTop = hudTop + 3*CELL;
  const wantBot = vh - hudBot - 2.5*CELL;
  let ay, Ry;
  if(wantBot - wantTop > 40){ ay=(wantTop+wantBot)/2; Ry=(wantBot-wantTop)/2; }
  else { ay=vh/2; Ry=Math.max(20,(vh-hudTop-hudBot)/4); }   /* страховка для очень низких экранов */

  /* по горизонтали — прежняя логика, свой радиус Rx */
  let mL,mR,Rx;
  if(compact&&landscape){mL=150;mR=170;Rx=24;}
  else if(compact){mL=120;mR=120;Rx=24;}
  else{mL=Math.min(335,vw*.36);mR=Math.min(400,vw*.4);Rx=72;}
  const ax=mL+(vw-mL-mR)/2;

  const sx=px-B.cam.x+vw/2, sy=py-B.cam.y+vh/2;
  const dx=sx-clamp(sx,ax-Rx,ax+Rx);     /* горизонталь — свой радиус */
  const dy=sy-clamp(sy,ay-Ry,ay+Ry);     /* вертикаль — свой, привязанный к HUD */
  const k=Math.min(1,ds*(compact?14:10));
  B.cam.x+=dx*k; B.cam.y+=dy*k;

  /* clamp по краям карты: mT/mB подобраны так, чтобы при упоре в стену
     над танком оставалось ~2 клетки (короткий тёмный кант за ареной) */
  let mT,mB;
  if(!compact){ mT=222; mB=200; }
  else if(landscape){ mT=110; mB=60; }
  else { mT=150; mB=60; }
  const cMinX=vw/2-mL, cMaxX=fw-vw/2+mR;
  const cMinY=vh/2-mT, cMaxY=fh-vh/2+mB;
  if(cMinX<=cMaxX)B.cam.x=clamp(B.cam.x,cMinX,cMaxX);else B.cam.x=px;
  if(cMinY<=cMaxY)B.cam.y=clamp(B.cam.y,cMinY,cMaxY);else B.cam.y=py;

  B.shake=Math.max(0,B.shake-ds*26);
  const shx=(Math.random()*2-1)*B.shake,shy=(Math.random()*2-1)*B.shake;
  world.scale.set(1);
  world.position.set(Math.round(vw/2-B.cam.x+shx),Math.round(vh/2-B.cam.y+shy));
}

/* разрушение штаба: rubble + взрыв + анонс; конец вылазки — через шину,
   чтобы обработчик handleBattleOver досчитал задержку в одном месте */
export function destroyBase(){
  const B=store.B;
  if(!B||!B.base.alive)return;
  B.base.alive=false;
  const k=BASE.gx+','+BASE.gy, tl=tiles.get(k);
  if(tl){
    removeTile(tl);
    const r=mkRubble();
    r.position.set(BORDER+BASE.gx*CELL,BORDER+BASE.gy*CELL);
    tileLayer.addChild(r);
  }
  explosion(BORDER+BASE.gx*CELL+CELL/2,BORDER+BASE.gy*CELL+CELL/2,40,true);
  log('ШТАБ УНИЧТОЖЕН · ВЫЛАЗКА ПРОВАЛЕНА','bad');
  announce('ШТАБ ПОТЕРЯН','boss',2.4);
  B.over=true;
  emit('battle:over',{reason:'base',delay:1600});
}

/* единый обработчик конца боя для main.js: по reason решает, отступление ли это,
   и показывает экран результатов после задержки (взрыв успеет доиграть) */
export function handleBattleOver({reason,delay}={}){
  setTimeout(()=>endBattle(reason==='retreat'), delay||1400);
}

export function updBattle(ds){
  const B=store.B;
  const dt=ds*B.timeScale;B.time+=dt;
  if(!B.over){
    updPlayer(dt);
    setDrive(B.player.moved>0.1, B.player.speed, store.S.loadout.gear, store.S.loadout.engine);
    if(B.state==='inter'){
      B.interT-=dt;
      const sec=Math.ceil(Math.max(0,B.interT));
      if(sec!==B.lastSec){B.lastSec=sec;
        announce('УКРЕПЛЯЙТЕСЬ','',1,'ВОЛНА '+(B.wave+1)+' ЧЕРЕЗ '+sec)}
      if(B.interT<=0)startWave(B.wave+1);
    }else{
      const MAXE=Math.min(5,4+Math.floor(B.wave/5));
      if(B.spawnQ.length){
        if(B.enemies.length+B.spawnFX.length<MAXE){
          B.spawnT-=dt;
          if(B.spawnT<=0){
            const gx=GATE_X[B.gateIdx%3];B.gateIdx++;
            const sx=gx*CELL+CELL/2,sy=CELL/2;
            if(hitsTank(sx,sy,44,null)||rectHitsSolid(sx,sy,44)){B.spawnT=.4}
            else{B.spawnT=1.4;const q=B.spawnQ.shift();
              B.spawnFX.push({x:sx,y:sy,t:.7,type:q.type,bonus:q.bonus})}}}
      }else if(B.enemies.length===0&&B.spawnFX.length===0){waveClear()}
    }
    for(let i=B.spawnFX.length-1;i>=0;i--){
      const f=B.spawnFX[i];f.t-=dt;
      if(!f.el){f.el=new PIXI.Graphics();
        f.el.lineStyle(2.5,0xffb020,1);
        for(let k=0;k<4;k++){const a=k*Math.PI/2;
          f.el.moveTo(Math.cos(a)*4,Math.sin(a)*4);f.el.lineTo(Math.cos(a)*16,Math.sin(a)*16)}
        f.el.position.set(BORDER+f.x,BORDER+f.y);fxLayer.addChild(f.el)}
      f.el.rotation+=dt*9;
      f.el.scale.set(.6+Math.abs(Math.sin(f.t*14))*.7);
      if(f.t<=0){fxLayer.removeChild(f.el);f.el.destroy();
        B.spawnFX.splice(i,1);
        if(!B.over)spawnEnemy(f.type,f.x,f.y,f.bonus)}}

    updBullets(dt);
    sweep();
    if(B._baseHit){B._baseHit=false;destroyBase();}
    for(const e of B.enemies)updEnemy(e,dt);
    separateEnemies();
    separatePlayer(B);
    B.vis.container.position.set(BORDER+B.player.x,BORDER+B.player.y);
    for(const e of B.enemies)e.container.position.set(BORDER+e.x,BORDER+e.y);
    updForts(dt);

    // for(const e of B.enemies)updEnemy(e,dt);
    // separateEnemies();
    // updBullets(dt);
    // if(B._baseHit){B._baseHit=false;destroyBase();}
    // updForts(dt);
    updPickups(dt);
    updWater(dt);
    if(B.shovelT>0){B.shovelT-=dt;
      if(B.shovelT<=0){
        baseRing.forEach(([gx,gy])=>{
          const k=gx+','+gy,tl=tiles.get(k);
          if(tl&&tl.t===TL.STEEL_TEMP){removeTile(tl);placeTile(gx,gy,TL.BRICK);}});
        log('СТАЛЬНОЕ КОЛЬЦО СНЯТО','info')}}
  }
  const trackSrc = B.over ? [] : [B.player].concat(B.enemies);
  updTracks(dt, trackSrc);
  updGhost();updCamera(ds);syncHUD();
}

export function endBattle(retreat){
  const B=store.B;
  if(!B||B.resultsShown)return;B.resultsShown=true;B.active=false;
  const newRec=B.wave>store.S.record;if(newRec)store.S.record=B.wave;save();
  store.uiState.results={
    title:retreat?'ОТСТУПЛЕНИЕ':(!B.base.alive?'ШТАБ ПОТЕРЯН':(B.player.hp<=0?'КОРПУС РАЗРУШЕН':'ВЫЛАЗКА ЗАВЕРШЕНА')),
    newRec,wave:B.wave,score:String(B.score).padStart(6,'0'),kills:B.kills,
    bolts:'+'+B.boltsRun,boxes:'+'+B.boxesRun,gears:'+'+B.gearsRun};
  store.uiState.modal={type:'results'};
  emit('ui:rebuild');
}
export function leaveBattle(){const B=store.B;if(B)B.over=true;endBattle(true)}
export function toGarage(){
  const B=store.B;
  if(B){tankLayer.removeChildren();bulletLayer.removeChildren();fxLayer.removeChildren();
    tileLayer.removeChildren();treeLayer.removeChildren();groundLayer.removeChildren();
    // removeGhost();resetParticles();world.filters=[]}
    removeGhost();resetParticles();clearTracks();world.filters=[]}
  store.B=null;store.mode='garage';
  sceneBattle.visible=false;sceneGarage.visible=true;
  store.uiState.modal=null;store.uiState.ann=null;
  emit('ui:rebuild');
  rebuildPreview();
}
export function togglePause(){
  const B=store.B;
  if(!B||!B.active||B.over)return;
  B.paused=!B.paused;
  store.uiState.modal=B.paused?{type:'pause'}:null;
  emit('ui:rebuild');
}