/* Единая таблица привязок «действие → клавиша + метки кнопок».
   Сменить кнопку = поправить code здесь (или setBind в рантайме).
   move (WASD) — это оси, они не биндятся как кнопки и живут в player.js. */
export const ACTIONS = {
  fire:     { code:'Space',  label:'ОГОНЬ',     sub:'' },
  build:    { code:'KeyF',   label:'СТЕНА',     sub:'F' },
  demolish: { code:'KeyX',   label:'СНОС',      sub:'X' },
  trance:   { code:'KeyB',   label:'ТРАНС',     sub:'B' },
  unstuck:  { code:'KeyR',   label:'ВЫБРАТЬСЯ', sub:'R' },
  dash:     { code:'KeyT',   label:'РЫВОК',     sub:'T' },
  pause:    { code:'Escape', label:'ПАУЗА',     sub:'' },
  fort1:    { code:'Digit1', label:'1', sub:'' },
  fort2:    { code:'Digit2', label:'2', sub:'' },
  fort3:    { code:'Digit3', label:'3', sub:'' },
  fort4:    { code:'Digit4', label:'4', sub:'' },
};
/* всегда актуальный поиск (учитывает setBind) */
export function actionForCode(code){
  for(const k in ACTIONS) if(ACTIONS[k].code===code) return k;
  return null;
}
export function setBind(action,code){ if(ACTIONS[action]) ACTIONS[action].code=code; }
export function getBind(action){ return ACTIONS[action]?ACTIONS[action].code:null; }
/* список действий для сенсорного кластера (без fire/pause/fort — они отдельно) */
export const TOUCH_AUX = ['build','demolish','trance','unstuck','dash'];