import { groundLayer,tileLayer,treeLayer } from '../core/engine.js';
import { GRID_W,GRID_H,CELL,BORDER,TL,BASE,baseRing,GATE_X,FIELD_W,FIELD_H } from '../config/world.js';
import { rnd } from '../utils/helpers.js';
import { store } from '../core/store.js';

export const tiles=new Map();
export const treeMap=new Map();

export function mkTile(t,frame){
  const g=new PIXI.Graphics();
  if(t===TL.BRICK){
    g.beginFill(0x6e3418);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x9a5230);
    for(let ry=0;ry<4;ry++){const y=ry*12+1;
      if(ry%2===0){g.drawRect(1,y,22,10);g.drawRect(25,y,22,10)}
      else{g.drawRect(0,y,10,10);g.drawRect(13,y,22,10);g.drawRect(37,y,10,10)}}
    g.endFill();g.beginFill(0x000000,.2);g.drawRect(0,44,48,4);g.endFill();
  }else if(t===TL.STEEL||t===TL.STEEL_TEMP){
    const base=t===TL.STEEL?0x9aa0a4:0x7aa8b8,hi=t===TL.STEEL?0xc6ccd0:0xaadcee,lo=t===TL.STEEL?0x5c6266:0x4a7a8a;
    g.beginFill(base);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(hi);g.drawRect(2,2,44,6);g.drawRect(2,2,6,44);g.endFill();
    g.beginFill(lo);g.drawRect(2,40,44,6);g.drawRect(40,2,6,44);g.endFill();
    g.beginFill(base);g.drawCircle(24,24,7);g.endFill();
    g.lineStyle(2,lo);g.drawCircle(24,24,7);g.lineStyle(0);
    g.beginFill(0x40464a);[[10,10],[38,10],[10,38],[38,38]].forEach(p=>g.drawCircle(p[0],p[1],2.5));g.endFill();
  }else if(t===TL.WATER){
    g.beginFill(0x1c3f66);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x2f5f8f);
    for(let wy=0;wy<3;wy++)for(let wx=0;wx<3;wx++)
      g.drawRect(wx*16+((wy+frame)%2)*6+2,8+wy*14,10,3);
    g.endFill();
  }else if(t===TL.BASE){
    g.beginFill(0x23282b);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x39424a);g.drawRect(8,36,32,8);g.endFill();
    g.beginFill(0xc8a23c);
    g.drawPolygon([17,24,5,11,15,27]);g.drawPolygon([31,24,43,11,33,27]);
    g.drawEllipse(24,25,7,10);g.drawCircle(24,12,5);g.endFill();
    g.beginFill(0x8a6a1c);g.drawPolygon([20,33,24,40,28,33]);g.endFill();
    g.beginFill(0x23282b);g.drawCircle(22,11,1.4);g.endFill();
    g.beginFill(0xe0b84c);g.drawPolygon([27,12,32,13,27,15]);g.endFill();
  }else if(t===TL.BAGS){
    g.beginFill(0x6a5c36);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x8a7a4a);
    g.drawRoundedRect(2,26,22,18,7);g.drawRoundedRect(24,26,22,18,7);g.drawRoundedRect(12,8,24,18,7);g.endFill();
    g.lineStyle(2,0x6a5c36);g.moveTo(14,17);g.lineTo(34,17);g.lineStyle(0);
  }else if(t===TL.CONCRETE){
    g.beginFill(0x98a0a4);g.drawRect(0,0,48,48);g.endFill();
    g.lineStyle(3,0x6a7276);g.drawRect(3,3,42,42);g.lineStyle(0);
    g.lineStyle(1.5,0x7d858a);g.moveTo(8,20);g.lineTo(22,12);g.lineTo(36,22);g.lineStyle(0);
    g.beginFill(0x5c6266);[[10,10],[38,38]].forEach(p=>g.drawCircle(p[0],p[1],2.5));g.endFill();
  }else if(t===TL.STEELW){
    g.beginFill(0x7c8c98);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x94a4b0);g.drawRect(2,2,44,8);g.endFill();
    g.beginFill(0x55636e);[[10,18],[38,18],[10,30],[38,30]].forEach(p=>g.drawCircle(p[0],p[1],2.5));g.endFill();
    g.beginFill(0xffb020,.9);for(let x=0;x<48;x+=12)g.drawPolygon([x,48,x+6,40,x+12,40,x+6,48]);
  }else if(t===TL.TURRET){
    g.beginFill(0x22282b);g.drawRect(0,0,48,48);g.endFill();
    g.beginFill(0x39424a);g.drawCircle(24,24,14);g.endFill();
    g.beginFill(0x2a3236);g.drawCircle(24,24,10);g.endFill();
    g.beginFill(0xb08030);g.drawCircle(24,24,4);g.endFill();
  }
  return g;
}
export function mkRubble(){
  const g=new PIXI.Graphics();
  g.beginFill(0x23282b);g.drawRect(0,0,48,48);g.endFill();
  g.beginFill(0x3a3f42);g.drawPolygon([6,40,14,22,22,34,30,18,40,40]);g.endFill();
  g.beginFill(0x57503a);g.drawPolygon([18,40,24,28,30,40]);g.endFill();
  g.beginFill(0x191d1f);g.drawCircle(12,36,2);g.drawCircle(36,34,2.5);g.endFill();
  return g;
}
export function mkTree(){
  const g=new PIXI.Graphics();
  g.beginFill(0x245c22,.95);
  g.drawCircle(14,16,10);g.drawCircle(30,12,11);g.drawCircle(24,30,12);g.drawCircle(38,32,9);g.drawCircle(10,34,8);g.endFill();
  g.beginFill(0x3a8a30,.9);g.drawCircle(16,14,5);g.drawCircle(30,12,5);g.drawCircle(24,28,6);g.endFill();
  return g;
}
export function placeTile(gx,gy,t,hp){
  const k=gx+','+gy;
  /* сначала зачищаем всё, что уже стоит в клетке, — иначе старый спрайт
     останется сиротой на экране и будет виден после разрушения нового */
  const old=tiles.get(k);
  if(old)removeTile(old);
  const oldTree=treeMap.get(k);
  if(oldTree){if(oldTree.el.parent)oldTree.el.parent.removeChild(oldTree.el);oldTree.el.destroy();treeMap.delete(k);}
  if(t===TL.TREE){
    const el=mkTree();el.position.set(BORDER+gx*CELL,BORDER+gy*CELL);treeLayer.addChild(el);
    treeMap.set(k,{gx,gy,el});return null}
  const el=mkTile(t,0);el.position.set(BORDER+gx*CELL,BORDER+gy*CELL);tileLayer.addChild(el);
  const maxHp=hp!=null?hp:(t===TL.CONCRETE?3:t===TL.TURRET?2:t===TL.BAGS?1:t===TL.STEELW?99:1);
  const tl={t,hp:maxHp,maxHp,gx,gy,el,cd:0,barrel:null,barBg:null,barFg:null};
  if(t===TL.TURRET){
    const b=new PIXI.Graphics();
    b.beginFill(0xb08030);b.drawRect(-3,-22,6,20);b.endFill();
    b.beginFill(0x11151a);b.drawRect(-4,-22,8,4);b.endFill();
    b.position.set(BORDER+gx*CELL+24,BORDER+gy*CELL+24);
    tileLayer.addChild(b);tl.barrel=b}
  if(t===TL.BAGS||t===TL.CONCRETE||t===TL.STEELW||t===TL.TURRET){
    const bw=32,bx=BORDER+gx*CELL+4,by=BORDER+gy*CELL+42;
    const bb=new PIXI.Graphics();bb.beginFill(0x0d1113,.85);bb.drawRect(0,0,bw,4);bb.endFill();bb.position.set(bx,by);
    const bf=new PIXI.Graphics();bf.beginFill(0xa5c46b);bf.drawRect(0,0,bw,4);bf.endFill();bf.position.set(bx,by);
    bb.visible=bf.visible=false;
    tileLayer.addChild(bb);tileLayer.addChild(bf);
    tl.barBg=bb;tl.barFg=bf;
  }
  tiles.set(k,tl);return tl;
}
export function removeTile(tl){
  tiles.delete(tl.gx+','+tl.gy);
  if(tl.el){if(tl.el.parent)tl.el.parent.removeChild(tl.el);tl.el.destroy({children:true});}
  if(tl.barrel){if(tl.barrel.parent)tl.barrel.parent.removeChild(tl.barrel);tl.barrel.destroy();}
  if(tl.barBg){if(tl.barBg.parent)tl.barBg.parent.removeChild(tl.barBg);tl.barBg.destroy();}
  if(tl.barFg){if(tl.barFg.parent)tl.barFg.parent.removeChild(tl.barFg);tl.barFg.destroy();}
}
export function clearCell(gx,gy){
  const k=gx+','+gy;
  const tl=tiles.get(k);
  if(tl&&tl.t!==TL.BASE)removeTile(tl);
  const tr=treeMap.get(k);if(tr){tr.el.destroy();treeMap.delete(k)}
}
export function genMap(){
  tiles.forEach(tl=>removeTile(tl));tiles.clear();
  treeMap.forEach(tr=>tr.el.destroy());treeMap.clear();
  const put=(gx,gy,t)=>{
    if(gx<0||gx>=GRID_W||gy<0||gy>=GRID_H)return;
    placeTile(gx,gy,t);
    if(gx<18)placeTile(36-gx,gy,t)};
  for(let gy=2;gy<=23;gy++)for(let gx=0;gx<=18;gx++){
    const r=Math.random();let t=null;
    if(r<.19)t=TL.BRICK;else if(r<.225)t=TL.STEEL;else if(r<.265)t=TL.WATER;else if(r<.335)t=TL.TREE;
    if(!t)continue;
    put(gx,gy,t);
    if(t===TL.BRICK&&Math.random()<.5){const ny=gy+(Math.random()<.6?1:-1);if(ny>=2&&ny<=23)put(gx,ny,t)}
    if(t===TL.TREE&&Math.random()<.6){const nx=gx+(Math.random()<.5?1:-1);if(nx>=0&&nx<=18)put(nx,gy,t)}
    if(t===TL.WATER&&Math.random()<.5&&gy<23)put(gx,gy+1,t);
  }
  for(let gx=0;gx<GRID_W;gx++){if(gx>=16&&gx<=20)continue;if(Math.random()<.15)placeTile(gx,24,TL.BRICK)}
  placeTile(BASE.gx,BASE.gy,TL.BASE);
  baseRing.forEach(([x,y])=>placeTile(x,y,TL.BRICK));
  [[0,0],[1,0],[0,1],[17,0],[18,0],[19,0],[18,1],[36,0],[35,0],[36,1],
   [13,25],[14,25],[14,24],[22,25],[23,25],[22,24],[18,23]].forEach(cc=>clearCell(cc[0],cc[1]));
}
export function buildGround(){
  groundLayer.removeChildren().forEach(c=>c.destroy({children:true}));
  const g=new PIXI.Graphics();
  const fw=FIELD_W+BORDER*2,fh=FIELD_H+BORDER*2;
  g.beginFill(0x14181a);g.drawRect(0,0,fw,fh);g.endFill();
  g.beginFill(0x101416);g.drawRect(BORDER,BORDER,FIELD_W,FIELD_H);g.endFill();
  g.lineStyle(1,0xffffff,.03);
  for(let i=1;i<GRID_W;i++){g.moveTo(BORDER+i*CELL,BORDER);g.lineTo(BORDER+i*CELL,BORDER+FIELD_H)}
  for(let i=1;i<GRID_H;i++){g.moveTo(BORDER,BORDER+i*CELL);g.lineTo(BORDER+FIELD_W,BORDER+i*CELL)}
  g.lineStyle(0);
  g.beginFill(0x262d31);
  g.drawRect(0,0,fw,BORDER);g.drawRect(0,fh-BORDER,fw,BORDER);
  g.drawRect(0,0,BORDER,fh);g.drawRect(fw-BORDER,0,BORDER,fh);g.endFill();
  g.lineStyle(2,0x39434a,.9);g.drawRect(BORDER,BORDER,FIELD_W,FIELD_H);g.lineStyle(0);
  g.beginFill(0xffb020,.7);
  for(let x=8;x<fw-8;x+=16){g.drawPolygon([x,4,x+8,4,x+4,10]);g.drawPolygon([x,fh-4,x+8,fh-4,x+4,fh-10])}
  g.endFill();
  groundLayer.addChild(g);
  GATE_X.forEach(gx=>{
    const m=new PIXI.Graphics();m.lineStyle(2,0xffb020,.6);
    const x=BORDER+gx*CELL,y=BORDER;
    m.moveTo(x+2,y+10);m.lineTo(x+2,y+2);m.lineTo(x+10,y+2);
    m.moveTo(x+38,y+2);m.lineTo(x+46,y+2);m.lineTo(x+46,y+10);
    m.lineStyle(0);groundLayer.addChild(m)});
  g.lineStyle(3,0xffb020,.06);g.drawCircle(BORDER+FIELD_W/2,BORDER+FIELD_H/2,170);g.lineStyle(0);
  const t1=new PIXI.Text('ПИТ · 07',{fontFamily:'Russo One',fontSize:110,fill:0xffffff,alpha:.045,letterSpacing:10});
  t1.anchor.set(.5);t1.position.set(BORDER+FIELD_W/2,BORDER+FIELD_H/2-30);groundLayer.addChild(t1);
  const t2=new PIXI.Text('СТАЛЬНОЙ РУБЕЖ',{fontFamily:'Russo One',fontSize:40,fill:0xffffff,alpha:.04,letterSpacing:14});
  t2.anchor.set(.5);t2.position.set(BORDER+FIELD_W/2,BORDER+FIELD_H-70);groundLayer.addChild(t2);
}
export function updWater(dt){
  const B=store.B;
  B.waterT+=dt;
  if(B.waterT<.5)return;
  B.waterT=0;B.waterFrame^=1;
  tiles.forEach(tl=>{
    if(tl.t!==TL.WATER)return;
    tl.el.destroy();
    tl.el=mkTile(TL.WATER,B.waterFrame);
    tl.el.position.set(BORDER+tl.gx*CELL,BORDER+tl.gy*CELL);
    tileLayer.addChild(tl.el)});
}
export function resetMap(){tiles.clear();treeMap.clear()}