import { app } from '../core/engine.js';
import { AudioFX } from '../core/audio.js';

/* Экран развёртки/загрузки. Живёт на app.stage поверх ui, крутится в своём update,
   не зависит от uiAnims (rebuildUI его не убьёт). Денди-техно стиль: затемнение,
   ползущая сетка, бегущая скан-линия, вращающаяся шестерня, сегментный прогресс
   в стиле обоймы, мигающий REC, угловые рамки. */

let root=null, bg=null, grid=null, scan=null, gear=null, ring=null;
let barBg=null, barSeg=[], pctTxt=null, statusTxt=null, recDot=null, recTxt=null;
let corners=[];

const state={
  visible:false, alpha:0, mode:'idle',     // idle | fadein | progress | fadeout
  time:0, prog:0, progSpeed:1.25,
  label:'', onDone:null, wantProgress:false,
};

const STATUS=[
  [0.00,'ИНИЦИАЛИЗАЦИЯ СИСТЕМ'],
  [0.18,'КАЛИБРОВКА ОРУДИЙ'],
  [0.40,'ЗАГРУЗКА КАРТЫ ПИТА 07'],
  [0.66,'РАССТАНОВКА ПРОТИВНИКА'],
  [0.88,'СИНХРОНИЗАЦИЯ СЛОЁВ'],
];
function statusFor(p){ let s=STATUS[0][1]; for(const row of STATUS) if(p>=row[0]) s=row[1]; return s; }

function txt(s,o={}){
  const{size=12,color=0xe9e4d6,font='mono',weight=400,ls=0}=o;
  return new PIXI.Text(s,{fontFamily:font==='disp'?'Russo One':'JetBrains Mono',
    fontSize:size,fill:color,fontWeight:weight,letterSpacing:ls});
}

function build(){
  root=new PIXI.Container();root.visible=false;
  app.stage.addChild(root);
  const W=app.screen.width,H=app.screen.height;

  bg=new PIXI.Graphics();
  bg.beginFill(0x080b0d,.94);bg.drawRect(0,0,W,H);bg.endFill();
  bg.beginFill(0x000000,.5);bg.drawEllipse(W/2,H/2,W*0.7,H*0.7); /* виньетка-обратная: центр чуть светлее */
  bg.endFill();
  root.addChild(bg);

  /* ползущая сетка-развёртка */
  grid=new PIXI.Graphics();
  grid.lineStyle(1,0x1c2a2e,.5);
  for(let x=0;x<=W;x+=40){grid.moveTo(x,-40);grid.lineTo(x,H+40);}
  for(let y=-40;y<=H+40;y+=40){grid.moveTo(0,y);grid.lineTo(W,y);}
  grid.lineStyle(0);
  root.addChild(grid);

  /* бегущая скан-линия */
  scan=new PIXI.Graphics();
  scan.beginFill(0xffb020,.10);scan.drawRect(0,0,W,46);
  scan.beginFill(0xffb020,.5);scan.drawRect(0,22,W,2);
  scan.endFill();
  root.addChild(scan);

  /* угловые рамки */
  corners=[];
  const m=26,L=46;
  const mk=(sx,sy,dx,dy)=>{const g=new PIXI.Graphics();g.lineStyle(2,0xffb020,.8);
    g.moveTo(sx,sy+dy*L);g.lineTo(sx,sy);g.lineTo(sx+dx*L,sy);g.lineStyle(0);
    g.beginFill(0xffb020);g.drawRect(sx-2,sy-2,4,4);g.endFill();return g;};
  corners.push(mk(m,m,1,1),mk(W-m,m,-1,1),mk(m,H-m,1,-1),mk(W-m,H-m,-1,-1));
  corners.forEach(c=>root.addChild(c));

  const cx=W/2, cy=H/2-30;

  /* пульсирующее кольцо */
  ring=new PIXI.Graphics();root.addChild(ring);ring.position.set(cx,cy);

  /* вращающаяся шестерня */
  gear=new PIXI.Graphics();
  gear.lineStyle(0);
  gear.beginFill(0x2a3338);gear.drawCircle(0,0,46);gear.endFill();
  gear.beginFill(0x3a454a);
  for(let k=0;k<12;k++){const a=k*Math.PI/6;
    gear.drawPolygon([Math.cos(a-0.16)*46,Math.sin(a-0.16)*46,
      Math.cos(a+0.16)*46,Math.sin(a+0.16)*46,
      Math.cos(a)*58,Math.sin(a)*58]);}
  gear.endFill();
  gear.beginFill(0x11161a);gear.drawCircle(0,0,30);gear.endFill();
  gear.beginFill(0xffb020);gear.drawCircle(0,0,7);gear.endFill();
  gear.beginFill(0x11161a);gear.drawCircle(0,0,3);gear.endFill();
  gear.position.set(cx,cy);
  root.addChild(gear);

  /* заголовок */
  const head=txt('СТАЛЬНОЙ РУБЕЖ',{size:13,font:'disp',color:0xffb020,ls:3});
  head.anchor.set(.5);head.position.set(cx,cy+84);root.addChild(head);

  /* статус */
  statusTxt=txt('',{size:10,color:0x9fb0ba,ls:2});
  statusTxt.anchor.set(.5);statusTxt.position.set(cx,cy+104);root.addChild(statusTxt);

  /* сегментный прогресс-бар (16 сегментов, как обойма) */
  const N=16, sw=14, gap=4, bw=N*sw+(N-1)*gap, bx=cx-bw/2, by=cy+124;
  barBg=new PIXI.Graphics();
  barBg.lineStyle(1,0x33404550 & 0xffffff,0.4);barBg.drawRect(bx-3,by-3,bw+6,16);barBg.lineStyle(0);
  root.addChild(barBg);
  barSeg=[];
  for(let i=0;i<N;i++){
    const g=new PIXI.Graphics();g.position.set(bx+i*(sw+gap),by);root.addChild(g);barSeg.push(g);
  }

  pctTxt=txt('0%',{size:11,weight:800,color:0xffb020});
  pctTxt.anchor.set(.5);pctTxt.position.set(cx,by+30);root.addChild(pctTxt);

  /* REC-индикатор */
  recDot=new PIXI.Graphics();recDot.beginFill(0xe0503c);recDot.drawCircle(0,0,3.5);recDot.endFill();
  recDot.position.set(cx-44,by+52);root.addChild(recDot);
  recTxt=txt('REC  ЗАПИСЬ ВЫЛАЗКИ',{size:8,color:0x8b968f,ls:2});
  recTxt.position.set(cx-34,by+50);root.addChild(recTxt);
}

function paintBar(p){
  const filled=Math.round(p*barSeg.length);
  for(let i=0;i<barSeg.length;i++){
    const g=barSeg[i];g.clear();
    if(i<filled){g.beginFill(0xffb020);g.drawRect(0,0,14,10);
      g.beginFill(0xffe08a);g.drawRect(0,0,14,2);g.endFill();}
    else{g.beginFill(0x1a2124);g.drawRect(0,0,14,10);g.endFill();}
  }
}

export function show(label){
  if(!root) build();
  state.visible=true; root.visible=true;
  state.alpha=0; state.mode='fadein'; state.time=0; state.prog=0;
  state.label=label||''; state.wantProgress=false; state.onDone=null;
  state.lastTickQuant=-1; state.resolved=false; AudioFX.bootChime();
  statusTxt.text=(label||'ЗАГРУЗКА').toUpperCase();
}
export function runProgress(onDone){
  state.wantProgress=true; state.onDone=onDone||null; state.progSpeed=1.15+Math.random()*0.4;
  if(state.mode==='idle') state.mode='progress';
}
export function fadeOut(onDone){
  state.mode='fadeout'; state.onDone=onDone||null;
}
export function hide(){ state.visible=false; if(root)root.visible=false; state.mode='idle'; }
export function isVisible(){ return state.visible; }

export function update(dt){
  if(!root) return;
  if(!state.visible){ root.visible=false; return; }
  state.time+=dt;
  const W=app.screen.width,H=app.screen.height;

  /* анимация фона всегда */
  grid.position.y=(state.time*22)%40;
  scan.position.y=((state.time*140)%(H+80))-40;
  gear.rotation+=dt*1.6;
  const rp=0.5+0.5*Math.sin(state.time*3);
  ring.clear();
  ring.lineStyle(2,0xffb020,0.25+0.35*rp);ring.drawCircle(0,0,66+rp*6);
  ring.lineStyle(1,0x79c7d4,0.15+0.2*(1-rp));ring.drawCircle(0,0,78+rp*4);ring.lineStyle(0);
  recDot.alpha=0.3+0.7*Math.abs(Math.sin(state.time*3));
  corners.forEach((c,i)=>{ c.alpha=0.55+0.45*Math.abs(Math.sin(state.time*2+i)); });

  if(state.mode==='fadein'){
    state.alpha=Math.min(1,state.alpha+dt*4.2);
    if(state.alpha>=1) state.mode=state.wantProgress?'progress':'idle';
  }else if(state.mode==='progress'){
    /* ступенчатый прогресс: иногда притормаживает, как настоящая загрузка */
    const jitter=0.55+0.9*Math.abs(Math.sin(state.time*5.3+state.prog*7));
    
    state.prog=Math.min(1,state.prog+dt*state.progSpeed*jitter);
    const q=Math.floor(state.prog*12); if(q!==state.lastTickQuant){state.lastTickQuant=q;AudioFX.loadingTick();}
    statusTxt.text=statusFor(state.prog);

    paintBar(state.prog);
    pctTxt.text=Math.floor(state.prog*100)+'%';
    // if(state.prog>=1 && state.onDone){ const cb=state.onDone; state.onDone=null; cb(); }
    if(state.prog>=1){ if(!state.resolved){state.resolved=true;AudioFX.loadingResolve();} if(state.onDone){ const cb=state.onDone; state.onDone=null; cb(); } }
  }else if(state.mode==='fadeout'){
    state.alpha=Math.max(0,state.alpha-dt*3.4);
    if(state.alpha<=0){ hide(); if(state.onDone){ const cb=state.onDone; state.onDone=null; cb(); } }
  }

  root.alpha=state.alpha;
}