import { store } from '../core/store.js';
import { GRID_W,GRID_H,CELL,BORDER,TS,TL,DX,DY,FIELD_W,FIELD_H } from '../config/world.js';
import { bulletLayer } from '../core/engine.js';
import { tiles } from '../world/map.js';
import { explosion,sparks } from '../fx/particles.js';
import { AudioFX } from '../core/audio.js';

/* радиус корпуса игрока для коллизий — константа, не зависит от полей объекта,
   чтобы «забытое поле» больше никогда не ломало попадания */
const PLAYER_R=20;

export function pushBullet(o){
  const g=new PIXI.Graphics();
  if(o.mortar){
    g.beginFill(0x2f352c);g.drawCircle(0,0,4);g.endFill();
    g.lineStyle(1.5,0xd99414);g.drawCircle(0,0,4);g.lineStyle(0);
  }else if(o.friendly){
    g.beginFill(0xffd27a);g.drawRect(-3,-3,6,6);g.endFill();
    g.beginFill(0xffffff);g.drawRect(-1.5,-1.5,3,3);g.endFill();
  }else{
    g.beginFill(0xff6a50);g.drawRect(-3,-3,6,6);g.endFill();
    g.beginFill(0xffc0a8);g.drawRect(-1.5,-1.5,3,3);g.endFill();
  }
  o.el=g;bulletLayer.addChild(g);store.B.bullets.push(o);
}
export function firePlayerBullet(t){
  const p=store.B.player;
  const bx=p.x+DX[p.dir]*(TS/2+6),by=p.y+DY[p.dir]*(TS/2+6);
  const n=t.def.pellets||1,sp=t.def.bspd*CELL;
  for(let k=0;k<n;k++){
    const a=(k-(n-1)/2)*(t.def.spread||0);
    const vx0=DX[p.dir],vy0=DY[p.dir];
    const vx=vx0*Math.cos(a)-vy0*Math.sin(a),vy=vx0*Math.sin(a)+vy0*Math.cos(a);
    pushBullet({x:bx,y:by,vx:vx*sp,vy:vy*sp,dmg:t.def.dmg,
      life:t.def.range/t.def.bspd,friendly:true,gi:0,
      splash:t.def.splash||0,pierce:t.def.pierce||0,breakSteel:!!t.def.breakSteel});
  }
  sparks(BORDER+bx,BORDER+by,2,0xfff3cf);
}
export function countPB(){let n=0;for(const b of store.B.bullets)if(b.friendly&&b.gi===0)n++;return n}
export function countEB(e){let n=0;for(const b of store.B.bullets)if(!b.friendly&&b.owner===e)n++;return n}

export function hitTile(tl,b){
  const B=store.B;
  const cx=BORDER+tl.gx*CELL+CELL/2,cy=BORDER+tl.gy*CELL+CELL/2;
  switch(tl.t){
    // case TL.BRICK: removeTileLocal(tl);explosion(cx,cy,12);return true;
    case TL.BRICK: removeTileLocal(tl);explosion(cx,cy,12);AudioFX.metalBreak();return true;
    case TL.BAGS: tl.hp--;if(tl.hp<=0){removeTileLocal(tl);sparks(cx,cy,6,0xa08a52)}return true;
    case TL.CONCRETE: tl.hp--;tl.el.tint=0xffc0a0;
      if(tl.hp<=0){removeTileLocal(tl);explosion(cx,cy,12);AudioFX.metalBreak()}else sparks(cx,cy,3,0xb9c2c8);
      return true;
    case TL.TURRET:
      if(b.friendly){sparks(cx,cy,3,0xd8dde0);return true}
      tl.hp--;if(tl.hp<=0){removeTileLocal(tl);explosion(cx,cy,14);AudioFX.metalBreak()}
      return true;
    case TL.STEEL: case TL.STEEL_TEMP: case TL.STEELW:
      if(b.friendly&&b.breakSteel){removeTileLocal(tl);explosion(cx,cy,14);AudioFX.metalBreak();b.pierce--;return b.pierce<0}
      AudioFX.clank();sparks(cx,cy,3,0xd8dde0);return true;
    case TL.BASE: B._baseHit=true;return true;   // флаг → battle.js вызовет destroyBase
    default: return false;
  }
}
function removeTileLocal(tl){
  const { tiles:TM }={ tiles };
  TM.delete(tl.gx+','+tl.gy);
  if(tl.el&&tl.el.parent)tl.el.parent.removeChild(tl.el);
  if(tl.el)tl.el.destroy({children:true});
  if(tl.barrel){if(tl.barrel.parent)tl.barrel.parent.removeChild(tl.barrel);tl.barrel.destroy();}
  if(tl.barBg){if(tl.barBg.parent)tl.barBg.parent.removeChild(tl.barBg);tl.barBg.destroy();}
  if(tl.barFg){if(tl.barFg.parent)tl.barFg.parent.removeChild(tl.barFg);tl.barFg.destroy();}
}

export function updBullets(dt){
  const B=store.B,bs=B.bullets;
  for(let i=bs.length-1;i>=0;i--){
    const b=bs[i];
    if(bs.indexOf(b)<0)continue;
    b.life-=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;
    b.el.position.set(BORDER+b.x,BORDER+b.y);
    if(b.mortar&&b.maxLife){const pr=Math.max(0,Math.min(1,1-b.life/b.maxLife));b.el.scale.set(1+Math.sin(pr*Math.PI)*.9);}
    let dead=b.life<=0;
    if(dead&&b.mortar){
      const gx=Math.floor(b.x/CELL),gy=Math.floor(b.y/CELL);
      const tl=tiles.get(gx+','+gy);
      if(tl)hitTile(tl,{friendly:true,breakSteel:false});
      for(const e of B.enemies){if(Math.hypot(e.x-b.x,e.y-b.y)<(b.splash||52)){e.hp-=b.dmg;e.flash=.12;}}
      explosion(BORDER+b.x,BORDER+b.y,18);
    }
    if(!dead){
      for(let j=bs.length-1;j>=0;j--){
        if(j===i)continue;const o=bs[j];
        if(o.friendly!==b.friendly&&Math.abs(o.x-b.x)<8&&Math.abs(o.y-b.y)<8){
          sparks(BORDER+b.x,BORDER+b.y,5,0xfff3cf);
          if(o.el&&!o.el.destroyed)o.el.destroy();
          bs.splice(Math.max(i,j),1);bs.splice(Math.min(i,j),1);
          dead=true;break;
        }
      }
    }
    if(!dead&&b.friendly&&!b.mortar){
      for(const e of B.enemies){
        if(b.hitSet&&b.hitSet.has(e))continue;
        // const rr=e.r+4;
        const rr=(e.r||18)+4;
        if((e.x-b.x)**2+(e.y-b.y)**2<rr*rr){
          e.hp-=b.dmg;e.flash=.12;
          if(b.splash){for(const o of B.enemies){if(o!==e&&Math.hypot(o.x-b.x,o.y-b.y)<b.splash){o.hp-=Math.max(1,b.dmg-1);o.flash=.12;}}explosion(BORDER+b.x,BORDER+b.y,14);}
          if(b.pierce>0){b.pierce--;(b.hitSet=b.hitSet||new Set()).add(e);}else dead=true;
          break;
        }
      }
    }
    if(!dead&&!b.friendly&&!B.over){
      const p=B.player,dx=p.x-b.x,dy=p.y-b.y;
      if(dx*dx+dy*dy<(PLAYER_R+3)*(PLAYER_R+3)){
        B._playerHit={d:b.dmg,sx:b.x,sy:b.y};   // флаг → player.js нанесёт урон с отдачей
        dead=true;
      }
    }
    if(!dead&&!b.mortar){
      const gx=Math.floor(b.x/CELL),gy=Math.floor(b.y/CELL);
      if(gx<0||gx>=GRID_W||gy<0||gy>=GRID_H){dead=true;sparks(BORDER+Math.max(4,Math.min(FIELD_W-4,b.x)),BORDER+Math.max(4,Math.min(FIELD_H-4,b.y)),3);}
      else{const tl=tiles.get(gx+','+gy);if(tl)dead=hitTile(tl,b);}
    }
    if(dead){const k=bs.indexOf(b);if(k>=0)bs.splice(k,1);if(b.el&&!b.el.destroyed)b.el.destroy();}
  }
}