import { store } from '../core/store.js';
import { emit } from '../core/bus.js';
import { AudioFX } from '../core/audio.js';
import * as Music from '../core/music.js';
import { txt, mkPanel, Btn, Toggle, Scroll } from './widgets.js';
import { buildMixerSection } from './mixer.js';
import { toggleSound, toggleMusic, doReset } from '../garage/garage.js';
import { C } from '../config/world.js';

/* окно настроек. Закрывается через шину, чтобы не тянуть screens.js (иначе цикл импортов). */
export function closeSettings(){
  const fromBattle = !!(store.uiState.modal && store.uiState.modal.fromBattle);
  store.uiState.modal = fromBattle ? {type:'pause'} : null;   // в бою → обратно в паузу, в гараже → закрыть
  emit('ui:rebuild');
}

let resetArmed=false;   // inline-подтверждение сброса (живёт между перерисовками тела)

/* рисованная шестерня-иконка для шапки */
function gearIcon(r){
  const g=new PIXI.Graphics();
  g.beginFill(0x39434a);g.drawCircle(0,0,r);g.endFill();
  g.beginFill(0x4d5a60);
  for(let k=0;k<8;k++){const a=k*Math.PI/4;
    g.drawPolygon([Math.cos(a-.18)*r,Math.sin(a-.18)*r,Math.cos(a+.18)*r,Math.sin(a+.18)*r,Math.cos(a)*(r+5),Math.sin(a)*(r+5)]);}
  g.endFill();
  g.beginFill(0x141a1c);g.drawCircle(0,0,r*.55);g.endFill();
  g.beginFill(0xffb020);g.drawCircle(0,0,r*.22);g.endFill();
  return g;
}
/* заголовок секции — «шильдик» с цветной полосой */
function sectionHead(parent,y,label,color){
  const bar=new PIXI.Graphics();bar.beginFill(color);bar.drawRect(0,0,3,14);bar.endFill();bar.position.set(0,y+1);parent.addChild(bar);
  const t=txt(label,{size:10,font:'disp',color,ls:2});t.position.set(10,y);parent.addChild(t);
  const ln=new PIXI.Graphics();ln.beginFill(0x232b2f);ln.drawRect(0,y+18,parent.__w||300,1);ln.endFill();ln.position.set(0,0);parent.addChild(ln);
  return y+28;
}

export function buildSettingsModal(card,W,H){
  resetArmed = resetArmed && true;   // сохраняем состояние подтверждения
  const pad=18;
  /* шапка */
  const gear=gearIcon(11);gear.position.set(pad+12,pad+12);card.addChild(gear);
  import('./anims.js').then(a=>a.regAnim(gear,dt=>{gear.rotation+=dt*.6;}));
  const title=txt('НАСТРОЙКИ',{size:18,font:'disp',color:C.ink,ls:2});title.position.set(pad+32,pad+2);card.addChild(title);
  const sub=txt('звук · баланс · данные игры',{size:8.5,color:C.faint,ls:1});sub.position.set(pad+34,pad+24);card.addChild(sub);
  const headH=pad*2+24;

  /* кнопка закрыть — всегда внизу, вне скролла */
  const footH=58;
  const bClose=new Btn('ЗАКРЫТЬ',{w:W-pad*2,h:40,variant:'primary',fs:12,on:closeSettings});
  bClose.position.set(pad,H-footH+8);card.addChild(bClose);

  /* тело со скроллом (влезает даже в мобильном ландшафте) */
  const bodyY=headH+4, bodyH=H-headH-footH-12;
  const sc=new Scroll(W-pad*2,bodyH);sc.position.set(pad,bodyY);card.addChild(sc);
  const content=sc.content; content.__w=W-pad*2;
  let y=4;

  /* ── СЕКЦИЯ: ЗВУК ── */
  y=sectionHead(content,y,'ЗВУК',C.amber);
  const tSound=new Toggle(W-pad*2,40,'ЗВУК ЭФФЕКТОВ','все выстрелы, взрывы, интерфейс',()=>store.S.sound,()=>{toggleSound();});
  tSound.position.set(0,y);content.addChild(tSound);y+=44;
  const tMusic=new Toggle(W-pad*2,40,'ФОНОВАЯ МУЗЫКА','процедурный эмбиент-секвенсор',()=>store.S.music,()=>{toggleMusic();});
  tMusic.position.set(0,y);content.addChild(tMusic);y+=52;

  /* ── СЕКЦИЯ: БАЛАНС ЗВУКА ── */
  y=sectionHead(content,y,'БАЛАНС ЗВУКА',C.cyan);
  y=buildMixerSection(content,0,y,W-pad*2);
  y+=12;

  /* ── СЕКЦИЯ: ДАННЫЕ ── */
  y=sectionHead(content,y,'ДАННЫЕ И ПРОГРЕСС',C.red);
  const hint=txt('Сброс удаляет болты, контейнеры, модули, рекорды и настройки звука. Действие необратимо.',{size:8.5,color:C.faint,wrap:W-pad*2-8});
  hint.position.set(0,y);content.addChild(hint);y+=hint.height+10;
  if(!resetArmed){
    const bReset=new Btn('СБРОСИТЬ ПРОГРЕСС',{w:W-pad*2,h:38,variant:'danger',fs:10,on:()=>{resetArmed=true;emit('ui:rebuild');}});
    bReset.position.set(0,y);content.addChild(bReset);y+=46;
  }else{
    const armBox=new PIXI.Graphics();armBox.beginFill(0x2a1416);armBox.drawRoundedRect(0,0,W-pad*2,40,8);armBox.endFill();
    armBox.lineStyle(1.5,C.red,.8);armBox.drawRoundedRect(0,0,W-pad*2,40,8);armBox.lineStyle(0);
    armBox.position.set(0,y);content.addChild(armBox);
    const q=txt('ТОЧНО СБРОСИТЬ ВСЁ?',{size:10,weight:800,color:0xffb0a6});q.position.set(14,y+13);content.addChild(q);
    const bw=(W-pad*2-14*2-110)/2;
    const bYes=new Btn('ДА, СБРОСИТЬ',{w:bw,h:28,variant:'danger',fs:9,on:()=>{resetArmed=false;doReset();}});
    bYes.position.set(W-pad*2-14-bw*2-8,y+6);content.addChild(bYes);
    const bNo=new Btn('ОТМЕНА',{w:bw,h:28,fs:9,on:()=>{resetArmed=false;emit('ui:rebuild');}});
    bNo.position.set(W-pad*2-14-bw,y+6);content.addChild(bNo);
    y+=50;
  }
  y+=8;
  sc.layout(y);
}