import { store } from '../core/store.js';
import { GRID_W,GRID_H,CELL,TS,FIELD_W,FIELD_H,SOLID,DX,DY } from '../config/world.js';
import { tiles } from '../world/map.js';

/* порог наложения танк-танк (сумма полуразмеров физических хитбоксов).
   Чуть меньше визуального размера (44) → плотный притык с микро-зазором,
   без осцилляции; редкие проникновения доразруливаются pushApart по осям. */
export const TANK_SEP=42;

export function rectHitsSolid(nx,ny,s){
  const h=s/2;
  const x0=Math.floor((nx-h)/CELL),x1=Math.floor((nx+h-.1)/CELL),
        y0=Math.floor((ny-h)/CELL),y1=Math.floor((ny+h-.1)/CELL);
  for(let gx=x0;gx<=x1;gx++)for(let gy=y0;gy<=y1;gy++){
    if(gx<0||gx>=GRID_W||gy<0||gy>=GRID_H)return true;
    const tl=tiles.get(gx+','+gy);
    if(tl&&SOLID.has(tl.t))return true}
  return false;
}
export function hitsTank(nx,ny,half,self){
  for(const e of store.B.enemies){if(e===self)continue;
    if(Math.abs(e.x-nx)<half&&Math.abs(e.y-ny)<half)return true}
  if(self!==store.B.player&&!store.B.over&&Math.abs(store.B.player.x-nx)<half&&Math.abs(store.B.player.y-ny)<half)return true;
  return false;
}
export function nearestEnemy2(x,y,r){
  let best=null,bd=r*r;
  for(const e of store.B.enemies){const d=(e.x-x)**2+(e.y-y)**2;if(d<bd){bd=d;best=e}}
  return best;
}
export function frontCell(){
  const p=store.B.player;
  return{gx:Math.floor(p.x/CELL)+DX[p.dir],gy:Math.floor(p.y/CELL)+DY[p.dir]};
}
export function placeValid(gx,gy){
  const B=store.B;
  if(gx<0||gx>=GRID_W||gy<0||gy>=GRID_H)return false;
  if(gy===0&&(gx<=1||gx>=GRID_W-2||Math.abs(gx-18)<=1))return false;
  const k=gx+','+gy;
  if(tiles.has(k))return false;
  if(B.pickups.some(p=>p.gx===gx&&p.gy===gy))return false;
  if(hitsTank(gx*CELL+CELL/2,gy*CELL+CELL/2,TANK_SEP+10,null))return false;
  return true;
}

/* ── поосевое разведение двух танков (убирает «диагональный слип») ── */
function inBounds(x,y){return x>=TS/2&&x<=FIELD_W-TS/2&&y>=TS/2&&y<=FIELD_H-TS/2;}
function canStand(x,y){return inBounds(x,y)&&!rectHitsSolid(x,y,TS);}
export function pushApart(ax,ay,bx,by,canA,canB){
  const dx=bx-ax, dy=by-ay;
  const ox=TANK_SEP-Math.abs(dx), oy=TANK_SEP-Math.abs(dy);
  if(ox<=0||oy<=0)return{ax,ay,bx,by};          // наложения нет — ничего не делаем
  if(ox<oy){                                     // разводим по X (меньшее проникновение)
    const s=dx>=0?1:-1;
    let da=-s*ox/2, db=s*ox/2;                   // пополам…
    if(!canA(ax+da,ay)){da=0;db=s*ox;}           // …если одному нельзя — весь сдвиг на другого
    if(!canB(bx+db,by)){db=0;da=-s*ox;}
    if(canA(ax+da,ay))ax+=da;
    if(canB(bx+db,by))bx+=db;
  }else{                                         // разводим по Y
    const s=dy>=0?1:-1;
    let da=-s*oy/2, db=s*oy/2;
    if(!canA(ax,ay+da)){da=0;db=s*oy;}
    if(!canB(bx,by+db)){db=0;da=-s*oy;}
    if(canA(ax,ay+da))ay+=da;
    if(canB(bx,by+db))by+=db;
  }
  return{ax,ay,bx,by};
}
export function separatePlayer(B){
  const p=B.player, canP=canStand;
  for(const e of B.enemies){
    const r=pushApart(p.x,p.y,e.x,e.y,canP,canStand);
    p.x=r.ax;p.y=r.ay;e.x=r.bx;e.y=r.by;
  }
}