function hex(g,cx,cy,r){const p=[];for(let k=0;k<6;k++){const a=Math.PI/6+k*Math.PI/3;p.push(cx+Math.cos(a)*r,cy+Math.sin(a)*r);}g.drawPolygon(p);}
function draw(kind,g){
  if(kind==='bolts'||kind==='repair'){
    g.beginFill(0xb9c2c8);g.drawRect(6,1,4,13);g.endFill();
    g.beginFill(0x6a7278);g.drawRect(6,8,4,1);g.drawRect(6,11,4,1);g.endFill();
    g.beginFill(0xdfe5e8);hex(g,8,4,3.6);g.endFill();
    g.lineStyle(1,0x4a545a);hex(g,8,4,3.6);g.lineStyle(0);
    g.beginFill(0x2a3338);g.drawCircle(8,4,1.3);g.endFill();
    if(kind==='repair'){g.beginFill(0x6fc37a);g.drawRect(2,2,3,3);g.endFill();}
  }else if(kind==='box'||kind==='boxes'){
    g.beginFill(0x9a6a3a);g.drawRect(2,4,12,10);g.endFill();
    g.beginFill(0xb0803c);g.drawRect(2,3,12,3);g.endFill();
    g.beginFill(0xd99414);g.drawRect(7,3,2,11);g.drawRect(2,7,12,2);g.endFill();
    g.lineStyle(1,0x5a3a1c);g.drawRect(2,3,12,11);g.lineStyle(0);
  }else if(kind==='gears'){
    g.beginFill(0x9fb0ba);g.drawCircle(8,8,5);
    for(let k=0;k<8;k++){const a=k*Math.PI/4;g.drawRect(8+Math.cos(a)*6-1.5,8+Math.sin(a)*6-1.5,3,3);}
    g.endFill();
    g.beginFill(0x2a3338);g.drawCircle(8,8,2.4);g.endFill();
    g.beginFill(0x6a7278);g.drawCircle(8,8,1);g.endFill();
  }else if(kind==='shield'){
    g.beginFill(0x79c7d4);g.drawPolygon([8,1,14,4,14,9,8,15,2,9,2,4]);g.endFill();
    g.beginFill(0xbfeec6);g.drawPolygon([8,4,11,5.5,11,8.5,8,11.5,5,8.5,5,5.5]);g.endFill();
  }else if(kind==='shovel'){
    g.beginFill(0x9fb0ba);g.drawRect(7,1,2,8);g.endFill();
    g.beginFill(0x8a7428);g.drawPolygon([4,9,12,9,10,15,6,15]);g.endFill();
  }
}
export function drawIcon(kind,g,size){ g.clear(); g.scale.set((size||16)/16); draw(kind,g); }
export function mkIcon(kind,size){ const g=new PIXI.Graphics(); drawIcon(kind,g,size); return g; }