import { AudioFX } from './audio.js';

const N={A2:110,C3:130.81,D3:146.83,E3:164.81,F3:174.61,G3:196,A3:220,B3:246.94,
  C4:261.63,D4:293.66,E4:329.63,F4:349.23,G4:392,A4:440,C5:523.25,E5:659.25,G5:783.99,A5:880};
const BPM=88, STEP=60/BPM/4;
const BASS=[N.A2,N.C3,N.E3,N.A2, N.F3,N.G3,N.E3,N.A2];
const ARP =[N.A4,N.C5,N.E5,N.A5,N.E5,N.C5];
const PADS=[[N.A3,N.C4,N.E4],[N.F3,N.A3,N.C4],[N.E3,N.G3,N.B3],[N.G3,N.B3,N.D4]];

let ctx=null, master=null, started=false, on=true, paused=false, userGain=1;
let next=0, step=0;

function env(g,t,a,d,peak){ g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(peak,t+a); g.gain.exponentialRampToValueAtTime(0.0001,t+a+d); }
function voice(freq,t,dur,type,peak,dest,detune){
  const o=ctx.createOscillator(),g=ctx.createGain();
  o.type=type; o.frequency.value=freq; if(detune)o.detune.value=detune;
  const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=type==='sawtooth'?900:2400;
  o.connect(f); f.connect(g); g.connect(dest); env(g,t,0.01,dur,peak); o.start(t); o.stop(t+dur+0.05);
}
function kick(t){
  const o=ctx.createOscillator(),g=ctx.createGain(); o.type='sine'; o.connect(g); g.connect(master);
  o.frequency.setValueAtTime(120,t); o.frequency.exponentialRampToValueAtTime(45,t+0.12);
  g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.5,t+0.005); g.gain.exponentialRampToValueAtTime(0.0001,t+0.18);
  o.start(t); o.stop(t+0.2);
}
function schedule(s,t){
  const chord=Math.floor(s/32)%4;
  if(s%32===0){ PADS[chord].forEach(f=>{ voice(f,t,32*STEP*0.95,'triangle',0.045,master,6); voice(f,t,32*STEP*0.95,'sine',0.03,master,-6); }); }
  if(s%4===0){ voice(BASS[Math.floor(s/4)%8],t,STEP*3.4,'sawtooth',0.11,master); kick(t); }
  voice(ARP[s%6],t,STEP*0.8,'square',0.022,master);
}
function baseLevel(){ return !on?0 : (paused?0.18:0.5); }
export function start(){
  AudioFX.ensure(); ctx=AudioFX.ctx; if(!ctx) return;
  if(!master){ master=ctx.createGain(); master.gain.value=0.0; master.connect(ctx.destination); }
  started=true; next=ctx.currentTime+0.1; step=0;
}
export function setEnabled(b){ on=b; if(master&&ctx) master.gain.value=baseLevel()*userGain; }
export function setPaused(p){ paused=p; if(master&&ctx) master.gain.value=baseLevel()*userGain; }
export function setGain(v){ userGain=v; if(master&&ctx) master.gain.value=baseLevel()*userGain; }   // ← ползунок
export function tick(dt){
  if(!started||!ctx||!master) return;
  if(!AudioFX.on){ master.gain.value=0; return; }
  const target=baseLevel()*userGain;
  if(on&&!paused && master.gain.value<target-0.01) master.gain.value=Math.min(target,master.gain.value+dt*0.4);
  const ahead=ctx.currentTime+0.2;
  while(next<ahead){ schedule(step,next); step++; next+=STEP; }
}