import { store } from '../core/store.js';
import { uiRefs } from './refs.js';
import { txt } from '../ui/widgets.js';
import { regAnim } from './anims.js';
import { C,FORTS } from '../config/world.js';
import { setTxt,mmss } from '../utils/helpers.js';
// import { fmt, full, isCompact } from './numbers.js';
import { fmt } from './numbers.js';

export function log(msg,cls='info'){
  const lc=store.HUD.logC;if(!lc)return;
  store.uiState.log.unshift({msg,cls,time:store.B?mmss(store.B.time):'00:00'});
  if(store.uiState.log.length>9)store.uiState.log.pop();
  renderLog(true);
}
export function renderLog(anim){
  const lc=store.HUD.logC;if(!lc)return;
  const LOGC={info:0x4a555a,good:0x8fa05a,warn:0xffb020,bad:0xe0503c,boss:0xe0503c};
  lc.removeChildren().forEach(ch=>ch.destroy({children:true}));
  store.uiState.log.forEach((e,i)=>{
    const en=new PIXI.Container();en.position.set(anim&&i===0?24:0,i*22);
    const bg=new PIXI.Graphics();bg.beginFill(0x0d1113,.78);bg.drawRect(0,0,272,19);bg.endFill();
    bg.beginFill(LOGC[e.cls]||0x4a555a);bg.drawRect(0,0,3,19);bg.endFill();en.addChild(bg);
    const tm=txt(e.time,{size:8.5,color:C.faint});tm.position.set(8,5);en.addChild(tm);
    const mt=txt(e.msg.length>36?e.msg.slice(0,35)+'…':e.msg,{size:9,color:e.cls==='boss'?0xffb0a6:C.ink});mt.position.set(46,5);en.addChild(mt);
    en.alpha=i>=4?.5:1;
    if(anim&&i===0){en.__s=1;regAnim(en,dt=>{en.__s=Math.max(0,en.__s-dt*4);en.x=24*en.__s})}
    lc.addChild(en)});
}
export function announce(main,cls='',hold=1.8,sub=''){
  store.uiState.ann={main,cls,hold,sub,t:0};
  const ANN=uiRefs.ANN;
  if(ANN){ANN.main.text=main;ANN.sub.text=sub||'';
    ANN.main.style.fill=cls==='boss'?C.red:cls==='good'?C.olive:C.ink;
    ANN.c.visible=true}
}
export function toast(msg){
  store.uiState.toastMsg=msg;
  store.uiState.toastT=2.4;
  renderToast();
}
export function renderToast(){
  const TOAST=uiRefs.TOAST;
  if(!TOAST||!store.uiState.toastMsg)return;
  TOAST.t.text=store.uiState.toastMsg;
  const w=TOAST.t.width+36;
  TOAST.bg.clear();
  TOAST.bg.beginFill(0x1b2124);TOAST.bg.drawRect(0,0,w,30);TOAST.bg.endFill();
  TOAST.bg.lineStyle(1,0x364045);TOAST.bg.drawRect(.5,.5,w-1,29);TOAST.bg.lineStyle(0);
  TOAST.bg.position.set(-w/2,-15);
  TOAST.c.visible=true;TOAST.c.alpha=1;
}
export function syncRes(){
  const S=store.S, GAR=store.GAR||{}, HUD=store.HUD||{};
  const set=(obj,k,val)=>{ const r=obj&&obj.res&&obj.res[k];
    if(typeof r==='function') r(val);        // trackNum-сеттер (сокращает по режиму)
    else if(r) setTxt(r, fmt(val)); };       // обычная Text-нода → тоже сокращаем
  ['bolts','boxes','gears'].forEach(k=>{ set(GAR,k,S[k]); set(HUD,k,S[k]); });
  if(GAR.recTxt) setTxt(GAR.recTxt,'РЕКОРД: ВОЛНА '+S.record);
  if(GAR.bCraft){ GAR.bCraft.setDisabled(S.boxes<1); if(GAR.bBuy)GAR.bBuy.setDisabled(S.bolts<150); }
}
export function syncHUD(){
  const {HUD,B,S}=store;
  if(!HUD||!HUD.wave||!B)return;const p=B.player;
  setTxt(HUD.wave,B.wave?String(B.wave).padStart(2,'0'):'—');
  const rem=B.spawnQ.length+B.spawnFX.length+B.enemies.length;
  /* счёт форматируется по текущему режиму; клик по строке переключает режим (см. screens.js) */
  // setTxt(HUD.sub,'ВРАГИ: '+rem+' · СЧЁТ: '+(isCompact()?fmt(B.score):full(B.score)));
  setTxt(HUD.sub,'ВРАГИ: '+rem+' · СЧЁТ: '+fmt(B.score));
  // setTxt(HUD.run,'ЗА ВЫЛАЗКУ: +'+(isCompact()?fmt(B.boltsRun):full(B.boltsRun))
  //   +(B.boxesRun?' · +'+B.boxesRun:'')+(B.gearsRun?' · +'+B.gearsRun:''));
    setTxt(HUD.run,'ЗА ВЫЛАЗКУ: +'+fmt(B.boltsRun)
    +(B.boxesRun?' · +'+B.boxesRun:'')+(B.gearsRun?' · +'+B.gearsRun:''));
  setTxt(HUD.rec,'REC '+mmss(B.time));
  if(HUD.baseT){ setTxt(HUD.baseT,B.base.alive?'ШТАБ: ЦЕЛ':'ШТАБ: ПОТЕРЯН');
    HUD.baseT.style.fill=B.base.alive?C.olive:C.red; }
  if(HUD.retT){
    if(p.unstuckCd<=0){ setTxt(HUD.retT,'ВЫБРАТЬСЯ [R]: ГОТОВ'); HUD.retT.style.fill=C.olive; }
    else { setTxt(HUD.retT,'ВЫБРАТЬСЯ [R]: '+Math.ceil(p.unstuckCd)+'С'); HUD.retT.style.fill=C.amber; }
  }
  if(HUD.eicons&&rem!==HUD.elast){HUD.elast=rem;HUD.eicons.clear();
    for(let i=0;i<rem;i++){const col=i%10,row=Math.floor(i/10);
      HUD.eicons.beginFill(0xffb020,.85);HUD.eicons.drawRect(col*11,row*11,8,8);HUD.eicons.endFill();}}
  const hp=Math.max(0,Math.min(1,p.hp/p.maxHp));
  if(HUD.barHull){HUD.barHull.set(hp);HUD.barHull.low=hp<=1;}
  if(HUD.nHull)setTxt(HUD.nHull,p.hp+'/'+p.maxHp);
  if(HUD.barTrance)HUD.barTrance.set(p.tranceE/B.stats.tranceMax);
  if(HUD.nTrance)setTxt(HUD.nTrance,String(Math.round(p.tranceE)));
  if(HUD.barDash){
    const canD=!!B.stats.canDash;
    HUD.barDash.set(canD?Math.max(0,1-p.dashCd/4):0);
    HUD.barDash.low=canD&&p.dashCd>0;
  }
  if(HUD.nDash){
    const canD=!!B.stats.canDash;
    if(!canD){ setTxt(HUD.nDash,'НЕТ'); HUD.nDash.style.fill=C.faint; }
    else if(p.dashCd>0){ setTxt(HUD.nDash,Math.ceil(p.dashCd)+'С'); HUD.nDash.style.fill=C.amber; }
    else { setTxt(HUD.nDash,'ГОТОВ'); HUD.nDash.style.fill=C.cyan; }
  }
  /* ресурсы: GAR/HUD.res[k] теперь сеттеры от trackNum */
  if(HUD.res){ const r=HUD.res;
    if(typeof r.bolts==='function')r.bolts(S.bolts);
    if(typeof r.boxes==='function')r.boxes(S.boxes);
    if(typeof r.gears==='function')r.gears(S.gears); }
  if(HUD.cards)HUD.cards.forEach((c,i)=>{const poor=S.bolts<FORTS[i].cost;if(c.poor!==poor){c.poor=poor;c.redraw();}});
  if(HUD.ammo)HUD.ammo.forEach(a=>{
    const cur=a.t.clip;
    if(cur!==a.last){a.last=cur;a.pips.clear();
      const pw=a.pipW||9, ph=a.pipH||12;
      for(let k=0;k<a.clip;k++){a.pips.beginFill(k<cur?0xffb020:0x2a3338);a.pips.drawRect(k*pw,0,pw-2,ph);a.pips.endFill();}}
    const rld=a.t.def.rld||1;
    a.fill.scale.x=Math.max(.01,a.t.rel>0?1-a.t.rel/rld:1);
    const rel=a.t.rel>0;
    setTxt(a.st,rel?'ПЕРЕЗАРЯДКА':(a.t.clip>0?'ГОТОВ':'ПУСТО'));
    a.st.style.fill=rel?C.amber:(a.t.clip>0?C.olive:C.red);
    a.st.alpha=rel?(.6+.4*Math.abs(Math.sin((globalThis.__t||0)*8))):1;
  });
}