import { store } from '../core/store.js';
import { uiRefs } from './refs.js';
import { CMF } from '../core/engine.js';
import { clamp,easeOutBack } from '../utils/helpers.js';

export const uiAnims=new Set();
export function regAnim(owner,fn){uiAnims.add({owner,fn})}
export function clearAnims(){uiAnims.clear()}

export function updUI(ds,t){
  const {GAR,HUD,uiState,B}=store;
  for(const a of [...uiAnims]){
    if(!a.owner||a.owner.destroyed){uiAnims.delete(a);continue}
    try{a.fn(ds)}catch(e){uiAnims.delete(a)}
  }
  const FX=uiRefs.FX;
  if(FX.dmg){FX.dmg.alpha=uiState.flashA;uiState.flashA=Math.max(0,uiState.flashA-ds*3.2)}
  if(FX.trance){const tr=B&&B.player&&B.player.trance?.85:0;FX.trance.alpha+=(tr-FX.trance.alpha)*Math.min(1,ds*6)}
  CMF.enabled=!!(B&&B.player&&B.player.trance);
  if(GAR.saveInd){GAR.saveInd.alpha=uiState.saveT;uiState.saveT=Math.max(0,uiState.saveT-ds*.7)}
  if(HUD.dot)HUD.dot.alpha=.25+.75*Math.abs(Math.sin(t*3));
  if(uiState.ann&&uiRefs.ANN){
    const a=uiState.ann,ANN=uiRefs.ANN;a.t+=ds;
    ANN.c.scale.set(easeOutBack(Math.min(1,a.t/.35)));
    ANN.c.alpha=a.t>a.hold?Math.max(0,1-(a.t-a.hold)/.4):1;
    if(a.t>a.hold+.4){uiState.ann=null;ANN.c.visible=false}
  }
  if(uiRefs.TOAST&&uiState.toastT>0){
    uiState.toastT-=ds;
    uiRefs.TOAST.c.visible=true;
    uiRefs.TOAST.c.alpha=clamp(uiState.toastT/.3,0,1);
    if(uiState.toastT<=0)uiRefs.TOAST.c.visible=false;
  }
}