export const CMF=new PIXI.ColorMatrixFilter();CMF.saturate(-.55,false);CMF.enabled=false;

function radialTex(size,stops){
  const c=document.createElement('canvas');c.width=c.height=size;
  const x=c.getContext('2d'),g=x.createRadialGradient(size/2,size/2,0,size/2,size/2,size/2);
  stops.forEach(s=>g.addColorStop(s[0],`rgba(${s[1]},${s[2]},${s[3]},${s[4]})`));
  x.fillStyle=g;x.fillRect(0,0,size,size);return PIXI.Texture.from(c);
}
export const TEX_VIG=radialTex(512,[[0,0,0,0,0],[.6,0,0,0,0],[1,0,0,0,.6]]);
export const TEX_DMG=radialTex(512,[[0,213,60,45,0],[.55,213,60,45,0],[1,213,60,45,.55]]);
export const TEX_TRANCE=radialTex(512,[[0,121,199,212,0],[.62,121,199,212,0],[1,121,199,212,.4]]);
const scC=document.createElement('canvas');scC.width=1;scC.height=3;
const scX=scC.getContext('2d');scX.fillStyle='rgba(255,255,255,0.9)';scX.fillRect(0,0,1,1);
export const TEX_SCAN=PIXI.Texture.from(scC);