import { store } from '../core/store.js';
import { AudioFX } from '../core/audio.js';
import * as EngineSound from '../core/engineSound.js';
import * as Music from '../core/music.js';
import { txt } from './widgets.js';
import { C } from '../config/world.js';

/* Пять каналов. sfx/boom/gun/hit крутят шины audio, engine/music — свои гейны. */
const CHANNELS=[
  {key:'sfx',   label:'ЭФФЕКТЫ'},
  {key:'boom',  label:'ВЗРЫВЫ'},
  {key:'gun',   label:'ВЫСТРЕЛЫ'},
  {key:'engine',label:'ДВИГАТЕЛЬ'},
  {key:'music', label:'МУЗЫКА'},
];
const DEF={sfx:1, boom:1, gun:1, engine:0.8, music:0.6};
const SKEY='sr_mixer_v1';
let vals=load();
function load(){ try{const d=JSON.parse(localStorage.getItem(SKEY)); if(d)return Object.assign({},DEF,d);}catch(e){} return Object.assign({},DEF); }
function save(){ try{localStorage.setItem(SKEY,JSON.stringify(vals))}catch(e){} }

function setChannel(key,v){
  vals[key]=v;
  if(key==='engine') EngineSound.setGain(v);
  else if(key==='music') Music.setGain(v);
  else AudioFX.setBusGain(key,v);
}
export function applyMix(){ CHANNELS.forEach(c=>setChannel(c.key, vals[c.key])); }

let globalBound=false, drag=null;
function bindGlobal(){
  if(globalBound) return; globalBound=true;
  window.addEventListener('pointermove',e=>{
    if(!drag) return;
    const x=drag.track.getGlobalPosition().x;
    const v=Math.max(0,Math.min(1,(e.clientX-x)/drag.TW));
    drag.val=v; setChannel(drag.key,v); drawSlider(drag); save();
  });
  window.addEventListener('pointerup',()=>{drag=null;});
  window.addEventListener('pointercancel',()=>{drag=null;});
}
function drawSlider(sl){
  const g=sl.bg; g.clear(); const TW=sl.TW, H=14, v=sl.val;
  g.beginFill(0x0d1113); g.drawRoundedRect(0,0,TW,H,4); g.endFill();
  g.lineStyle(1,0x2a3338); g.drawRoundedRect(.5,.5,TW-1,H-1,4); g.lineStyle(0);
  g.beginFill(0xd99414); g.drawRoundedRect(1,1,Math.max(2,(TW-2)*v),H-2,3); g.endFill();
  g.beginFill(0xffe08a); g.drawRoundedRect(1,1,Math.max(2,(TW-2)*v),2,1); g.endFill();
  for(let i=1;i<10;i++){ g.beginFill(0x000000,.35); g.drawRect(Math.round(TW*i/10),2,1,H-4); g.endFill(); }
  g.beginFill(0xffe6b0); g.drawRoundedRect(Math.round((TW-6)*v)+1,-2,6,H+4,2); g.endFill();
  g.lineStyle(1,0x8a6205); g.drawRoundedRect(Math.round((TW-6)*v)+1,-2,6,H+4,2); g.lineStyle(0);
  sl.valTxt.text=Math.round(v*100);
}

/* встраиваемая секция ползунков (для окна настроек). возвращает занятую высоту */
export function buildMixerSection(parent,x,y,W){
  bindGlobal();
  const TW=Math.min(240,W-150), x0=W-TW-44, rowH=32;
  CHANNELS.forEach((c,i)=>{
    const ry=y+i*rowH;
    const lb=txt(c.label,{size:9.5,weight:700,color:C.ink}); lb.position.set(x,ry+1); parent.addChild(lb);
    const bg=new PIXI.Graphics(); bg.position.set(x+x0,ry); parent.addChild(bg);
    bg.eventMode='static'; bg.cursor='pointer'; bg.hitArea=new PIXI.Rectangle(0,-4,TW,22);
    const valTxt=txt('100',{size:9.5,weight:800,color:C.amber}); valTxt.anchor.set(1,0); valTxt.position.set(x+W,ry+1); parent.addChild(valTxt);
    const sl={bg,valTxt,key:c.key,val:vals[c.key],TW,track:bg};
    bg.on('pointerdown',e=>{ drag=sl; const gx=bg.getGlobalPosition().x; sl.val=Math.max(0,Math.min(1,(e.clientX-gx)/TW)); setChannel(c.key,sl.val); drawSlider(sl); save(); });
    drawSlider(sl);
  });
  return y+CHANNELS.length*rowH;
}