import { fxLayer } from '../core/engine.js';
import { AudioFX } from '../core/audio.js';
import { rnd } from '../utils/helpers.js';
import { store } from '../core/store.js';
import { drawIcon } from '../ui/icons.js';

const parts=[],floats=[];
const MAX_PARTS=220;

export function part(o){
  let p=parts.find(p=>!p.active);
  // if(!p){
  //   if(parts.length>=MAX_PARTS){p=parts[0];let mn=p.life;for(const q of parts){if(q.active&&q.life<mn){mn=q.life;p=q;}}}
  //   else{p={g:new PIXI.Graphics()};parts.push(p);}
  // }
  if(!p){
    if(parts.length>=340){ p=parts[0]; let mn=p.life; for(const q of parts){ if(q.active&&q.life<mn){mn=q.life;p=q;} } }
    else { p={g:new PIXI.Graphics()}; parts.push(p); }
  }
  if(!p.g.parent)fxLayer.addChild(p.g);
  Object.assign(p,o,{active:true,max:o.life,grow:o.grow||0,drag:o.drag||0});
  p.g.clear();
  if(o.shape==='ring'){p.g.lineStyle(2.5,o.color,1);p.g.drawCircle(0,0,o.size);}
  else{p.g.beginFill(o.color,1);
    if(o.shape==='circle')p.g.drawCircle(0,0,o.size);
    else p.g.drawRect(-o.size/2,-o.size/2,o.size,o.size);p.g.endFill();}
  p.g.position.set(o.x,o.y);p.g.rotation=o.rot||0;p.g.scale.set(1);p.g.visible=true;p.g.alpha=1;
}
export function updParts(dt){
  for(const p of parts){if(!p.active)continue;
    p.life-=dt;if(p.life<=0){p.active=false;p.g.visible=false;continue;}
    p.x+=p.vx*dt;p.y+=p.vy*dt;const dr=1-p.drag*dt;p.vx*=dr;p.vy*=dr;
    if(p.grow)p.g.scale.set(1+(1-p.life/p.max)*p.grow);
    p.g.position.set(p.x,p.y);p.g.alpha=Math.max(0,p.life/p.max);}
}
export function explosion(x,y,r,big){
  part({x,y,vx:0,vy:0,life:.13,color:0xfff3cf,size:r*1.1,shape:'circle'});
  part({x,y,vx:0,vy:0,life:.4,color:0xffb020,size:r*.5,shape:'ring',grow:r/5});
  const n=big?18:9;
  for(let i=0;i<n;i++){const a=rnd(0,Math.PI*2),s=rnd(80,big?380:260);
    part({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rnd(.25,.5),
      color:[0xffb020,0xff7847,0xffe9b0,0xd4574a][i%4],size:rnd(2,5),drag:3});}
  for(let i=0;i<(big?6:3);i++)
    part({x:x+rnd(-6,6),y:y+rnd(-6,6),vx:rnd(-30,30),vy:rnd(-45,-10),life:rnd(.5,.9),
      color:0x5a6266,size:rnd(6,12),shape:'circle',grow:1.6,drag:1});
  if(store.B)store.B.shake=Math.min(16,store.B.shake+(big?10:3)+r*.08);
  AudioFX.boom(big);
}
export function sparks(x,y,n,color){
  n=n||4;color=color||0xffd27a;
  for(let i=0;i<n;i++){const a=rnd(0,Math.PI*2),s=rnd(60,190);
    part({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rnd(.12,.28),color,size:rnd(1.5,3),drag:4});}
}
/* всплывающий текст + опциональная векторная иконка справа */
export function floatText(x,y,str,color,size,iconKind){
  let f=floats.find(f=>!f.active);
  if(!f){
    if(floats.length>=40){f=floats[0];let mn=f.life;for(const q of floats){if(q.active&&q.life<mn){mn=q.life;f=q;}}}
    else{
      f={c:new PIXI.Container(),
         t:new PIXI.Text('',{fontFamily:'JetBrains Mono',fontWeight:'700',fontSize:14,stroke:0x0a0c0d,strokeThickness:4}),
         icon:null};
      f.t.anchor.set(.5,0);
      f.c.addChild(f.t);
      floats.push(f);fxLayer.addChild(f.c);
    }
  }
  Object.assign(f,{active:true,life:.95,max:.95});
  f.t.text=str;f.t.style.fill=color||0xffd27a;f.t.style.fontSize=size||14;
  if(iconKind){
    if(!f.icon){f.icon=new PIXI.Graphics();f.c.addChild(f.icon);}
    drawIcon(iconKind,f.icon,(size||14)+2);
    f.icon.visible=true;
    f.icon.position.set(f.t.width/2+3,-2);
  }else if(f.icon){ f.icon.visible=false; }
  f.t.position.set(0,0);
  f.c.visible=true;f.c.alpha=1;f.c.position.set(x,y);
}
export function updFloats(dt){
  for(const f of floats){if(!f.active)continue;
    f.life-=dt;if(f.life<=0){f.active=false;f.c.visible=false;continue;}
    f.c.y-=46*dt;f.c.alpha=f.life/f.max;}
}
export function resetParticles(){
  parts.forEach(p=>p.active=false);
  floats.forEach(f=>{f.active=false;if(f.c)f.c.visible=false;});
}