import { store } from '../core/store.js';
import { MODULES } from '../config/modules.js';
import { clamp } from '../utils/helpers.js';

export function calcStats(){
  const lo=store.S.loadout;
  const hull=MODULES[lo.hull]||MODULES.hull_medium;
  const gun=lo.gun?MODULES[lo.gun]:null;
  const eng=MODULES[lo.engine]||MODULES.eng_base;
  const gear=MODULES[lo.gear]||MODULES.gear_tracks;
  const opt=lo.optics?MODULES[lo.optics]:null;
  const pow=lo.power?MODULES[lo.power]:null;
  const aux=[lo.aux1,lo.aux2].map(id=>id?MODULES[id]:null).filter(Boolean);
  const weight=hull.w+gear.w+(eng.w||0);
  const speed=clamp(eng.spd+gear.add-weight*.02,1.4,3.2);
  const range=gun?gun.range+(opt?opt.rng:0):0;
  let dps=0;
  if(gun){const rld=gun.rld*eng.rlm;dps=gun.dmg*(gun.pellets||1)*gun.clip/(gun.clip/gun.rate+rld);dps=Math.round(dps*10)/10}
  return{hp:hull.hp,weight,speed,range,dps,
    tranceMax:pow?pow.cap:100,tranceReg:pow?pow.reg:13,relMult:eng.rlm,
    canBuild:aux.some(a=>a.id==='aux_eng'),canTurret:aux.some(a=>a.id==='aux_turret'),
    canDash:!!eng.dash,
    mortars:aux.filter(a=>a.id==='aux_mortar').length,
    // dHeal:aux.filter(a=>a.id==='aux_dh').length*2,
    dHeal: aux.filter(a=>a.id==='aux_dh').reduce((s,a)=>s+((MODULES[a.id]||{}).drones||2),0),
    dAtk:aux.filter(a=>a.id==='aux_da').length*2,
    gun};
}