import { store,save } from '../core/store.js';
import { pad2,shuffle } from '../utils/helpers.js';
import { log,announce,syncRes } from '../ui/hud.js';
import { AudioFX } from '../core/audio.js';

export function buildQueue(n){
  const q=[];
  if(n%5===0){
    q.push({type:'boss'});
    for(let i=0;i<3+Math.floor(n/5);i++)q.push({type:'scout'});
  }else{
    const total=Math.min(24,8+n*2);
    const pool=[];
    const add=(t,cc)=>{for(let i=0;i<cc;i++)pool.push(t)};
    add('scout',Math.max(2,10-n));add('assault',2+n);
    if(n>=2)add('sapper',1+n);
    if(n>=3)add('ram',Math.floor((n-1)/2));
    while(pool.length<total)pool.push('scout');
    shuffle(pool);
    for(let i=0;i<total;i++)q.push({type:pool[i]});
  }
  q.forEach((e,i)=>{if((i+1)%4===0&&e.type!=='boss')e.bonus=true});
  return q;
}
export function startWave(n){
  const B=store.B;
  B.wave=n;B.spawnQ=buildQueue(n);B.state='combat';B.spawnT=.5;B.gateIdx=Math.floor(Math.random()*3);
  B.tank.turrets.forEach(t=>{t.clip=t.def.clip;t.rel=0});
  log('БОЕКОМПЛЕКТ ПОПОЛНЕН','good');
  const boss=n%5===0;
  announce('ВОЛНА '+pad2(n),boss?'boss':'',2.2,boss?'!! ОБНАРУЖЕН БРОНЕНОСЕЦ !!':B.spawnQ.length+' ТАНКОВ В КВАДРАТЕ');
  log('ВОЛНА '+n+' — КОНТАКТ'+(boss?' · БОСС':''),'warn');
  AudioFX.horn();
}
export function waveClear(){
  const B=store.B;
  const bolts=15+5*B.wave,gears=B.wave%2===0?1:0;
  store.S.bolts+=bolts;B.boltsRun+=bolts;B.score+=100*B.wave;
  if(gears){store.S.gears++;B.gearsRun++}
  announce('ВОЛНА ЗАЧИЩЕНА','good',1.8,'+'+bolts+' B'+(gears?' · +'+gears+' G':''));
  log('ВОЛНА '+B.wave+' ЗАЧИЩЕНА · +'+bolts+' B','good');
  B.state='inter';B.interT=6;B.lastSec=99;
  save();syncRes();
}