import './core/pixi.js';
import { app } from './core/engine.js';
import { store } from './core/store.js';
import { on } from './core/bus.js';
import { initInput } from './core/input.js';
import { initTouch, setTouchVisible } from './core/touch.js';
import * as api from './game/api.js';
import * as flow from './game/flow.js';
import { rebuildUI, initScreens } from './ui/screens.js';
import { updUI } from './ui/anims.js';
import { buildGarageScene, updGarage, G } from './garage/garage.js';
import { updBattle, handleBattleOver } from './game/battle.js';
import { updParts, updFloats } from './fx/particles.js';
import * as loader from './ui/loader.js';
import { AudioFX, Turntable } from './core/audio.js';
import * as EngineSound from './core/engineSound.js';
import * as Music from './core/music.js';
import { applyMix } from './ui/mixer.js';

if(typeof PIXI==='undefined'){
  document.body.insertAdjacentHTML('beforeend',
    '<div id="fatal" style="position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:#0e1113;color:#e9e4d6;font-family:monospace;text-align:center;padding:20px">⚠ ДВИЖОК PIXIJS НЕ ЗАГРУЗИЛСЯ</div>');
  throw new Error('PIXI not loaded');
}

on('ui:rebuild', () => rebuildUI());
on('battle:over', handleBattleOver);

initInput(api);
initTouch(api);
initScreens();
buildGarageScene();
rebuildUI();
applyMix();   // восстановленные ползунки микшера (запомнятся в шинах до первого жеста)

/* разблокировка аудио первым жестом + старт фоновой мелодии */
let audioUnlocked=false;
function unlockAudio(){
  AudioFX.ensure();
  if(!audioUnlocked){ audioUnlocked=true;
    Music.setEnabled(store.S.music); Music.start();
    EngineSound.setEnabled(store.mode==='battle'); }
}
window.addEventListener('pointerdown', unlockAudio, {once:false});
window.addEventListener('keydown', unlockAudio, {once:false});

let globalT=0, bootDone=false;
let loopErr=null, battleErr=null, garageErr=null;
let lastTouchVis=null, lastPaused=false;

/* ★ окно загрузки при самом запуске игры */
loader.show('ЗАГРУЗКА АНГАРА');
loader.runProgress(() => loader.fadeOut());

app.ticker.add(() => {
  const wantTouch = store.mode==='battle' && !!store.B && store.B.active && !store.B.over && !store.B.paused;
  if(wantTouch!==lastTouchVis){ lastTouchVis=wantTouch; setTouchVisible(wantTouch); }

  const ds=Math.min(app.ticker.deltaMS,50)/1000;
  globalT+=ds; globalThis.__t=globalT;

  /* звуковые движки тикают всегда (плавно затухают вне своих сцен) */
  const inGarage = store.mode==='garage' && !G.departing && !G.arriving;
  Turntable.setTarget(inGarage?1:0); Turntable.frame(ds);
  EngineSound.setEnabled(store.mode==='battle' && !!store.B && store.B.active && !store.B.over);
  EngineSound.frame(ds);
  const paused = !!(store.B&&store.B.paused);
  if(paused!==lastPaused){ lastPaused=paused; Music.setPaused(paused); }
  Music.tick(ds);

  loader.update(ds);

  try{
    if(store.mode==='garage'){
      try{ updGarage(ds,globalT); }
      catch(err){ if(!garageErr){garageErr=err;console.error('[РУБЕЖ] ошибка ангара:',err);} }
    }else if(store.B){
      if(store.B.active && !store.B.paused){
        try{ updBattle(ds); }
        catch(err){ if(!battleErr){battleErr=err;console.error('[РУБЕЖ] ошибка боя:',err);} }
      }
      updParts(ds*store.B.timeScale);
      updFloats(ds*store.B.timeScale);
    }
    updUI(ds,globalT);
    bootDone=true;
  }catch(err){
    if(!loopErr){loopErr=err;console.error('[РУБЕЖ] ошибка цикла:',err);}
  }
});

if(document.fonts && document.fonts.ready){
  document.fonts.ready.then(()=>{ try{ buildGarageScene(); rebuildUI(); }catch(e){} });
}