import { store } from '../core/store.js';
import { CELL,BORDER,FORTS,FORTDEF,FORT2TILE,TILE2FORT,DX,DY,SOLID,TL,FIELD_W,FIELD_H } from '../config/world.js';
import { world } from '../core/engine.js';
import { tiles,placeTile,removeTile } from '../world/map.js';
import { AudioFX } from '../core/audio.js';
import { frontCell,placeValid } from './collision.js';
import { pushBullet } from './bullets.js';
import { log,toast,syncRes } from '../ui/hud.js';
import { save } from '../core/store.js';
import { sparks,explosion } from '../fx/particles.js';
import { clamp } from '../utils/helpers.js';

export let ghost=null;
export function makeGhost(){ghost=new PIXI.Graphics();world.addChild(ghost);return ghost}
export function removeGhost(){if(ghost){world.removeChild(ghost);ghost=null}}

export function selectFort(i){
  const B=store.B;if(!B)return;B.sel=i;
  if(store.HUD.cards)store.HUD.cards.forEach((c,k)=>{c.sel=(k===i);c.redraw()});
}
export function denyCard(){
  const cards=store.HUD.cards;
  if(cards&&cards[store.B.sel])cards[store.B.sel].shake();
  AudioFX.err();
}
export function tryPlace(){
  const B=store.B,fc=frontCell(),def=FORTS[B.sel];
  if(def.id==='turret'&&!B.stats.canTurret){toast('НУЖЕН ТУРЕЛЬНЫЙ МОДУЛЬ');denyCard();return}
  if(def.id!=='turret'&&!B.stats.canBuild){toast('НУЖЕН ИНЖЕНЕРНЫЙ МОДУЛЬ');denyCard();return}
  if(!placeValid(fc.gx,fc.gy)){denyCard();return}
  // if(store.S.bolts<def.cost){toast('НЕ ХВАТАЕТ 🔩');denyCard();AudioFX.err();return}
  if(store.S.bolts<def.cost){toast('НЕ ХВАТАЕТ БОЛТОВ');denyCard();AudioFX.err();return}
  store.S.bolts-=def.cost;
  placeTile(fc.gx,fc.gy,FORT2TILE[def.id]);
  sparks(BORDER+fc.gx*CELL+CELL/2,BORDER+fc.gy*CELL+CELL/2,6,0xb9c2c8);
  AudioFX.place();
  // log(def.name+' · УСТАНОВЛЕНО (−'+def.cost+'🔩)','good');
  log(def.name+' · УСТАНОВЛЕНО (−'+def.cost+' B)','good');
  save();syncRes();
}
export function demolish(){
  const fc=frontCell(),tl=tiles.get(fc.gx+','+fc.gy);
  if(!tl||!TILE2FORT[tl.t]){toast('НЕТ УКРЕПЛЕНИЯ ВПЕРЕДИ');return}
  const def=FORTDEF[TILE2FORT[tl.t]];
  const refund=Math.floor(def.cost/2);store.S.bolts+=refund;
  removeTile(tl);
  sparks(BORDER+fc.gx*CELL+CELL/2,BORDER+fc.gy*CELL+CELL/2,5,0x8a949a);
  // log(def.name+' · СНЕСЁН (+'+refund+'🔩)','warn');
  log(def.name+' · СНЕСЁН (+'+refund+' B)','warn');
  save();syncRes();
}
export function updForts(dt){
  tiles.forEach(tl=>{
    if(tl.t!==TL.TURRET)return;
    tl.cd-=dt;
    if(tl.cd>0)return;
    const cx=tl.gx*CELL+CELL/2,cy=tl.gy*CELL+CELL/2;
    for(let d=0;d<4;d++){
      let found=false;
      for(let s=1;s<=5;s++){
        const px=cx+DX[d]*CELL*s,py=cy+DY[d]*CELL*s;
        if(px<0||px>FIELD_W||py<0||py>FIELD_H)break;
        const t2=tiles.get(Math.floor(px/CELL)+','+Math.floor(py/CELL));
        if(t2&&SOLID.has(t2.t))break;
        for(const e of store.B.enemies){
          if(Math.abs(e.x-px)<20&&Math.abs(e.y-py)<20){
            pushBullet({x:cx+DX[d]*24,y:cy+DY[d]*24,vx:DX[d]*8*CELL,vy:DY[d]*8*CELL,
              dmg:1,life:.8,friendly:true,gi:99});
            if(tl.barrel)tl.barrel.rotation=d*Math.PI/2;
            tl.cd=1.3;found=true;
            AudioFX.tone(760,.05,'square',.03,-400);break}}
        if(found)break}
      if(found)break}});
}
export function updGhost(){
  const B=store.B;
  if(!ghost)return;
  if(!B.active||B.paused||B.over){ghost.visible=false;return}
  const fc=frontCell(),ok=placeValid(fc.gx,fc.gy);
  ghost.clear();
  ghost.lineStyle(2,ok?0x8fae5a:0xd4574a,.95);
  ghost.beginFill(ok?0x8fae5a:0xd4574a,.18);
  ghost.drawRect(BORDER+fc.gx*CELL+2,BORDER+fc.gy*CELL+2,CELL-4,CELL-4);
  ghost.endFill();ghost.lineStyle(0);
  ghost.visible=true;
  ghost.alpha=.5+Math.sin(B.time*6)*.2;
}
export function damageFort(tl,d,hx,hy){
  tl.hp-=d;
  if(tl.barBg){tl.barBg.visible=tl.barFg.visible=true;tl.barFg.scale.x=clamp(tl.hp/tl.maxHp,0,1);}
  if(hx!==undefined)sparks(hx,hy,3,0xb9c2c8);
  if(tl.hp<=0)destroyFort(tl,true);
}
export function destroyFort(tl,byEnemy){
  const cx=BORDER+tl.gx*CELL+CELL/2,cy=BORDER+tl.gy*CELL+CELL/2;
  removeTile(tl);
  explosion(cx,cy,14);
  if(byEnemy)log('УКРЕПЛЕНИЕ РАЗРУШЕНО','warn');
}