import { app } from './engine.js';
import { input } from './input.js';
import { store } from './store.js';
import { FORTS } from '../config/world.js';
import { toast } from '../ui/hud.js';
import { txt } from '../ui/widgets.js';
import { ACTIONS, TOUCH_AUX } from '../config/controls.js';

let layer=null, visible=false, actionsRef=null;
let joyId=null, fireId=null;
let joy=null, fire=null, pauseBtn=null, ring=null;
let aux=[], buildPanel=null;
let buildOpen=false;
const baseHits=[];

export function isTouchDevice(){return ('ontouchstart' in window)||(navigator.maxTouchPoints>0);}

export function initTouch(actions){
  actionsRef=actions;
  if(!isTouchDevice()) return;
  input.touchDevice=true;
  layer=new PIXI.Container();
  app.stage.addChild(layer);
  layer.visible=false;
  build();
  layout();
  window.addEventListener('resize',layout);
  window.addEventListener('pointerdown',onDown);
  window.addEventListener('pointermove',onMove);
  window.addEventListener('pointerup',onUp);
  window.addEventListener('pointercancel',onUp);
  app.ticker.add(upd);
}
export function setTouchVisible(v){
  visible=v;
  if(layer)layer.visible=v;
  if(!v){buildOpen=false;joyId=fireId=null;input.keys.Space=false;
    input.keys.KeyA=input.keys.KeyD=input.keys.KeyW=input.keys.KeyS=false;
    if(joy){joy.dx=joy.dy=0;joy.knob.position.set(0,0);}
    if(fire){fire.held=false;paintBtn(fire);}
  }
}
function mkBtn(label,sub,r,col){
  const c=new PIXI.Container();
  const glow=new PIXI.Graphics();c.addChild(glow);
  const bg=new PIXI.Graphics();c.addChild(bg);
  const t1=txt(label,{size:9,color:col});t1.anchor.set(.5);t1.position.set(0,sub?-3:0);c.addChild(t1);
  const t2=txt(sub,{size:8,color:0x8b968f});t2.anchor.set(.5);t2.position.set(0,9);c.addChild(t2);
  const o={c,bg,glow,r,flash:0,held:false};
  paintBtn(o);
  return o;
}
function paintBtn(o){
  o.bg.clear();
  o.bg.beginFill(0x1d2427);o.bg.drawCircle(0,0,o.r);o.bg.endFill();
  o.bg.lineStyle(1.5,(o.held||o.flash>0)?0xffb020:0x3d484d,1);o.bg.drawCircle(0,0,o.r);o.bg.lineStyle(0);
  o.bg.beginFill(0xffffff,.05);o.bg.drawCircle(-o.r*.2,-o.r*.25,o.r*.5);o.bg.endFill();
  o.glow.clear();
  if(o.held||o.flash>0){o.glow.lineStyle(2,0xffb020,.5);o.glow.drawCircle(0,0,o.r+3);o.glow.lineStyle(0);}
}
function pulse(b){if(b){b.flash=.14;paintBtn(b);}}
function build(){
  joy={c:new PIXI.Container(),base:new PIXI.Graphics(),knob:new PIXI.Graphics(),dx:0,dy:0};
  ring=new PIXI.Graphics();
  joy.base.beginFill(0x141a1d);joy.base.drawCircle(0,0,66);joy.base.endFill();
  joy.base.lineStyle(1.5,0x3d484d,1);joy.base.drawCircle(0,0,66);joy.base.lineStyle(0);
  ring.lineStyle(1,0xffb020,.28);
  for(let k=0;k<12;k++)ring.arc(0,0,52,k*Math.PI/6,k*Math.PI/6+Math.PI/9);
  joy.knob.beginFill(0xc98a10);joy.knob.drawCircle(0,0,28);joy.knob.endFill();
  joy.knob.beginFill(0xffc44d);joy.knob.drawCircle(-6,-7,16);joy.knob.endFill();
  joy.c.addChild(joy.base,ring,joy.knob);layer.addChild(joy.c);

  fire=mkBtn(ACTIONS.fire.label,'',47,0x1c1405);
  fire.bg.clear();
  fire.bg.beginFill(0xd99414);fire.bg.drawCircle(0,0,47);fire.bg.endFill();
  fire.bg.lineStyle(2,0x8a6205);fire.bg.drawCircle(0,0,47);fire.bg.lineStyle(0);
  fire.bg.beginFill(0xffd257);fire.bg.drawCircle(-12,-14,22);fire.bg.endFill();
  layer.addChild(fire.c);

  pauseBtn=mkBtn('❚','',21,0x8b968f);layer.addChild(pauseBtn.c);

  /* кластер действий собирается из таблицы привязок */
  const defs=TOUCH_AUX.map(a=>[ACTIONS[a].label,ACTIONS[a].sub,a]).concat([['СТРОЙ','☰','buildmenu']]);
  aux=defs.map(([l,s,act])=>{const b=mkBtn(l,s,29,act==='buildmenu'?0xa5c46b:0xe9e4d6);b.act=act;layer.addChild(b.c);return b;});

  buildPanel=new PIXI.Container();buildPanel.h=300;
  buildPanel.bg=new PIXI.Graphics();buildPanel.addChild(buildPanel.bg);
  const head=txt('ЧЕРТЁЖ УКРЕПЛЕНИЯ',{size:10,color:0x9fb0ba,ls:2});head.position.set(16,16);buildPanel.addChild(head);
  buildPanel.close=mkBtn('✕','',16,0xe9e4d6);buildPanel.addChild(buildPanel.close.c);
  buildPanel.rows=[];
  FORTS.forEach((f,i)=>{
    const row=new PIXI.Container();row.idx=i;
    row.rbg=new PIXI.Graphics();row.addChild(row.rbg);
    const ixBox=new PIXI.Graphics();ixBox.beginFill(0x0d1113);ixBox.drawRoundedRect(14,12,24,24,6);ixBox.endFill();
    ixBox.lineStyle(1,0x3d484d);ixBox.drawRoundedRect(14,12,24,24,6);ixBox.lineStyle(0);row.addChild(ixBox);row.ixBox=ixBox;
    const ix=txt(String(i+1),{size:12,weight:800,color:0xffb020});ix.position.set(26,24);ix.anchor.set(.5);row.addChild(ix);row.ix=ix;
    const nm=txt(f.name,{size:13,font:'disp',color:0xe9e4d6});nm.position.set(50,12);row.addChild(nm);
    const hp=txt(typeof f.hp==='number'?f.hp+' HP':f.hp,{size:10,color:0x8b968f});hp.position.set(50,30);row.addChild(hp);
    row.bolt=(typeof mkIconSafe==='function')?null:null;
    const cost=txt(String(f.cost),{size:12,weight:800,color:0xffb020});cost.position.set(app.screen.width-50,20);row.addChild(cost);row.cost=cost;
    buildPanel.addChild(row);buildPanel.rows.push(row);
  });
  layer.addChild(buildPanel);
}
function mkIconSafe(){return null;}
function layout(){
  if(!layer)return;
  baseHits.length=0;
  const W=app.screen.width,H=app.screen.height,portrait=H>=W;
  const BS=58,GAP=8;
  const jx=portrait?80:88, jy=H-(portrait?86:88);
  joy.c.position.set(jx,jy);
  baseHits.push({type:'joy',cx:jx,cy:jy,r:74});
  const fx=W-(portrait?63:77), fy=H-(portrait?73:75);
  fire.c.position.set(fx,fy);
  baseHits.push({type:'fire',cx:fx,cy:fy,r:53});
  pauseBtn.c.position.set(portrait?W-33:W/2, portrait?118:74);
  baseHits.push({type:'pause',cx:pauseBtn.c.x,cy:pauseBtn.c.y,r:25});
  const rightEdge=portrait?W-16:W-150;
  const blockW=2*BS+GAP, blockLeft=rightEdge-blockW;
  const rowsN=Math.ceil(aux.length/2);
  const blockH=rowsN*BS+(rowsN-1)*GAP, blockTop=H-(portrait?150:36)-blockH;
  aux.forEach((b,i)=>{
    const col=i%2,row=Math.floor(i/2);
    b.c.position.set(blockLeft+col*(BS+GAP)+BS/2, blockTop+row*(BS+GAP)+BS/2);
    baseHits.push({type:'aux',act:b.act,cx:b.c.x,cy:b.c.y,r:33});
  });
  const rowH=52,pad=16,headH=44;
  buildPanel.h=headH+pad+FORTS.length*rowH+pad;
  buildPanel.bg.clear();
  buildPanel.bg.beginFill(0x0e1214,.97);buildPanel.bg.drawRect(0,0,W,buildPanel.h);buildPanel.bg.endFill();
  buildPanel.bg.lineStyle(2,0xffb020,1);buildPanel.bg.moveTo(0,1);buildPanel.bg.lineTo(W,1);buildPanel.bg.lineStyle(0);
  buildPanel.close.c.position.set(W-30,22);
  buildPanel.rows.forEach((r,i)=>{
    r.position.set(0,headH+pad+i*rowH);
    if(r.cost)r.cost.position.set(W-50,20);
  });
  refreshSel();
  buildPanel.y=buildOpen?H-buildPanel.h:H+10;
}
function refreshSel(){
  if(!buildPanel)return;
  const W=app.screen.width;
  buildPanel.rows.forEach(r=>{
    const sel=!!(store.B&&store.B.sel===r.idx);
    r.rbg.clear();
    r.rbg.beginFill(sel?0x1d2418:0x171d20);r.rbg.drawRoundedRect(12,0,W-24,44,11);r.rbg.endFill();
    r.rbg.lineStyle(1.5,sel?0xffb020:0x3d484d,1);r.rbg.drawRoundedRect(12,0,W-24,44,11);r.rbg.lineStyle(0);
    r.ix.style.fill=sel?0x181206:0xffb020;
    r.ixBox.clear();
    r.ixBox.beginFill(sel?0xffb020:0x0d1113);r.ixBox.drawRoundedRect(14,12,24,24,6);r.ixBox.endFill();
    if(!sel){r.ixBox.lineStyle(1,0x3d484d);r.ixBox.drawRoundedRect(14,12,24,24,6);r.ixBox.lineStyle(0);}
  });
}
function hitTest(x,y){
  if(buildOpen){
    const cl=buildPanel.close;
    if(Math.hypot(x-cl.c.x, y-(cl.c.y+buildPanel.y))<24) return {type:'buildclose'};
    for(const r of buildPanel.rows){
      const ry=r.y+buildPanel.y;
      if(x>=12&&x<=app.screen.width-12&&y>=ry&&y<=ry+44) return {type:'buildrow',idx:r.idx};
    }
    if(y>=buildPanel.y) return {type:'panelblank'};
  }
  for(const h of baseHits){
    if(Math.hypot(x-h.cx,y-h.cy)<h.r) return h;
  }
  return null;
}
function onDown(e){
  if(!visible)return;
  const h=hitTest(e.clientX,e.clientY);
  if(!h)return;
  e.preventDefault();
  if(h.type==='panelblank')return;
  if(h.type==='joy'){joyId=e.pointerId;moveJoy(e.clientX,e.clientY);}
  else if(h.type==='fire'){fireId=e.pointerId;fire.held=true;paintBtn(fire);input.keys.Space=true;}
  else if(h.type==='pause'){pulse(pauseBtn);doAct('pause');}
  else if(h.type==='aux'){pulse(aux.find(b=>b.act===h.act));doAct(h.act);}
  else if(h.type==='buildclose'){buildOpen=false;}
  else if(h.type==='buildrow'){doAct('select',h.idx);}
}
function onMove(e){if(visible&&e.pointerId===joyId)moveJoy(e.clientX,e.clientY);}
function onUp(e){
  if(e.pointerId===joyId){joyId=null;joy.dx=joy.dy=0;joy.knob.position.set(0,0);setDir(0,0);}
  if(e.pointerId===fireId){fireId=null;fire.held=false;paintBtn(fire);input.keys.Space=false;}
}
function moveJoy(x,y){
  const R=42,dead=10;
  let dx=x-joy.c.x,dy=y-joy.c.y;const len=Math.hypot(dx,dy);
  if(len>R){dx=dx/len*R;dy=dy/len*R;}
  joy.dx=dx;joy.dy=dy;joy.knob.position.set(dx,dy);
  let mx=0,my=0;
  if(Math.abs(dx)>=Math.abs(dy)){if(Math.abs(dx)>dead)mx=dx>0?1:-1;}
  else{if(Math.abs(dy)>dead)my=dy>0?1:-1;}
  setDir(mx,my);
}
function setDir(mx,my){const k=input.keys;k.KeyA=mx<0;k.KeyD=mx>0;k.KeyW=my<0;k.KeyS=my>0;}
function doAct(act,idx){
  const a=actionsRef;if(!a)return;
  if(act==='build')a.tryPlace();
  else if(act==='demolish')a.demolish();
  else if(act==='trance')a.toggleTrance();
  else if(act==='unstuck')a.unstuck();
  else if(act==='dash')a.dash();
  // else if(act==='pause')a.togglePause();
  else if(act==='pause'){ if(store.uiState.modal&&store.uiState.modal.type==='settings')a.closeSettings(); else a.togglePause(); }
  else if(act==='buildmenu'){buildOpen=!buildOpen;if(buildOpen)refreshSel();}
  else if(act==='select'){a.selectFort(idx);buildOpen=false;}
}
function upd(){
  const dt=Math.min(app.ticker.deltaMS,50)/1000;
  if(!layer||!visible)return;
  if(ring)ring.rotation+=dt*.5;
  if(buildPanel){
    const target=buildOpen?app.screen.height-buildPanel.h:app.screen.height+10;
    buildPanel.y+=(target-buildPanel.y)*Math.min(1,dt*12);
  }
  aux.forEach(b=>{if(b.flash>0){b.flash-=dt;if(b.flash<=0)paintBtn(b);}});
  if(pauseBtn&&pauseBtn.flash>0){pauseBtn.flash-=dt;if(pauseBtn.flash<=0)paintBtn(pauseBtn);}
}