import { app } from './engine.js';
import { store } from './store.js';
import { AudioFX } from './audio.js';
import { actionForCode } from '../config/controls.js';

export const input={keys:{},mouse:{down:false},uiHold:false};

export function initInput(actions){
  const {keys,mouse}=input;

  const handle=(act)=>{
    if(act==='fire') return;                 // огонь — удержание, читается в player.js через keys.Space
    if(act==='build') actions.tryPlace();
    else if(act==='demolish') actions.demolish();
    else if(act==='trance') actions.toggleTrance();
    else if(act==='unstuck') actions.unstuck();
    else if(act==='dash') actions.dash();
    else if(act==='pause') actions.togglePause();
    else if(act==='fort1') actions.selectFort(0);
    else if(act==='fort2') actions.selectFort(1);
    else if(act==='fort3') actions.selectFort(2);
    else if(act==='fort4') actions.selectFort(3);
  };

  window.addEventListener('keydown',e=>{
    if(e.repeat)return;keys[e.code]=true;
    const {mode,B}=store;
    if(mode==='battle'&&B&&B.active){
      const act=actionForCode(e.code);
      if(act==='fire') e.preventDefault();
      // if(B.paused){ if(act==='pause') actions.togglePause(); return; }
      if(act==='pause'){ if(store.uiState.modal&&store.uiState.modal.type==='settings') actions.closeSettings(); else actions.togglePause(); return; }
      if(B.paused) return;
      if(act) handle(act);
    }
  });
  window.addEventListener('keyup',e=>keys[e.code]=false);
  window.addEventListener('pointerup',()=>{mouse.down=false;input.uiHold=false});
  // app.view.addEventListener('pointerdown',e=>{AudioFX.ensure();if(e.button===0)mouse.down=true});
  app.view.addEventListener('pointerdown',e=>{
    AudioFX.ensure();
    if(e.button===0 && e.pointerType!=='touch') mouse.down=true;   // палец огонь не взводит
  });
  app.view.addEventListener('contextmenu',e=>e.preventDefault());
}