import { trackLayer } from '../core/engine.js';
import { store } from '../core/store.js';
import { part } from '../fx/particles.js';
import { rnd } from '../utils/helpers.js';

/* ── настройки следа: свой localStorage, не трогает основной сейв ── */
const SKEY='sr_track_settings_v1';
const TRACK_OPTS=[
  {label:'ВЫКЛ',on:false},
  {label:'2С', on:true,life:2},
  {label:'4С', on:true,life:4},
  {label:'8С', on:true,life:8},
  {label:'20С',on:true,life:20},
];
const DEF_SET={on:true,life:4};
function loadSet(){
  try{const d=JSON.parse(localStorage.getItem(SKEY));
    if(d&&typeof d.on==='boolean')return{on:d.on,life:typeof d.life==='number'?d.life:DEF_SET.life};}catch(e){}
  return Object.assign({},DEF_SET);
}
let settings=loadSet();
function saveSet(){try{localStorage.setItem(SKEY,JSON.stringify(settings))}catch(e){}}
export function getTrackSettings(){return settings}
export function setTracksOn(b){settings.on=!!b;saveSet()}
export function setTrackLife(v){settings.life=v;saveSet()}
export { TRACK_OPTS };

/* ── характер СЛЕДА игрока (по модулю ходовой) ── */
const STYLE={
  gear_tracks :{gw:17,shape:'tread',w:7, len:8, col:0x3a3228,a0:.60},
  gear_wide   :{gw:20,shape:'tread',w:11,len:9, col:0x332c22,a0:.62},
  gear_wheels :{gw:14,shape:'wheel',w:6, len:0, col:0x423a2e,a0:.50},
  gear_rollers:{gw:14,shape:'wheel',w:7, len:0, col:0x382f26,a0:.52},
};
/* ── характер СЛЕДА врага (по типу; все tread — под спрайт с гусеницами) ── */
const ENEMY_STYLE={
  scout  :{gw:12,shape:'tread',w:5, len:7, col:0x423a2e,a0:.45},
  assault:{gw:15,shape:'tread',w:6, len:8, col:0x3a3228,a0:.52},
  sapper :{gw:13,shape:'tread',w:5, len:7, col:0x3f372c,a0:.48},
  ram    :{gw:19,shape:'tread',w:9, len:9, col:0x332c22,a0:.58},
  boss   :{gw:24,shape:'tread',w:12,len:10,col:0x2c251d,a0:.62},
};
/* ── характер ПЫЛИ врага (по типу: разведчик — сухая крошка, босс — густой клуб) ── */
export const ENEMY_DUST={
  scout  :{gw:13,hl:13,perTick:1,interval:.060,colors:[0x9a9082,0xb0a692,0x837a6c],spread:1.4,back:.9, grow:1.0,lifeMin:.22,lifeMax:.40,sizeMin:2.0,sizeMax:3.2,drag:3.0,rectChance:.30},
  assault:{gw:16,hl:15,perTick:2,interval:.055,colors:[0x6a6258,0x7d7468,0x574f46],spread:.8, back:.6, grow:1.4,lifeMin:.30,lifeMax:.52,sizeMin:2.5,sizeMax:4.2,drag:2.6,rectChance:0},
  sapper :{gw:14,hl:14,perTick:1,interval:.060,colors:[0x8a8276,0x9c9488,0x736b60],spread:1.1,back:.7, grow:1.2,lifeMin:.26,lifeMax:.46,sizeMin:2.2,sizeMax:3.6,drag:2.8,rectChance:.15},
  ram    :{gw:20,hl:18,perTick:3,interval:.050,colors:[0x5a5249,0x6e655a,0x48413a],spread:.9, back:.6, grow:1.7,lifeMin:.34,lifeMax:.58,sizeMin:3.0,sizeMax:5.2,drag:2.4,rectChance:0},
  boss   :{gw:25,hl:22,perTick:3,interval:.045,colors:[0x4a4239,0x5e554a,0x38312a],spread:1.0,back:.65,grow:1.9,lifeMin:.38,lifeMax:.62,sizeMin:3.5,sizeMax:6.0,drag:2.2,rectChance:0},
};

const STAMP_INTERVAL=0.12;   // шаг отпечатка (сек) — плотность пунктира
const MAX_TRACKS=360;        // потолок пула следов (игрок + боты делят)

/* ── общий выброс пыли (используют и player.js, и enemies.js) ── */
export function puffDust(wx,wy,dir,cfg){
  const th=dir*Math.PI/2;
  const bx=-Math.sin(th), by=Math.cos(th);   // «назад» в мире
  const sx= Math.cos(th), sy=Math.sin(th);   // «вбок» в мире
  for(let i=0;i<cfg.perTick;i++){
    const side=(Math.random()*2-1)*cfg.spread;
    const bk=(0.3+Math.random()*0.7)*cfg.back;
    const vx=bx*bk*60+sx*side*60+(Math.random()*2-1)*15;
    const vy=by*bk*60+sy*side*60+(Math.random()*2-1)*15;
    const isRect=Math.random()<cfg.rectChance;
    const sz=isRect?rnd(cfg.sizeMin*0.7,cfg.sizeMax*0.7):rnd(cfg.sizeMin,cfg.sizeMax);
    part({x:wx+(Math.random()*2-1)*4,y:wy+(Math.random()*2-1)*4,
      vx:vx,vy:vy,life:rnd(cfg.lifeMin,cfg.lifeMax),
      color:cfg.colors[(Math.random()*cfg.colors.length)|0],
      size:sz,shape:isRect?'rect':'circle',
      grow:isRect?0:cfg.grow,drag:cfg.drag,rot:Math.random()*6.28});
  }
}

/* ── пул отпечатков ── */
const pool=[];
function acquire(){
  let o=pool.find(o=>!o.active);
  if(!o){
    if(pool.length>=MAX_TRACKS){ o=pool[0]; let mn=o.life; for(const q of pool){ if(q.active&&q.life<mn){mn=q.life;o=q;} } }
    else { o={g:new PIXI.Graphics(),active:false,life:0,max:1,a0:1}; pool.push(o); trackLayer.addChild(o.g); }
  }
  return o;
}
function paintStamp(g,st){
  g.clear();
  g.beginFill(st.col,st.a0);
  if(st.shape==='tread'){
    g.drawRect(-st.gw-st.w/2,-st.len/2,st.w,st.len);
    g.drawRect( st.gw-st.w/2,-st.len/2,st.w,st.len);
  }else{
    g.drawCircle(-st.gw,0,st.w/2);
    g.drawCircle( st.gw,0,st.w/2);
  }
  g.endFill();
}
function trackStyleFor(src){
  if(src===store.B.player) return STYLE[store.S.loadout.gear||'gear_tracks'];
  return ENEMY_STYLE[src.type]||STYLE.gear_tracks;
}

/* вызывается из battle.js каждый кадр: sources = [игрок, ...живые боты] (или [] при конце боя) */
export function updTracks(dt,sources){
  for(const o of pool){
    if(!o.active)continue;
    o.life-=dt;
    if(o.life<=0){o.active=false;o.g.visible=false;continue;}
    o.g.alpha=o.a0*(o.life/o.max);
  }
  if(!settings.on||!sources||!sources.length) return;
  for(const src of sources){
    const moved=src.moved||0;
    if(moved<=0.1){ src._trackT=0; continue; }
    src._trackT=(src._trackT||0)+dt;
    if(src._trackT<STAMP_INTERVAL) continue;
    src._trackT=0;
    const st=trackStyleFor(src);
    const o=acquire();
    paintStamp(o.g,st);
    o.g.position.set(24+src.x,24+src.y);   // BORDER=24 — та же система, что у танков
    o.g.rotation=src.dir*Math.PI/2;
    o.g.visible=true;o.g.alpha=st.a0;
    o.active=true;o.life=settings.life;o.max=settings.life;o.a0=st.a0;
  }
}
export function clearTracks(){ for(const o of pool){o.active=false;o.g.visible=false;} }