function isCompact(){
  const vw=app.screen.width,vh=app.screen.height;
  return isTouchDevice()||Math.min(vw,vh)<700;
}
function addRes(parent,k,x,y,anchorRight,size){
  size=size||(anchorRight?10:13);
  const ic=(typeof mkIcon==='function')?mkIcon(k,anchorRight?13:15):null;
  const v=txt(String(store.S[k]),{size,weight:anchorRight?700:800,color:C.amber});
  if(anchorRight){ v.anchor.set(1,0); v.position.set(x,y); if(ic)ic.position.set(x-v.width-16,y+1); }
  else { if(ic)ic.position.set(x,y); v.position.set(x+(ic?20:0),y-1); }
  if(ic)parent.addChild(ic);
  parent.addChild(v);
  return v;
}

export function rebuildUI(){
  if(store.GAR && store.GAR.scroll) store._garageScrollY = store.GAR.scroll.targetY;
  ui.removeChildren().forEach(c=>c.destroy({children:true}));
  clearAnims();
  store.GAR={};store.HUD={};uiRefs.ANN=null;uiRefs.TOAST=null;
  const W=app.screen.width,H=app.screen.height;
  const FX=uiRefs.FX;
  FX.vig=new PIXI.Sprite(TEX_VIG);FX.vig.width=W;FX.vig.height=H;ui.addChild(FX.vig);
  FX.scan=new PIXI.TilingSprite(TEX_SCAN,W,H);FX.scan.alpha=.05;ui.addChild(FX.scan);
  FX.trance=new PIXI.Sprite(TEX_TRANCE);FX.trance.width=W;FX.trance.height=H;FX.trance.alpha=0;ui.addChild(FX.trance);
  if(store.mode==='garage')buildGarageUI();else buildBattleUI();
  if(store.GAR && store.GAR.scroll){
    const sc=store.GAR.scroll; const max=Math.max(0,sc.contentH-sc.h);
    const y=Math.max(-max,Math.min(0,store._garageScrollY||0)); sc.targetY=y; sc.scrollY=y;
  }
  FX.dmg=new PIXI.Sprite(TEX_DMG);FX.dmg.width=W;FX.dmg.height=H;FX.dmg.alpha=store.uiState.flashA;ui.addChild(FX.dmg);
  const TOAST={c:new PIXI.Container(),bg:new PIXI.Graphics(),t:txt('',{size:10.5,ls:1})};
  TOAST.t.anchor.set(.5);TOAST.c.addChild(TOAST.bg,TOAST.t);
  TOAST.c.position.set(W/2,H-112);TOAST.c.visible=false;ui.addChild(TOAST.c);
  uiRefs.TOAST=TOAST;
  if(store.uiState.toastT>0)renderToast();
  buildModal();
}

