/* плавно подтянуть панель инспектора в видимую зону (минимальным движением) */
function scrollToInspect(){
  const sc=store.GAR.scroll, iy=store.GAR.inspectY;
  if(!sc||iy==null) return;
  const ih=store.GAR.inspectH||190, pad=16;
  const cur=-sc.targetY;                       // верх видимой зоны в координатах контента
  const topTarget=-(iy-pad);                   // выровнять по верху
  const botTarget=-(iy+ih-sc.h+pad);           // выровнять по низу
  let target=sc.targetY;
  if(iy < cur+pad) target=topTarget;                       // обрезан сверху / выше экрана
  else if(iy+ih > cur+sc.h-pad) target=(ih>sc.h)?topTarget:botTarget;  // обрезан снизу (если не влезает — всё равно верх)
  sc.targetY=target; sc.clampT();
}
function showInspect(info){ store.GAR.inspect=info; renderInspect(); if(info) scrollToInspect(); }

