import { store } from './store.js';

/* Групповые шины: master → sfxMaster → {boom,gun,hit,ui}.
   Двигатель и музыка имеют собственные гейны в своих модулях.
   setBusGain крутит шину; если шин ещё нет (до первого жеста) — запоминает в _mix. */
export const AudioFX={ctx:null,master:null,sfxMaster:null,bus:null,nbuf:null,on:store.S.sound,_mix:null,
  ensure(){if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
    this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=.5;this.master.connect(this.ctx.destination);
    this.sfxMaster=this.ctx.createGain();this.sfxMaster.gain.value=1;this.sfxMaster.connect(this.master);
    this.bus={};
    ['boom','gun','hit','ui'].forEach(k=>{const g=this.ctx.createGain();g.gain.value=1;g.connect(this.sfxMaster);this.bus[k]=g;});
    if(this._mix){for(const k in this._mix){ if(k==='sfx')this.sfxMaster.gain.value=this._mix[k]; else if(this.bus[k])this.bus[k].gain.value=this._mix[k]; }}
    const len=this.ctx.sampleRate*.5,b=this.ctx.createBuffer(1,len,this.ctx.sampleRate),d=b.getChannelData(0);
    for(let i=0;i<len;i++)d[i]=Math.random()*2-1;this.nbuf=b}
    if(this.ctx.state==='suspended')this.ctx.resume()},
  setBusGain(name,v){ this._mix=this._mix||{}; this._mix[name]=v;
    if(name==='sfx'){ if(this.sfxMaster)this.sfxMaster.gain.value=v; }
    else if(this.bus&&this.bus[name]) this.bus[name].gain.value=v; },
  _out(bus){ if(bus==='sfx'&&this.sfxMaster)return this.sfxMaster;
    if(bus&&this.bus&&this.bus[bus])return this.bus[bus]; return this.master; },
  tone(f,dur,type='square',vol=.12,slide=0,delay=0,bus){if(!this.on||!this.ctx)return;
    const t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();
    o.type=type;o.frequency.setValueAtTime(f,t);
    if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,f+slide),t+dur);
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);
    o.connect(g);g.connect(this._out(bus));o.start(t);o.stop(t+dur+.02)},
  noise(dur=.2,vol=.2,fq=800,q=1,bus){if(!this.on||!this.ctx)return;
    const t=this.ctx.currentTime,s=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();
    s.buffer=this.nbuf;f.type='lowpass';f.frequency.value=fq;f.Q.value=q;
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);
    s.connect(f);f.connect(g);g.connect(this._out(bus));s.start(t);s.stop(t+dur+.02)},
  band(dur,vol,fq,q=4,bus){if(!this.on||!this.ctx)return;
    const t=this.ctx.currentTime,s=this.ctx.createBufferSource(),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();
    s.buffer=this.nbuf;f.type='bandpass';f.frequency.value=fq;f.Q.value=q;
    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);
    s.connect(f);f.connect(g);g.connect(this._out(bus));s.start(t);s.stop(t+dur+.02)},

  /* ── выстрелы (шина gun) ── */
  shot(id){const B='gun';
    if(id==='gun_short')this.tone(760,.07,'square',.06,-420,0,B);
    else if(id==='gun_long'){this.tone(520,.12,'sawtooth',.1,-300,0,B);this.noise(.08,.1,1600,1,B)}
    else if(id==='gun_twin'){this.tone(880,.05,'square',.05,-520,0,B);this.tone(820,.05,'square',.05,-520,.03,B)}
    else if(id==='gun_howitzer'){this.tone(160,.22,'sawtooth',.14,-120,0,B);this.noise(.16,.16,900,1,B)}
    else this.tone(880,.06,'square',.05,-520,0,B)},
  eshot(){this.tone(420,.07,'square',.04,-200,0,'gun')},
  reload(){this.tone(400,.09,'square',.07,260,0,'gun')},

  /* ── попадания / металл (шина hit) ── */
  hit(){this.tone(220,.05,'square',.05,-90,0,'hit')},
  clank(){this.tone(1200,.05,'square',.05,-700,0,'hit')},

  /* ── ВЗРЫВ: многослойный удар (шина boom) ── */
  boom(big){const B='boom';
    this.tone(big?48:70, big?.5:.30, 'sine', .28, big?-30:-45, 0, B);          // суб-низкий удар
    this.noise(big?.45:.22, big?.40:.24, big?520:900, 1, B);                  // воздушный всплеск
    this.tone(1800,.05,'square',.06,-900,0,B);                               // звон осколков
    this.tone(2600,.04,'square',.04,-1200,.02,B);
    if(big){                                                                 // эпический грохот
      this.tone(40,.6,'sine',.22,-20,.12,B);
      this.noise(.6,.18,300,1,B);
      this.tone(1100,.06,'square',.05,-600,.05,B);
    }},
  /* скрежет ломающейся стены / турели — подмешивается к взрыву */
  metalBreak(){const B='boom';
    this.band(.18,.18,1400,3,B);
    this.tone(340,.12,'sawtooth',.08,-220,0,B);
    this.tone(1200,.05,'square',.05,-700,0,B);},

  /* ── интерфейс / действия (шина ui) ── */
  pickup(){this.tone(660,.07,'square',.07,0,0,'ui');this.tone(990,.1,'square',.07,0,.07,'ui')},
  horn(){this.tone(170,.4,'sawtooth',.12,-30,0,'ui');this.tone(230,.4,'sawtooth',.09,-30,.18,'ui')},
  place(){this.tone(300,.08,'square',.08,-110,0,'ui');this.noise(.06,.09,500,1,'ui')},
  err(){this.tone(140,.13,'square',.08,-40,0,'ui')},
  dash(){this.noise(.25,.18,3200,1,'ui');this.tone(480,.22,'sine',.08,420,0,'ui')},
  trance(){this.tone(1300,.45,'sine',.06,-1000,0,'ui')},
  servo(){this.tone(320,.10,'square',.05,900,0,'ui');this.band(.06,.05,1400,3,'ui');this.tone(1180,.04,'sine',.03,0,.08,'ui')},
  rampExtend(){this.band(.42,.16,820,3,'ui');this.tone(220,.4,'sawtooth',.07,-150,0,'ui');
    this.tone(900,.03,'square',.05,0,.05,'ui');this.tone(700,.03,'square',.05,0,.22,'ui')},
  deployRumble(){this.tone(58,.7,'sawtooth',.12,18,0,'boom');this.noise(.7,.12,240,2,'boom');this.tone(110,.5,'sine',.06,-40,0,'boom')},
  bootChime(){this.tone(523,.12,'sine',.07,0,0,'ui');this.tone(659,.12,'sine',.06,0,.08,'ui');this.tone(784,.18,'sine',.06,0,.16,'ui')},
  loadingTick(){this.tone(1500,.03,'square',.025,0,0,'ui')},
  loadingResolve(){this.tone(523,.5,'sine',.06,0,0,'ui');this.tone(659,.5,'sine',.05,0,.02,'ui');this.tone(784,.6,'sine',.05,0,.04,'ui');this.noise(.3,.06,2600,1,'ui')},
};

/* тихий гул поворотного стола ангарa */
export const Turntable={ctx:null,o1:null,o2:null,g:null,cur:0,tgt:0,
  ensure(){if(this.ctx||!AudioFX.ctx)return;this.ctx=AudioFX.ctx;
    this.g=this.ctx.createGain();this.g.gain.value=0;
    const f=this.ctx.createBiquadFilter();f.type='lowpass';f.frequency.value=240;f.connect(this.g);this.g.connect(AudioFX.master);
    this.o1=this.ctx.createOscillator();this.o1.type='sine';this.o1.frequency.value=80;this.o1.connect(f);this.o1.start();
    this.o2=this.ctx.createOscillator();this.o2.type='sine';this.o2.frequency.value=82.5;
    const g2=this.ctx.createGain();g2.gain.value=0.6;this.o2.connect(g2);g2.connect(f);this.o2.start();},
  setTarget(v){this.tgt=v;this.ensure();},
  frame(dt){if(!this.g)return;if(!AudioFX.on){this.g.gain.value=0;return;}
    this.cur+=(this.tgt-this.cur)*Math.min(1,dt*6);this.g.gain.value=this.cur*0.05;}
};