import { store,save } from '../core/store.js';
import { CELL,BORDER,TS,FIELD_W,FIELD_H,DX,DY,ETYPES,BASE,SOLID,TL,GRID_W,GRID_H } from '../config/world.js';
import { tankLayer } from '../core/engine.js';
import { buildEnemySprite } from '../world/tank.js';
import { explosion,floatText } from '../fx/particles.js';
import { AudioFX } from '../core/audio.js';
import { pushBullet } from './bullets.js';
import { tiles } from '../world/map.js';
import { spawnPickup } from './pickups.js';
import { randi,rnd,clamp } from '../utils/helpers.js';
import { log,syncRes,announce } from '../ui/hud.js';
import { rectHitsSolid,hitsTank,TANK_SEP,pushApart } from './collision.js';
import { damageFort } from './forts.js';
import { puffDust, ENEMY_DUST } from './tracks.js';
import { damagePlayer } from './player.js';   // безопасно: player не импортирует enemies → цикла нет

const PLAYER_R=20;   // тот же радиус, что в bullets.js
const AGGRO={scout:8,assault:7,sapper:6,ram:5,boss:6};
function getTarget(e){
  const p=store.B.player,r=(AGGRO[e.type]||7)*CELL;
  if(!store.B.over && Math.hypot(p.x-e.x,p.y-e.y)<r) return {x:p.x,y:p.y};
  return {x:BASE.gx*CELL+CELL/2,y:BASE.gy*CELL+CELL/2};
}
function findFreeSpawn(x,y){
  const cgx=Math.floor(x/CELL),cgy=Math.floor(y/CELL);
  const busy=(gx,gy)=>{
    if(gx<0||gx>=GRID_W||gy<0||gy>=GRID_H)return true;
    const tl=tiles.get(gx+','+gy); if(tl&&SOLID.has(tl.t))return true;
    if(hitsTank(gx*CELL+CELL/2,gy*CELL+CELL/2,40,null))return true;
    return false;
  };
  if(!busy(cgx,cgy))return{x:cgx*CELL+CELL/2,y:cgy*CELL+CELL/2};
  for(let r=1;r<=3;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){
    if(Math.max(Math.abs(dx),Math.abs(dy))!==r)continue;
    if(!busy(cgx+dx,cgy+dy))return{x:(cgx+dx)*CELL+CELL/2,y:(cgy+dy)*CELL+CELL/2};
  }
  return{x,y};
}
export function separateEnemies(){
  const arr=store.B.enemies;
  for(let i=0;i<arr.length;i++)for(let j=i+1;j<arr.length;j++){
    const a=arr[i],b=arr[j];
    const r=pushApart(a.x,a.y,b.x,b.y,canStand,canStand);
    a.x=r.ax;a.y=r.ay;b.x=r.bx;b.y=r.by;
  }
}
function canStand(x,y){return x>=TS/2&&x<=FIELD_W-TS/2&&y>=TS/2&&y<=FIELD_H-TS/2&&!rectHitsSolid(x,y,TS);}
export function spawnEB(e){
  const sp=(e.type==='sapper'?8.5:e.type==='boss'?7:6)*CELL;
  pushBullet({x:e.x+DX[e.dir]*(TS/2+6),y:e.y+DY[e.dir]*(TS/2+6),
    vx:DX[e.dir]*sp,vy:DY[e.dir]*sp,dmg:1,life:2.2,friendly:false,owner:e});
  AudioFX.eshot();
}
export function bossCross(e){
  [e.dir,(e.dir+1)%4,(e.dir+3)%4].forEach(d=>{
    const sp=7*CELL;
    pushBullet({x:e.x+DX[d]*(TS/2+8),y:e.y+DY[d]*(TS/2+8),
      vx:DX[d]*sp,vy:DY[d]*sp,dmg:1,life:2.2,friendly:false,owner:e})});
  AudioFX.tone(240,.3,'sawtooth',.09,-140);
}
export function countEB(e){let n=0;for(const b of store.B.bullets)if(!b.friendly&&b.owner===e)n++;return n}
export function pickDir(e){
  if(Math.random()<.72){
    const tgt=getTarget(e);const dx=tgt.x-e.x,dy=tgt.y-e.y,pref=[];
    if(Math.abs(dx)>Math.abs(dy)){pref.push(dx>0?1:3);pref.push(dy>0?2:0)}
    else{pref.push(dy>0?2:0);pref.push(dx>0?1:3)}
    return pref[randi(0,pref.length-1)];
  }
  return randi(0,3);
}
export function aligned(e){
  for(let s=1;s<=7;s++){
    const cx=e.x+DX[e.dir]*CELL*s,cy=e.y+DY[e.dir]*CELL*s;
    if(cx<0||cx>FIELD_W||cy<0||cy>FIELD_H)return false;
    const tl=tiles.get(Math.floor(cx/CELL)+','+Math.floor(cy/CELL));
    if(tl&&SOLID.has(tl.t))return tl.t===TL.BASE;
    if(!store.B.over&&Math.abs(store.B.player.x-cx)<CELL/2&&Math.abs(store.B.player.y-cy)<CELL/2)return true}
  return false;
}
function frontCellOf(e){return{gx:Math.floor(e.x/CELL)+DX[e.dir],gy:Math.floor(e.y/CELL)+DY[e.dir]}}
function isFortType(t){return t===TL.BAGS||t===TL.CONCRETE||t===TL.STEELW||t===TL.TURRET}

export function spawnEnemy(type,x,y,bonus){
  const B=store.B,T=ETYPES[type];
  const pos=findFreeSpawn(x,y);
  const ramp=Math.ceil(Math.max(1,B.wave)*0.7);
  let hp=T.hp+ramp;
  if(type==='boss')hp=T.hp+Math.floor(B.wave/5)*6+ramp*2;
  const spd=T.speed*(type==='boss'?1:1+Math.min(.25,B.wave*.012));
  const e={type,x:pos.x,y:pos.y,dir:2,hp,maxHp:hp,speed:spd,bonus:!!bonus,aggro:false,r:T.r,
    dirT:rnd(.5,1.5),shootCd:rnd(.8,1.6),blockT:0,atkCd:0,hitCd:0,animT:0,frame:0,flash:0,cross:2.4,minion:6};
  const s=buildEnemySprite(type);
  e.sprite=s.container;e.body=s.body;e.treads=s.treads;
  e.container=new PIXI.Container();e.container.addChild(e.sprite);
  e.sprite.rotation=e.dir*Math.PI/2;
  if(type==='boss'){e.sprite.scale.set(1.35);e.body.tint=0xff6a5a;}
  const bw=type==='boss'?60:36, by=type==='boss'?-40:-28;
  const bb=new PIXI.Graphics();bb.beginFill(0x0d1113,.85);bb.drawRect(0,0,bw,4);bb.endFill();bb.position.set(-bw/2,by);
  const bf=new PIXI.Graphics();bf.beginFill(type==='boss'?0xe0503c:0xa5c46b);bf.drawRect(0,0,bw,4);bf.endFill();bf.position.set(-bw/2,by);
  e.container.addChild(bb,bf);e.barBg=bb;e.barFg=bf;
  e.container.position.set(BORDER+pos.x,BORDER+pos.y);
  tankLayer.addChild(e.container);B.enemies.push(e);
}
export function updEnemy(e,dt){
  const B=store.B,P=B.player;
  if(e.hp<=0)return;
  const ox=e.x,oy=e.y;
  e.flash=Math.max(0,e.flash-dt);
  e.animT+=dt;if(e.animT>.1){e.animT=0;e.frame^=1;e.treads.y=e.frame?4:0}
  if(e.barFg)e.barFg.scale.x=clamp(e.hp/e.maxHp,0,1);
  if(!B.over){
    const aggro=Math.hypot(P.x-e.x,P.y-e.y)<(AGGRO[e.type]||7)*CELL;
    if(aggro!==e.aggro){e.aggro=aggro;e.dirT=0;}
    e.dirT-=dt*(aggro?2.6:1);e.shootCd-=dt;
    const sp=e.speed*CELL;
    if(e.dir%2===0){const lc=Math.round((e.x-CELL/2)/CELL)*CELL+CELL/2;e.x+=(lc-e.x)*Math.min(1,dt*8)}
    else{const lc=Math.round((e.y-CELL/2)/CELL)*CELL+CELL/2;e.y+=(lc-e.y)*Math.min(1,dt*8)}
    const nx=e.x+DX[e.dir]*sp*dt,ny=e.y+DY[e.dir]*sp*dt;
    const blocked=rectHitsSolid(nx,ny,TS)||hitsTank(nx,ny,TANK_SEP,e)||nx<TS/2||nx>FIELD_W-TS/2||ny<TS/2||ny>FIELD_H-TS/2;
    if(blocked){
      e.blockT+=dt;
      const fc=frontCellOf(e),tl=tiles.get(fc.gx+','+fc.gy);
      if(tl&&isFortType(tl.t)){e.atkCd-=dt;if(e.atkCd<=0){e.atkCd=.8;damageFort(tl,e.type==='boss'?3:1,e.x,e.y);}}
      else if(e.blockT>.25||e.dirT<=0){e.dir=pickDir(e);e.dirT=rnd(1.2,3);e.blockT=0;e.sprite.rotation=e.dir*Math.PI/2;}
    }else{
      e.blockT=0;e.x=nx;e.y=ny;
      if(e.dirT<=0){if(aggro||Math.random()<.5){e.dir=pickDir(e);e.sprite.rotation=e.dir*Math.PI/2}e.dirT=rnd(1.5,3.5);}
    }
    if(e.shootCd<=0&&countEB(e)<1){
      e.shootCd=rnd(.8,1.9)*(e.type==='sapper'?.55:1)*(aggro?.7:1);
      if(aligned(e)||Math.random()<.45)spawnEB(e)}
    if(e.type==='boss'){
      e.cross-=dt;if(e.cross<=0){e.cross=2.4;bossCross(e)}
      e.minion-=dt;
      if(e.minion<=0){e.minion=7;
        if(B.enemies.length<5){const my=clamp(e.y+CELL,CELL/2,FIELD_H-CELL/2);
          if(!rectHitsSolid(e.x,my,TS)&&!hitsTank(e.x,my,44,null)){B.spawnFX.push({x:e.x,y:my,t:.7,type:'scout'});log('БРОНЕНОСЕЦ ВЫПУСКАЕТ МОБИЛЫ','boss');}}}
    }
    const dist=Math.hypot(P.x-e.x,P.y-e.y)||.001;
    if(dist<PLAYER_R+e.r+2){
      e.hitCd-=dt;
      if(e.hitCd<=0){e.hitCd=.85;const dmg=ETYPES[e.type].dmg;if(dmg>0)damagePlayer(dmg,e.x,e.y);}
    }
  }
  if(e.flash>0)e.body.tint=0xff8a7a;
  else if(e.type==='boss')e.body.tint=0xff6a5a;
  else if(e.type==='ram')e.body.tint=[0xff6a5a,0xff9a5a,0xffd27a,0xffffff][clamp(Math.floor((e.hp/e.maxHp)*4),0,3)];
  else if(e.bonus)e.body.tint=Math.floor(B.time*6)%2?0xffffff:0xff5a5a;
  else e.body.tint=0xffffff;
  e.moved=Math.hypot(e.x-ox,e.y-oy);
  const edcfg=ENEMY_DUST[e.type];
  if(edcfg && e.moved>0.1){
    e.dustT=(e.dustT||0)-dt;
    if(e.dustT<=0){
      e.dustT=edcfg.interval;
      const th=e.dir*Math.PI/2, c=Math.cos(th), s=Math.sin(th);
      const contacts=[[-edcfg.gw,edcfg.hl],[edcfg.gw,edcfg.hl]];
      for(let ci=0;ci<contacts.length;ci++){
        const lx=contacts[ci][0], ly=contacts[ci][1];
        puffDust(BORDER+e.x+(lx*c-ly*s), BORDER+e.y+(lx*s+ly*c), e.dir, edcfg);
      }
    }
  }
  e.container.position.set(BORDER+e.x,BORDER+e.y);
}
export function killEnemy(i){
  const B=store.B,e=B.enemies[i];B.enemies.splice(i,1);
  explosion(BORDER+e.x,BORDER+e.y,e.type==='boss'?34:22,e.type!=='scout');
  const T=ETYPES[e.type],bolts=randi(T.bolts[0],T.bolts[1]);
  store.S.bolts+=bolts;B.boltsRun+=bolts;B.score+=T.score;B.kills++;
  floatText(BORDER+e.x,BORDER+e.y-16,'+'+T.score,0xe9e4d6,12);
  floatText(BORDER+e.x,BORDER+e.y-2,'+'+bolts,0xffd27a,12,'bolts');
  if(e.type==='boss'){
    store.S.boxes++;store.S.gears+=2;B.boxesRun++;B.gearsRun+=2;
    announce('КОНТЕЙНЕР ЗАХВАЧЕН','good',2.2,'+1 контейнер · +2 шестерни');
    log('БРОНЕНОСЕЦ УНИЧТОЖЕН · КОНТЕЙНЕР ЗАХВАЧЕН','boss');spawnPickup('box');
  }else if(e.bonus){
    const r=Math.random();
    const type=r<.38?'bolts':r<.60?'repair':r<.76?'shield':r<.90?'shovel':'gears';
    spawnPickup(type);log('БОНУС-ТАНК СБРОСИЛ УСИЛЕНИЕ','good');
  }
  if(e.container.parent)e.container.parent.removeChild(e.container);
  e.container.destroy({children:true});
  save();syncRes();
}
export function sweep(){const B=store.B;for(let i=B.enemies.length-1;i>=0;i--)if(B.enemies[i].hp<=0)killEnemy(i)}