import { AudioFX } from './audio.js';

let ctx=null, master=null, osc=null, sub=null, noiseSrc=null, noiseGain=null, lp=null, bp=null;
let enabled=false, cur=0, tgt=0, userGain=1;
let curFreq=70, tgtFreq=70, curNoise=0, tgtNoise=0, curBp=300, tgtBp=300;
let drive={moving:false,speed:2,gear:'gear_tracks',engine:'eng_base'};

const ENG={
  eng_base:  {f:64, sw:0.0, lp:380, n:0.10},
  eng_forced:{f:88, sw:0.05,lp:560, n:0.16},
  eng_turbo: {f:128,sw:0.16,lp:820, n:0.30},
};
const GEAR={
  gear_tracks :{fm:1.00, lp:1.0, nm:1.3, bp:260},
  gear_wide   :{fm:0.92, lp:0.85,nm:1.7, bp:220},
  gear_wheels :{fm:1.35, lp:1.5, nm:0.6, bp:520},
  gear_rollers:{fm:1.12, lp:1.2, nm:0.8, bp:380},
};

function build(){
  ctx=AudioFX.ctx; if(!ctx) return false;
  master=ctx.createGain(); master.gain.value=0; master.connect(ctx.destination);
  lp=ctx.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=400; lp.Q.value=6; lp.connect(master);
  bp=ctx.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=300; bp.Q.value=2; bp.connect(master);
  osc=ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.value=70;
  const og=ctx.createGain(); og.gain.value=0.5; osc.connect(og); og.connect(lp); osc.start();
  sub=ctx.createOscillator(); sub.type='sine'; sub.frequency.value=35;
  const sg=ctx.createGain(); sg.gain.value=0.4; sub.connect(sg); sg.connect(lp); sub.start();
  const len=ctx.sampleRate*2, buf=ctx.createBuffer(1,len,ctx.sampleRate), d=buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  noiseSrc=ctx.createBufferSource(); noiseSrc.buffer=buf; noiseSrc.loop=true;
  noiseGain=ctx.createGain(); noiseGain.gain.value=0;
  noiseSrc.connect(noiseGain); noiseGain.connect(bp); noiseGain.connect(lp); noiseSrc.start();
  return true;
}
function retarget(){
  const e=ENG[drive.engine]||ENG.eng_base, g=GEAR[drive.gear]||GEAR.gear_tracks;
  const spd=drive.speed||2;
  tgtFreq=e.f*g.fm*(1+spd*0.10);
  tgtNoise=(drive.moving?e.n*g.nm:0.02);
  tgtBp=g.bp*(1+spd*0.05);
  tgt=enabled?(drive.moving?0.16:0.035):0;
}
export function setEnabled(b){ enabled=b; if(enabled&&!ctx){ AudioFX.ensure(); if(!build()) return; } retarget(); }
export function setGain(v){ userGain=v; }                                   // ← громкость из микшера
export function setDrive(moving,speed,gear,engine){ drive={moving,speed,gear:gear||'gear_tracks',engine:engine||'eng_base'}; retarget(); }
export function frame(dt){
  if(!ctx||!master) return;
  if(!AudioFX.on){ master.gain.value=0; return; }
  const k=Math.min(1,dt*8);
  cur+=(tgt-cur)*k; curFreq+=(tgtFreq-curFreq)*k; curNoise+=(tgtNoise-curNoise)*k; curBp+=(tgtBp-curBp)*k;
  master.gain.value=cur*userGain;                                          // ← учитываем ползунок
  if(osc){ osc.frequency.value=curFreq; sub.frequency.value=curFreq*0.5; }
  if(noiseGain) noiseGain.gain.value=curNoise;
  if(lp) lp.frequency.value=300+curFreq*2.2;
  if(bp) bp.frequency.value=curBp;
}