export const rnd=(a,b)=>a+Math.random()*(b-a);
export const randi=(a,b)=>Math.floor(rnd(a,b+1));
export const clamp=(v,a,b)=>v<a?a:v>b?b:v;
export const pad2=n=>String(n).padStart(2,'0');
export const mmss=t=>pad2(Math.floor(t/60))+':'+pad2(Math.floor(t%60));
export const trunc=(s,n)=>s.length>n?s.slice(0,n-1)+'…':s;
export function angLerp(a,b,t){let d=(b-a)%(Math.PI*2);if(d>Math.PI)d-=Math.PI*2;if(d<-Math.PI)d+=Math.PI*2;return a+d*t}
export function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
export const easeOutBack=t=>{const c1=1.70158,c3=c1+1;return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2)};
export function setTxt(t,s){ if(!t)return; s=String(s); if(t.text!==s)t.text=s; }
export const clone=o=>JSON.parse(JSON.stringify(o));