import { app } from '../core/engine.js';

/* ── форматирование ── */
const SUFFIX = ['','k','m','b','t','q','Q','s','S','o','N'];
export function fmt(n){
  if(n===null||n===undefined||isNaN(n)) return '0';
  const neg=n<0, a=Math.abs(n);
  if(a<1000) return (neg?'-':'')+Math.round(a);
  let u=0,v=a; while(v>=1000 && u<SUFFIX.length-1){ v/=1000; u++; }
  const s=(v>=100)?Math.round(v).toString():(Math.round(v*10)/10).toString();
  return (neg?'-':'')+s+SUFFIX[u];
}
export function full(n){
  if(n===null||n===undefined||isNaN(n)) return '0';
  const neg=n<0, a=Math.abs(Math.round(n)).toString(); let out='';
  for(let i=0;i<a.length;i++){ if(i>0 && (a.length-i)%3===0) out+=' '; out+=a[i]; }
  return (neg?'-':'')+out;
}
const easeOutBack=t=>{const c1=1.70158,c3=c1+1;return 1+c3*Math.pow(t-1,3)+c1*Math.pow(t-1,2);};

/* ── всплывающий бейдж точного значения (один на всё, поверх UI и модалок) ── */
let badgeLayer=null, badge=null;
function ensureBadge(){
  if(badgeLayer) return;
  badgeLayer=new PIXI.Container();
  app.stage.addChild(badgeLayer);
  const c=new PIXI.Container(); c.visible=false;
  const bg=new PIXI.Graphics();
  const arrow=new PIXI.Graphics();
  const t=new PIXI.Text('',{fontFamily:'JetBrains Mono',fontWeight:'800',fontSize:13,
    fill:0xffe6b0,letterSpacing:1,stroke:0x000000,strokeThickness:3});
  t.anchor.set(.5,.5);                                  // число центрируем в плашке
  c.addChild(bg,t,arrow); badgeLayer.addChild(c);       // подпись-тег убрана
  badge={c,bg,arrow,t,appear:0,active:false,target:null,getText:null,flip:false,arrowX:0};
  window.addEventListener('pointerup',   ()=>{ endHold(false); hideBadge(); });
  window.addEventListener('pointercancel',()=>{ endHold(false); hideBadge(); });
  app.ticker.add(updBadge);
}
function updBadge(){
  if(!badge) return;
  const dt=Math.min(app.ticker.deltaMS,50)/1000, now=performance.now()/1000;
  if(badge.active && badge.target && !badge.target.destroyed) badge.appear=Math.min(1,badge.appear+dt*8);
  else { badge.appear=Math.max(0,badge.appear-dt*12); if(badge.appear<=0){ badge.c.visible=false; badge.target=null; return; } }
  badge.c.visible=true;

  const str=badge.getText?badge.getText():''; if(badge.t.text!==str) badge.t.text=str;

  const padX=12,padY=9;
  const bw=badge.t.width+padX*2, bh=badge.t.height+padY*2;   // тега больше нет — высота только под число
  const hw=bw/2, hh=bh/2, cc=7;
  const pulse=badge.active?(0.72+0.28*Math.sin(now*9)):1;
  const poly=[-hw+cc,-hh, hw,-hh, hw,hh-cc, hw-cc,hh, -hw,hh, -hw,-hh+cc];   // центрированная плашка

  const bg=badge.bg; bg.clear();
  bg.beginFill(0x10161a,0.96); bg.drawPolygon(poly); bg.endFill();
  bg.lineStyle(1.5,0xffb020,pulse); bg.drawPolygon(poly); bg.lineStyle(0);
  bg.beginFill(0xffffff,0.06); bg.drawRect(-hw+2,-hh+2,bw-4,3); bg.endFill();   // верхний блик

  badge.t.position.set(0,0);                            // число строго по центру плашки

  const ar=badge.arrow, ax=badge.arrowX; ar.clear();    // стрелка у реального края плашки
  ar.beginFill(0x10161a,0.96);
  if(!badge.flip){ ar.drawPolygon([ax-6,hh,ax+6,hh,ax,hh+7]);
    ar.lineStyle(1.5,0xffb020,pulse); ar.moveTo(ax-6,hh); ar.lineTo(ax,hh+7); ar.lineTo(ax+6,hh); ar.lineStyle(0); }
  else { ar.drawPolygon([ax-6,-hh,ax+6,-hh,ax,-hh-7]);
    ar.lineStyle(1.5,0xffb020,pulse); ar.moveTo(ax-6,-hh); ar.lineTo(ax,-hh-7); ar.lineTo(ax+6,-hh); ar.lineStyle(0); }

  const el=badge.target, axn=el.anchor?el.anchor.x:0, ayn=el.anchor?el.anchor.y:0;
  const topC=el.toGlobal(new PIXI.Point(el.width*(0.5-axn),el.height*(0-ayn)));
  const botC=el.toGlobal(new PIXI.Point(el.width*(0.5-axn),el.height*(1-ayn)));
  const sw=app.screen.width;
  let cx=Math.max(hw+8,Math.min(sw-hw-8,topC.x));
  badge.arrowX=Math.max(-hw+10,Math.min(hw-10,topC.x-cx));
  const gap=12; let cy;
  if(topC.y-gap-hh-7>=6){ badge.flip=false; cy=topC.y-gap-hh; }      // плашка сверху
  else { badge.flip=true;  cy=botC.y+gap+hh; }                       // не влезла — уходит под число
  badge.c.position.set(cx,cy);
  badge.c.scale.set(0.7+0.3*easeOutBack(badge.appear));
  badge.c.alpha=badge.appear;
}

/* ── удержание: локальный показ бейджа только над этой нодой ── */
function showBadge(el,getText){ ensureBadge(); badge.target=el; badge.getText=getText; badge.active=true; }
function hideBadge(){ if(badge) badge.active=false; }
function endHold(hoverAfter){
  if(!badge||!badge.target) return; const el=badge.target;
  if(el.destroyed){ badge.target=null; return; }
  if(!el.__hrHold) return;                 // уже сброшено (идемпотентность для window-up)
  el.__hrHold=false;
  if(el.scale) el.scale.set(el.__hrBase||1);
  el.tint=hoverAfter?0xffe6b0:0xffffff;
}
export function holdReveal(el,getText){
  el.eventMode='static'; el.cursor='pointer';
  el.__hrBase=el.scale?el.scale.x:1;
  el.on('pointerover',()=>{ if(!el.__hrHold) el.tint=0xffe6b0; });
  el.on('pointerout', ()=>{ if(!el.__hrHold) el.tint=0xffffff; });
  el.on('pointerdown',()=>{ el.__hrHold=true; el.tint=0xffd27a; if(el.scale)el.scale.set((el.__hrBase||1)*1.08); showBadge(el,getText); });
  el.on('pointerup',      ()=>{ endHold(true);  hideBadge(); });
  el.on('pointerupoutside',()=>{ endHold(false); hideBadge(); });
  el.on('pointercancel',  ()=>{ endHold(false); hideBadge(); });
}

/* ── трекнутое число: всегда сокращено в ноде, полное — в бейдже при удержании ── */
export function trackNum(el,opts){
  opts=opts||{};
  const r={el,val:0,opts};
  const render=()=>{ el.text=(opts.prefix||'')+fmt(r.val)+(opts.suffix||''); };
  holdReveal(el, ()=> opts.reveal? opts.reveal(r.val) : full(r.val));
  render();
  return (n)=>{ r.val=n; render(); };
}