import { store } from '../core/store.js';
import { C } from '../config/world.js';
import { MODULES,CATCOL,RCX } from '../config/modules.js';
import { input } from '../core/input.js';
import { mkIcon } from './icons.js';
import { regAnim } from './anims.js';

function lerpColor(a,b,t){
  const ar=(a>>16)&255,ag=(a>>8)&255,ab=a&255,br=(b>>16)&255,bg=(b>>8)&255,bb=b&255;
  const r=Math.round(ar+(br-ar)*t),g=Math.round(ag+(bg-ag)*t),bl=Math.round(ab+(bb-ab)*t);
  return (r<<16)|(g<<8)|bl;
}

export function txt(str,o={}){
  const{size=12,color=C.ink,font='mono',weight=400,ls=0,alpha=1,wrap=0,stroke=0}=o;
  return new PIXI.Text(str,{fontFamily:font==='disp'?'Russo One':'JetBrains Mono',
    fontSize:size,fill:color,fontWeight:weight,letterSpacing:ls,alpha,
    wordWrap:wrap>0,wordWrapWidth:wrap,stroke:stroke||0x000000,strokeThickness:stroke?4:0});
}
export const cutPts=(w,h,c)=>[c,0,w,0,w,h-c,w-c,h,0,h,0,c];
export function cutPoly(g,w,h,c,fill,stroke){
  if(fill!=null){g.beginFill(fill);g.drawPolygon(cutPts(w,h,c));g.endFill()}
  if(stroke!=null){g.lineStyle(1,stroke,1);g.drawPolygon(cutPts(w,h,c));g.lineStyle(0)}
}
export function mkPanel(w,h,{hz=false,title=null}={}){
  const p=new PIXI.Container();p.panelW=w;p.panelH=h;
  const g=new PIXI.Graphics();
  cutPoly(g,w,h,10,0x1b2124,0x364045);
  g.lineStyle(1,0xffffff,.05);g.moveTo(12,1.5);g.lineTo(w-2,1.5);g.lineStyle(0);
  if(hz){let i=0;for(let y=14;y<h-10;y+=9,i++){g.beginFill(i%2?0x151a1d:C.amber,.85);g.drawRect(0,y,4,6);g.endFill()}}
  g.beginFill(0x39434a);g.drawCircle(w-9,9,2);g.drawCircle(9,h-9,2);g.endFill();
  p.addChild(g);
  if(title){
    const sq=new PIXI.Graphics();sq.beginFill(C.amber);sq.drawPolygon([0,0,8,0,8,5,5,8,0,8]);sq.endFill();
    sq.position.set(14,13);p.addChild(sq);
    const t=txt(title,{size:11,font:'disp',color:C.steel,ls:2});t.position.set(28,11);p.addChild(t);
  }
  return p;
}

/* ── рисованный анимированный тумблер ── */
export class Toggle extends PIXI.Container{
  constructor(w,h,label,sub,getOn,onToggle){
    super();this.w=w;this.h=h;this.getOn=getOn;this.onToggle=onToggle;this.t=getOn()?1:0;this.hover=false;
    this.track=new PIXI.Graphics();this.knob=new PIXI.Graphics();
    this.track.addChild(this.knob);
    const lt=txt(label,{size:10,weight:700,color:C.ink});lt.position.set(0,sub?3:(h-12)/2);
    this.addChild(this.track,lt);this.label=lt;
    if(sub){const st=txt(sub,{size:8,color:C.faint});st.position.set(0,17);this.addChild(st);}
    this.trackX=w-46;this.trackY=(h-22)/2;this.track.position.set(this.trackX,this.trackY);
    this.eventMode='static';this.cursor='pointer';this.hitArea=new PIXI.Rectangle(0,0,w,h);
    this.on('pointerover',()=>this.hover=true);
    this.on('pointerout',()=>this.hover=false);
    this.on('pointerdown',()=>{if(this.onToggle)this.onToggle();});
    regAnim(this,dt=>{const tg=this.getOn()?1:0;this.t+=(tg-this.t)*Math.min(1,dt*12);this.paint();});
    this.paint();
  }
  paint(){
    const tr=this.track;tr.clear();
    tr.beginFill(lerpColor(0x2a3338,0xb87a10,this.t));tr.drawRoundedRect(0,0,44,22,11);tr.endFill();
    if(this.hover){tr.lineStyle(1.5,0xffe08a,.7);tr.drawRoundedRect(0,0,44,22,11);tr.lineStyle(0);}
    tr.beginFill(0x000000,.25);tr.drawRoundedRect(2,2,40,9,8);tr.endFill();
    const k=this.knob;k.clear();
    k.beginFill(0xffe6b0);k.drawCircle(0,0,8);k.endFill();
    k.lineStyle(1,0x8a6205);k.drawCircle(0,0,8);k.lineStyle(0);
    k.beginFill(0xffffff,.45);k.drawCircle(-2,-2,3);k.endFill();
    k.position.set(11+this.t*22,11);
  }
}

export class Card extends PIXI.Container{
  constructor(w,h,onClick){
    super();this.w=w;this.h=h;this.onClick=onClick;this.inScroll=false;
    this.inner=new PIXI.Container();this.addChild(this.inner);
    this.bg=new PIXI.Graphics();this.inner.addChild(this.bg);
    this.hover=false;this._ph=false;this.hoverT=0;this.shakeT=0;
    this.eventMode='static';this.cursor='pointer';this.hitArea=new PIXI.Rectangle(0,0,w,h);
    let dp=null;
    this.on('pointerover',()=>this.hover=true);
    this.on('pointerout',()=>this.hover=false);
    this.on('pointerdown',e=>{dp={x:e.global.x,y:e.global.y};input.uiHold=true});
    this.on('pointerup',e=>{
      const ok=dp&&Math.hypot(e.global.x-dp.x,e.global.y-dp.y)<8;dp=null;
      if(!ok||this.disabled||!this.onClick)return;
      if(this.inScroll&&store.GAR.scroll){
        const sp=store.GAR.scroll.getGlobalPosition();
        if(e.global.x<sp.x||e.global.x>sp.x+store.GAR.scroll.w||e.global.y<sp.y||e.global.y>sp.y+store.GAR.scroll.h)return}
      this.onClick()});
    regAnim(this,dt=>{
      const t=(this.hover&&!this.disabled)?1:0;
      this.hoverT+=(t-this.hoverT)*Math.min(1,dt*13);
      this.inner.y=-2.5*this.hoverT;
      if(this.shakeT>0){this.shakeT-=dt;this.inner.x=Math.sin(this.shakeT*50)*5*Math.max(0,this.shakeT)/.35}
      else if(this.inner.x)this.inner.x=0;
      if(this.hover!==this._ph){this._ph=this.hover;this.redraw()}
    });
  }
  shake(){this.shakeT=.35}
  redraw(){}
}
export class Btn extends Card{
  constructor(label,o={}){
    super(o.w||150,o.h||38,o.on||null);
    this.variant=o.variant||'default';
    this.label=txt(label,{size:o.fs||11,font:'disp',ls:1});
    this.label.anchor.set(.5);this.label.position.set(this.w/2,this.h/2+1);
    this.inner.addChild(this.label);this.redraw();
  }
  setLabel(s){this.label.text=s}
  setDisabled(d){this.disabled=d;this.eventMode=d?'none':'static';this.cursor=d?'default':'pointer';this.redraw()}
  redraw(){
    const g=this.bg;g.clear();
    let fill=0x242c30,stroke=0x3a4448,lc=C.ink;
    if(this.variant==='primary'){fill=0xd99414;stroke=0x8a6205;lc=0x1c1405}
    else if(this.variant==='danger'){fill=0x2a2124;stroke=0x5a3230;lc=0xe08a7c}
    if(this.disabled){fill=0x1a1f22;stroke=0x262e32;lc=0x5f6b66}
    cutPoly(g,this.w,this.h,8,fill,stroke);
    if(this.variant==='primary'&&!this.disabled){g.lineStyle(1,0xffffff,.28);g.moveTo(10,2.5);g.lineTo(this.w-2,2.5);g.lineStyle(0)}
    if(this.hover&&!this.disabled){g.lineStyle(1.5,this.variant==='danger'?C.red:C.amber,.95);g.drawPolygon(cutPts(this.w,this.h,8));g.lineStyle(0)}
    this.label.style.fill=lc;
  }
}
export class SlotCard extends Card{
  constructor(w,h,data,onClick){
    super(w,h,onClick);this.data=data;
    const catCol=CATCOL[data.cat]||0x9fb0ba;
    const cl=txt(data.catLabel||'',{size:7.5,weight:800,color:catCol,ls:1});cl.position.set(9,6);this.inner.addChild(cl);
    if(data.mod){
      const st=new PIXI.Graphics();st.beginFill(RCX[data.mod.r]||0x9fb0ba);st.drawRect(0,6,3,h-16);st.endFill();this.inner.addChild(st);
      const nm=txt(data.mod.name,{size:8.5,weight:700,wrap:w-18});nm.position.set(9,18);this.inner.addChild(nm);
      const sv=txt(data.stat||'',{size:8,color:C.dim});sv.position.set(9,h-17);this.inner.addChild(sv);
      const un=txt('снять ↩',{size:7,color:C.faint});un.anchor.set(1,0);un.position.set(w-7,6);this.inner.addChild(un);
    }else if(data.state==='locked'){
      const lk=new PIXI.Graphics();lk.lineStyle(2,0x8b968f,1);lk.arc(w/2,h*.30,4,Math.PI,0);lk.lineStyle(0);
      lk.beginFill(0x8b968f);lk.drawRoundedRect(w/2-5,h*.30,10,8,2);lk.endFill();this.inner.addChild(lk);
      const nm=txt(data.label||'',{size:9,weight:700,color:C.faint,wrap:w-12});nm.anchor.set(.5,0);nm.position.set(w/2,h*.46);this.inner.addChild(nm);
      const cs=txt(data.hint||'',{size:9.5,weight:800,color:C.cyan});cs.anchor.set(.5,0);cs.position.set(w/2,h*.70);this.inner.addChild(cs);
    }else{
      const nm=txt(data.label||'',{size:9,weight:700,color:C.faint});nm.anchor.set(.5,0);nm.position.set(w/2,h*.4);this.inner.addChild(nm);
      const hn=txt(data.hint||'',{size:8.5,color:C.faint});hn.anchor.set(.5,0);hn.position.set(w/2,h*.62);this.inner.addChild(hn);
    }
    this.redraw();
  }
  redraw(){
    const g=this.bg;g.clear();const d=this.data;
    cutPoly(g,this.w,this.h,6,0x141a1c,d.state==='filled'?0x46545a:0x3a464b);
    if(d.state!=='filled'&&!this.hover){
      g.lineStyle(1,0x3a464b,.9);const x=4,y=4,w=this.w-8,h=this.h-8;
      for(let i=0;i<w;i+=9){g.moveTo(x+i,y);g.lineTo(Math.min(x+i+5,x+w),y);g.moveTo(x+i,y+h);g.lineTo(Math.min(x+i+5,x+w),y+h)}
      for(let i=0;i<h;i+=9){g.moveTo(x,y+i);g.lineTo(x,Math.min(y+i+5,y+h));g.moveTo(x+w,y+i);g.lineTo(x+w,Math.min(y+i+5,y+h))}
      g.lineStyle(0)}
    if(this.hover){g.lineStyle(1.5,C.amber,.95);g.drawPolygon(cutPts(this.w,this.h,6));g.lineStyle(0)}
  }
}
export class ChipCard extends Card{
  constructor(id,count){
    const m=MODULES[id];const t=txt(m?m.name:'?',{size:9,weight:700});
    super(t.width+52,26,null);
    const dot=new PIXI.Graphics();dot.beginFill(CATCOL[m?m.cat:'hull']||0x9fb0ba);dot.drawRect(0,0,8,8);dot.endFill();
    dot.position.set(8,9);this.inner.addChild(dot);
    t.position.set(21,8);this.inner.addChild(t);
    const n=txt('×'+count,{size:10,weight:800,color:C.amber});n.position.set(t.width+27,7);this.inner.addChild(n);
    this.redraw();
  }
  redraw(){const g=this.bg;g.clear();cutPoly(g,this.w,this.h,5,0x161c1f,this.hover?C.amber:0x3a464b)}
}
export class FortCard extends Card{
  constructor(i,locked){
    super(88,80,null);
    this.i=i;this.sel=false;this.poor=false;this.locked=!!locked;
    const k=txt(String(i+1),{size:9,color:C.faint});k.position.set(7,5);this.inner.addChild(k);
    const nm=txt('',{size:10,font:'disp',ls:1});nm.anchor.set(.5,0);nm.position.set(44,20);this.inner.addChild(nm);this.nm=nm;
    this.costIcon=mkIcon('bolts',11);this.costIcon.position.set(0,40);this.inner.addChild(this.costIcon);   // position, НЕ anchor
    const cost=txt('',{size:10,weight:800});cost.anchor.set(0,0);this.inner.addChild(cost);this.cost=cost;
    const hp=txt('',{size:8.5,color:C.dim});hp.anchor.set(.5,0);hp.position.set(44,58);this.inner.addChild(hp);this.hpT=hp;
    if(this.locked){
      const lk=new PIXI.Graphics();
      lk.lineStyle(2,0x8b968f,1);lk.arc(44,66,4,Math.PI,0);lk.lineStyle(0);
      lk.beginFill(0x8b968f);lk.drawRoundedRect(39,66,10,8,2);lk.endFill();
      lk.beginFill(0x141a1c);lk.drawRect(43,68,2,4);lk.endFill();
      this.inner.addChild(lk);
    }
    this.redraw();
  }
  setFort(f){
    this.nm.text=f.name;
    this.cost.text=String(f.cost);
    this.cost.position.set(44,40);
    this.costIcon.position.set(44 - this.cost.width/2 - 14, 39.5);
    this.hpT.text=typeof f.hp==='number'?f.hp+' HP':f.hp;
    this.redraw();
  }
  redraw(){
    const g=this.bg;g.clear();
    cutPoly(g,this.w,this.h,7,0x1b2124,this.sel?C.amber:(this.hover?0x4d5a60:0x333d42));
    if(this.sel){g.beginFill(C.amber,.12);g.drawPolygon(cutPts(this.w,this.h,7));g.endFill()}
    this.nm.style.fill=this.locked?C.faint:(this.sel?C.amber:C.ink);
    this.cost.style.fill=this.locked?C.faint:(this.poor?C.red:C.amber);
    if(this.costIcon)this.costIcon.alpha=this.locked?.4:1;
  }
}
export class Bar extends PIXI.Container{
  constructor(w,h,color){
    super();this.w=w;this.h=h;this.val=1;this.disp=0;this.low=false;
    this.bg=new PIXI.Graphics();
    this.bg.beginFill(0x0d1113);this.bg.drawRect(0,0,w,h);this.bg.endFill();
    this.bg.lineStyle(1,0x2a3338);this.bg.drawRect(.5,.5,w-1,h-1);this.bg.lineStyle(0);
    this.fill=new PIXI.Graphics();
    this.fill.beginFill(color);this.fill.drawRect(0,0,w-2,h-2);this.fill.endFill();
    this.fill.beginFill(0xffffff,.16);this.fill.drawRect(0,0,w-2,2);this.fill.endFill();
    this.fill.position.set(1,1);
    this.seg=new PIXI.Graphics();this.seg.beginFill(0x000000,.45);
    for(let x=11;x<w-2;x+=12)this.seg.drawRect(x,0,1.5,h-2);
    this.seg.endFill();
    this.addChild(this.bg,this.fill,this.seg);
    regAnim(this,dt=>{
      this.disp+=(this.val-this.disp)*Math.min(1,dt*9);
      this.fill.scale.x=Math.max(.001,this.disp);
      this.fill.alpha=this.low?(.5+.5*Math.abs(Math.sin(globalThis.__t||0)*7)):1;
    });
  }
  set(v){this.val=Math.max(0,Math.min(1,v))}
}
export class Scroll extends PIXI.Container{
  constructor(w,h){
    super();this.w=w;this.h=h;
    this.content=new PIXI.Container();this.addChild(this.content);
    this.maskG=new PIXI.Graphics();this.maskG.beginFill(0xffffff);this.maskG.drawRect(0,0,w,h);this.maskG.endFill();
    this.addChild(this.maskG);this.content.mask=this.maskG;
    this.scrollY=0;this.targetY=0;this.contentH=h;
    this.drag=false;this.dragPending=false;this.dragY=0;this.dragS=0;this.dragX=0;
    this.eventMode='static';this.hitArea=new PIXI.Rectangle(0,0,w,h);
    this.on('pointerdown',e=>{this.dragPending=true;this.drag=false;this.dragY=e.global.y;this.dragX=e.global.x;this.dragS=this.targetY});
    this.sb=new PIXI.Graphics();this.addChild(this.sb);
    regAnim(this,dt=>this.tick(dt));
  }
  layout(ch){this.contentH=Math.max(this.h,ch);this.clampT()}
  clampT(){const max=Math.max(0,this.contentH-this.h);this.targetY=Math.max(-max,Math.min(0,this.targetY))}
  wheel(dy){this.targetY-=dy*.9;this.clampT()}
  tick(dt){
    this.scrollY+=(this.targetY-this.scrollY)*Math.min(1,dt*11);
    this.content.y=Math.round(this.scrollY*10)/10;
    const sb=this.sb;sb.clear();
    if(this.contentH>this.h+4){
      const th=Math.max(30,this.h*this.h/this.contentH);
      const y=(-this.scrollY/(this.contentH-this.h))*(this.h-th);
      sb.beginFill(0x2c363b,.9);sb.drawRoundedRect(this.w-5,y,4,th,2);sb.endFill();
    }
  }
}