/* ближайшая свободная клетка по спирали; вернёт {x,y} в пикселях центра или null */
function findFreeCell(px,py,radius){
  const cgx=Math.floor(px/CELL),cgy=Math.floor(py/CELL);
  const busy=(gx,gy)=>{
    if(gx<0||gx>=37||gy<0||gy>=26)return true;
    const tl=tiles.get(gx+','+gy); if(tl&&SOLID.has(tl.t))return true;
    const cx=gx*CELL+CELL/2,cy=gy*CELL+CELL/2;
    if(hitsTank(cx,cy,40,null))return true;
    return false;
  };
  for(let r=1;r<=radius;r++){
    for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){
      if(Math.max(Math.abs(dx),Math.abs(dy))!==r)continue;
      const gx=cgx+dx,gy=cgy+dy;
      if(!busy(gx,gy))return{x:gx*CELL+CELL/2,y:gy*CELL+CELL/2};
    }
  }
  return null;
}

export function damagePlayer(d,sx,sy){
  const p=store.B.player;
  if(p.invuln>0||store.B.over)return;
  p.hp-=d;p.invuln=1.5;p.hullFlash=.2;
  if(sx!==undefined){const dx=p.x-sx,dy=p.y-sy,l=Math.hypot(dx,dy)||1;p.vx=(p.vx||0)+dx/l*150;p.vy=(p.vy||0)+dy/l*150;}
  store.B.shake=Math.min(16,store.B.shake+4);
  store.uiState.flashA=1;AudioFX.hit();
  if(p.hp<=0){p.hp=0;playerDeath()}
}
export function playerDeath(){
  const B=store.B;B.over=true;
  explosion(BORDER+B.player.x,BORDER+B.player.y,34,true);
  B.vis.container.visible=false;
  log('КОРПУС РАЗРУШЕН · МАШИНА ПОТЕРЯНА','bad');
  emit('announce',{main:'КОРПУС РАЗРУШЕН',cls:'boss',hold:2.4});
  emit('battle:over',{reason:'player',delay:1500});
}
export function toggleTrance(){
  const p=store.B.player;if(store.B.over)return;
  if(p.trance){p.trance=false;log('ТРАНС ПРЕРВАН','info')}
  else if(p.tranceE>20){p.trance=true;log('БОЕВОЙ ТРАНС · ВРЕМЯ ЗАМЕДЛЕНО','good');AudioFX.trance()}
  else{toast('НЕДОСТАТОЧНО ЭНЕРГИИ');AudioFX.err()}
}
/* РЫВОК [T] — прыжок вперёд по курсу; требует модуль двигателя с dash */
export function dash(){
  const B=store.B,p=B.player;if(B.over)return;
  if(!B.stats.canDash){toast('НУЖЕН ПРЫЖКОВЫЙ ПРИВОД');AudioFX.err();return}
  if(p.dashCd>0){toast('РЫВОК: '+Math.ceil(p.dashCd)+'С');AudioFX.err();return}
  for(const d of [2,1]){
    const tx=p.x+DX[p.dir]*CELL*d,ty=p.y+DY[p.dir]*CELL*d;
    if(tx>=TS/2&&tx<=FIELD_W-TS/2&&ty>=TS/2&&ty<=FIELD_H-TS/2&&
       !rectHitsSolid(tx,ty,TS)&&!hitsTank(tx,ty,44,null)){
      for(let s=1;s<=d;s++)part({x:BORDER+p.x+DX[p.dir]*CELL*s,y:BORDER+p.y+DY[p.dir]*CELL*s,
        vx:0,vy:0,life:.3,color:0x79c7d4,size:8,shape:'circle'});
      p.x=tx;p.y=ty;p.invuln=Math.max(p.invuln,.5);p.dashCd=4;
      log('РЫВОК','warn');AudioFX.dash();B.shake+=3;return}
  }
  toast('РЫВОК НЕВОЗМОЖЕН — ПЕРЕД МАШИНОЙ СТЕНА');AudioFX.err();
}
/* ВЫБРАТЬСЯ [R] — телепорт в свободную клетку рядом (вытаскивает из зажима) */
export function unstuck(){
  const B=store.B,p=B.player;if(B.over)return;
  if(p.unstuckCd>0){toast('ВЫБРАТЬСЯ: '+Math.ceil(p.unstuckCd)+'С');AudioFX.err();return}
  const t=findFreeCell(p.x,p.y,4);
  if(!t){toast('НЕКУДА ВЫБРАТЬСЯ');AudioFX.err();return}
  part({x:BORDER+p.x,y:BORDER+p.y,vx:0,vy:0,life:.3,color:0x79c7d4,size:16,shape:'ring',grow:1.4});
  p.x=t.x;p.y=t.y;p.invuln=Math.max(p.invuln,.6);p.unstuckCd=12;
  part({x:BORDER+p.x,y:BORDER+p.y,vx:0,vy:0,life:.3,color:0x79c7d4,size:16,shape:'ring',grow:1.4});
  log('АВАРИЙНЫЙ ВЫХОД ИЗ ЗАЖИМА','warn');AudioFX.dash();B.shake+=2;
}

/* ── пылевой след: свой характер под каждый тип ходовой ──
   gw/hl — полуширина и полувысота точек контакта (усреднены по корпусам),
   perTick/interval — плотность, spread/back — разлёт назад и вбок,
   rectChance — доля «камешков» (квадраты без клубления) */
const DUST={
 gear_tracks :{gw:22,hl:21,perTick:2,interval:.055,colors:[0x6a6258,0x7d7468,0x574f46],spread:.7, back:.55,grow:1.4,lifeMin:.32,lifeMax:.55,sizeMin:2.5,sizeMax:4.5,drag:2.6,rectChance:0},
 gear_wide   :{gw:25,hl:21,perTick:3,interval:.050,colors:[0x5a5249,0x6e655a,0x48413a],spread:.9, back:.60,grow:1.7,lifeMin:.35,lifeMax:.60,sizeMin:3.0,sizeMax:5.5,drag:2.4,rectChance:0},
 gear_wheels :{gw:19,hl:19,perTick:2,interval:.050,colors:[0x9a9082,0xb0a692,0x837a6c],spread:1.7,back:1.10,grow:1.0,lifeMin:.22,lifeMax:.42,sizeMin:2.0,sizeMax:3.5,drag:3.2,rectChance:.35},
 gear_rollers:{gw:19,hl:19,perTick:1,interval:.070,colors:[0x7a7268,0x8c8478,0x6a6258],spread:.6, back:.50,grow:1.2,lifeMin:.30,lifeMax:.50,sizeMin:2.5,sizeMax:4.0,drag:2.8,rectChance:.10},
};
/* puffDust теперь импортируется из tracks.js — локальная копия удалена */

export function updPlayer(dt){
  const B=store.B,p=B.player,stc=B.stats;
  if(B._playerHit){const h=B._playerHit;B._playerHit=null;damagePlayer(h.d,h.sx,h.sy);}
  p.invuln=Math.max(0,p.invuln-dt);
  p.unstuckCd=Math.max(0,p.unstuckCd-dt);
  // p.invuln=Math.max(0,p.invuln-dt);
  // p.unstuckCd=Math.max(0,p.unstuckCd-dt);
  p.dashCd=Math.max(0,p.dashCd-dt);
  p.hullFlash=Math.max(0,p.hullFlash-dt);
  if(p.trance){p.tranceE-=26*dt;if(p.tranceE<=0){p.tranceE=0;p.trance=false;log('ТРАНС ИСЧЕРПАН','warn')}}
  else p.tranceE=Math.min(stc.tranceMax,p.tranceE+stc.tranceReg*dt);
  B.tsTarget=p.trance?.35:1;
  B.timeScale+=(B.tsTarget-B.timeScale)*Math.min(1,dt*7);
  let moved=0;
  if(!B.over){
    const keys=input.keys;
    let nd=-1;
    if(keys.KeyW)nd=0;else if(keys.KeyD)nd=1;else if(keys.KeyS)nd=2;else if(keys.KeyA)nd=3;
    if(nd>=0&&nd!==p.dir){
      if(p.dir%2!==nd%2){
        if(nd%2===0)p.x=Math.round((p.x-CELL/2)/CELL)*CELL+CELL/2;
        else p.y=Math.round((p.y-CELL/2)/CELL)*CELL+CELL/2}
      p.dir=nd;B.vis.container.rotation=nd*Math.PI/2}
    if(nd>=0){
      const sp=p.speed*CELL;
      const nx=p.x+DX[p.dir]*sp*dt,ny=p.y+DY[p.dir]*sp*dt;
      if(!rectHitsSolid(nx,ny,TS)&&!hitsTank(nx,ny,TANK_SEP,B.player)&&
         nx>=TS/2&&nx<=FIELD_W-TS/2&&ny>=TS/2&&ny<=FIELD_H-TS/2){p.x=nx;p.y=ny}
      moved=sp*dt;
    }
    // const firing=(keys.Space||input.mouse.down)&&!input.uiHold;
    const firing=(keys.Space||(input.mouse.down&&!input.touchDevice))&&!input.uiHold;
    B.tank.turrets.forEach(t=>{
      t.cd-=dt;
      if(t.rel>0){t.rel-=dt;if(t.rel<=0){t.clip=t.def.clip;AudioFX.reload()}}
      if(firing&&t.cd<=0&&t.rel<=0&&t.clip>0&&countPB()<2){
        t.cd=1/t.def.rate;t.clip--;
        if(t.clip===0)t.rel=t.def.rld;
        firePlayerBullet(t);
        AudioFX.shot(t.def.id);
        B.shake=Math.min(16,B.shake+.3)}
    });
    if(stc.dHeal>0){B.healT-=dt;
      if(B.healT<=0){B.healT=10/(stc.dHeal/2); //  частота лечения
        if(p.hp<p.maxHp){p.hp=Math.min(p.maxHp,p.hp+1);
          part({x:BORDER+p.x,y:BORDER+p.y,vx:0,vy:0,life:.4,color:0x6fc37a,size:14,shape:'ring',grow:1.5});
          AudioFX.tone(660,.1,'sine',.06,200)}}}
    if(stc.dAtk>0){B.atkT-=dt;
      if(B.atkT<=0){B.atkT=1.6/(stc.dAtk/2);
        const e=nearestEnemy2(p.x,p.y,5.5*CELL);
        if(e){const a=Math.atan2(e.y-p.y,e.x-p.x);
          pushBullet({x:p.x+Math.cos(a)*16,y:p.y+Math.sin(a)*16,
            vx:Math.cos(a)*8*CELL,vy:Math.sin(a)*8*CELL,dmg:1,life:.9,friendly:true,gi:98});
          AudioFX.tone(1200,.04,'square',.03,-600)}}}
    if(stc.mortars>0){B.mortT-=dt;
      if(B.mortT<=0){B.mortT=3.2/stc.mortars;
        const e=nearestEnemy2(p.x,p.y,9*CELL);
        if(e){const d=Math.hypot(e.x-p.x,e.y-p.y),a=Math.atan2(e.y-p.y,e.x-p.x),sp2=4.5*CELL;
          const lf=Math.min(2,d/sp2);
          pushBullet({x:p.x,y:p.y,vx:Math.cos(a)*sp2,vy:Math.sin(a)*sp2,dmg:2,life:lf,maxLife:lf,
            friendly:true,gi:97,mortar:true,splash:52});
          AudioFX.tone(240,.18,'sine',.1,-140)}}}
    /* пыль из-под шасси — сыплем только в движении, с двух задних точек контакта */
    const gearId=store.S.loadout.gear||'gear_tracks';
    const dcfg=DUST[gearId]||DUST.gear_tracks;
    B.dustT=(B.dustT||0)-dt;
    if(moved>0.1 && B.dustT<=0){
      B.dustT=dcfg.interval;
      const th=p.dir*Math.PI/2, c=Math.cos(th), s=Math.sin(th);
      const contacts=[[-dcfg.gw,dcfg.hl],[dcfg.gw,dcfg.hl]];
      for(let ci=0;ci<contacts.length;ci++){
        const lx=contacts[ci][0], ly=contacts[ci][1];
        const wx=BORDER+p.x+(lx*c-ly*s);   // поворот локальной точки в мир
        const wy=BORDER+p.y+(lx*s+ly*c);
        puffDust(wx,wy,p.dir,dcfg);
      }
    }
    p.moved=moved;   // ← следы на земле читают это в tracks.js
    if(store.S.loadout.engine==='eng_turbo'&&moved>0){
      B.smokeT-=dt;
      if(B.smokeT<=0){B.smokeT=.14;
        const rx=p.x-DX[p.dir]*(B.vis.hl+6),ry=p.y-DY[p.dir]*(B.vis.hl+6);
        part({x:BORDER+rx,y:BORDER+ry,vx:-DX[p.dir]*30+rnd(-15,15),vy:-DY[p.dir]*30+rnd(-15,15),
          life:.5,color:0x6a7278,size:4,shape:'circle',grow:1.8,drag:1})}}
    B.vis.container.position.set(BORDER+p.x,BORDER+p.y);
    B.vis.container.alpha=p.invuln>0?(Math.sin(B.time*30)>0?.5:1):1;
    B.vis.body.tint=p.hullFlash>0?0xff9a8a:0xffffff;
  }
  tankFx(B.vis,dt,B.time,moved);
}