import { clone } from '../utils/helpers.js';

// export const DEF={bolts:120,boxes:1,gears:0,record:0,sound:true,
export const DEF={bolts:120,boxes:1,gears:0,record:0,sound:true,music:true,
  inv:{hull_light:1,gun_short:1,gear_wheels:1},
  loadout:{hull:'hull_medium',gun:'gun_single',aux1:'aux_eng',aux2:null,engine:'eng_base',gear:'gear_tracks',optics:null,power:null}};

const KEY='stalnoi_rubezh_pixi_v4';

function loadSave(){
  try{const d=JSON.parse(localStorage.getItem(KEY));
    if(d&&d.loadout){const s=clone(DEF);Object.assign(s,d);
      s.loadout=Object.assign(clone(DEF.loadout),d.loadout);s.inv=d.inv||{};return s}}catch(e){}
  try{const o=JSON.parse(localStorage.getItem('stalnoi_rubezh_pixi_v3'));
    if(o){const s=clone(DEF);
      s.bolts=o.bolts!=null?o.bolts:120;s.boxes=o.boxes!=null?o.boxes:1;
      s.gears=o.gears||0;s.record=o.record||0;s.sound=o.sound!==false;return s}}catch(e){}
  return null;
}

export const store={
  S:loadSave()||clone(DEF),
  B:null,
  mode:'garage',
  uiState:{modal:null,results:null,log:[],ann:null,flashA:0,saveT:0,toastMsg:'',toastT:0},
  GAR:{},
  HUD:{},
};

export function save(){
  try{localStorage.setItem(KEY,JSON.stringify(store.S))}catch(e){}
  store.uiState.saveT=1;
}
export function resetProgress(){
  localStorage.removeItem(KEY);
  store.S=clone(DEF);
  save();
}